insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check, reviewer_notes) values
(2219, null, null, null, 'النموذج: أيونات فلزية موجبة مرتبة بانتظام في الشبكة البلورية، تملأ الفراغات بينها إلكترونات التكافؤ غير المتمركزة التي لا ترتبط بذرة معينة وتتحرك بحرية في كل الفلز (بحر من الإلكترونات). عند توصيل الفلز بالبطارية: تنجذب الإلكترونات الحرة نحو القطب الموجب وتتحرك خلال الفلز بانتظام، بينما تدخل إلكترونات من القطب السالب، فيسري تيار كهربائي، وتبقى الأيونات الموجبة في مواقعها.', '["أيونات موجبة مرتبة بانتظام","إلكترونات تكافؤ غير متمركزة حرة الحركة بينها","حركة الإلكترونات نحو القطب الموجب عند تطبيق فرق الجهد","بقاء الأيونات الموجبة في مواقعها"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الأيونات الموجبة","marks":1},{"element":"وصف بحر الإلكترونات","marks":1},{"element":"حركة الإلكترونات وسريان التيار","marks":1},{"element":"الأيونات تبقى ثابتة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نموذج صحيح وتفسير كامل لسريان التيار"},{"level":"3 درجات","description":"نموذج صحيح مع تفسير ناقص"},{"level":"2 درجتان","description":"نموذج صحيح دون تفسير"},{"level":"1 درجة","description":"ذكر الإلكترونات الحرة فقط"},{"level":"صفر","description":"نموذج خاطئ (أيونات سالبة أو جزيئات)"}]'::jsonb, '["رسم أيونات سالبة بين الأيونات الموجبة","القول إن الأيونات الموجبة تتحرك نحو القطب السالب في الفلز الصلب","إغفال بقاء الأيونات في مواقعها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.311Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2220, null, null, null, 'Cu وAl صلبان فلزيان يحتويان أيونات موجبة في بحر من الإلكترونات الحرة الحركة، فتنقل الإلكترونات الشحنة وتوصل جيدًا. السكر صلب جزيئي من جزيئات متعادلة لا تحوي شحنات حرة فهو رديء التوصيل. KBr صلب أيوني أيوناته مقيدة في مواقعها ولا توجد فيه إلكترونات حرة، فهو رديء التوصيل وهو صلب. الاستنتاج: لكي توصل المادة الصلبة الكهرباء يجب أن تحتوي جسيمات مشحونة حرة الحركة، وهي في الفلزات الإلكترونات الحرة.', '["تفسير توصيل Cu وAl بالإلكترونات الحرة","تفسير رداءة السكر (جزيئات متعادلة)","تفسير رداءة KBr الصلب (أيونات مقيدة)","الاستنتاج: الحاجة إلى جسيمات مشحونة حرة الحركة"]'::jsonb, '[]'::jsonb, '[{"element":"الفلزان","marks":2},{"element":"السكر","marks":1},{"element":"KBr","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل صحيح للمواد الأربع مع الاستنتاج"},{"level":"3–4 درجات","description":"تحليل صحيح لمعظم المواد مع استنتاج ناقص"},{"level":"1–2 درجة","description":"تفسير الفلزات فقط"},{"level":"صفر","description":"تحليل خاطئ"}]'::jsonb, '["تفسير رداءة KBr بأنه لا يحتوي أيونات","عدّ السكر أيونيًا","استنتاج أن كل المواد الصلبة القاسية موصلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:23.312Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2221, 1, 'إضافة الطاقة تزيد الطاقة الحركية للجسيمات (اهتزازها)، فإذا أصبحت كافية للتغلب على قوى التجاذب التي تثبتها في مواقعها تحولت المادة إلى سائل.', '["هذا ما يحدث عند انتزاع الطاقة لا عند إضافتها.","","حجم الجسيمات لا يتغير بالتسخين؛ الذي يتغير طاقتها الحركية والمسافات بينها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:23.315Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2222, 2, 'الانصهار والتبخر والتسامي تحتاج إلى امتصاص حرارة لتتغلب الجسيمات على قوى التجاذب، فهي تغيرات ماصة للطاقة.', '["هذه كلها تغيرات طاردة للطاقة (تطلق حرارة).","التكثف تغير طارد للطاقة، فالمجموعة ليست كلها ماصة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.315Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2223, 0, 'أثناء الانصهار تُستهلك الطاقة المضافة في التغلب على قوى التجاذب بين الجزيئات لا في زيادة طاقتها الحركية، لذا تبقى درجة الحرارة ثابتة عند 0 °C حتى ينصهر الجليد كله.', '["","التسخين مستمر بمعدل ثابت بحسب المعطيات، فالطاقة تُضاف فعلًا.","الانصهار تغير ماص للطاقة، فالجليد يمتص الطاقة ولا يطلقها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.317Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2224, 1, 'بانتزاع الطاقة تقل الطاقة الحركية فيتكثف البخار إلى سائل عند 100 °C، ثم يتجمد السائل إلى جليد عند 0 °C، فيصل إلى الحالة الصلبة عند −5 °C.', '["لا يتحول الصلب إلى سائل بانتزاع الطاقة؛ هذا يحتاج إلى إضافة طاقة.","","العينة تبدأ غازًا لا سائلًا، وانتزاع الطاقة لا يحول السائل إلى غاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.318Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2225, 2, 'التجمد تغير طارد للطاقة: يفقد الماء طاقة إلى المحيط الأبرد فتقل الطاقة الحركية لجسيماته وتتمكن قوى التجاذب من تثبيتها في مواقع منتظمة.', '["البرودة ليست شيئًا ينتقل؛ الذي ينتقل هو الطاقة من الماء إلى المجمد.","امتصاص الطاقة يزيد حركة الجسيمات ولا يثبتها؛ هذا مفهوم خاطئ شائع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:23.318Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2226, 0, 'التكثف تغير طارد للطاقة، والترسيب (تحول الغاز إلى صلب مباشرة) طارد للطاقة أيضًا، فكلاهما يطلق طاقة إلى المحيط.', '["","التسامي ماص للطاقة، فهو عكس التكثف في اتجاه انتقال الطاقة.","التبخر ماص للطاقة، وهو عكس التكثف تمامًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.318Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2227, 1, 'الانصهار تغير ماص للطاقة، فالجليد يمتص الطاقة الحرارية من اليد؛ فقدان اليد لهذه الطاقة هو سبب الإحساس بالبرودة.', '["البرودة ليست طاقة تنتقل؛ الطاقة تنتقل من الأسخن (اليد) إلى الأبرد (الجليد).","","الجليد يمتص الطاقة عند انصهاره ولا يطلقها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:23.318Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2228, null, null, null, 'عند إضافة الطاقة إلى الجليد تزداد الطاقة الحركية (الاهتزازية) لجزيئاته، وعندما تصبح كافية للتغلب على قوى التجاذب التي تثبتها في مواقعها في الشبكة البلورية تتحرك الجزيئات بعضها فوق بعض فينصهر الجليد إلى ماء. ومع استمرار التسخين تزداد الطاقة الحركية لجزيئات الماء حتى تتغلب تمامًا على قوى التجاذب فتفلت إلى الحالة الغازية فيتبخر الماء. وكلا التغيرين ماص للطاقة.', '["إضافة الطاقة تزيد الطاقة الحركية للجزيئات","الانصهار يحدث عند التغلب على قوى التجاذب التي تثبت الجزيئات في مواقعها","التبخر يحدث عند تغلب الجزيئات تمامًا على قوى التجاذب وإفلاتها","التغيران ماصان للطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"زيادة الطاقة الحركية بإضافة الطاقة","marks":1},{"element":"تفسير الانصهار","marks":1},{"element":"تفسير التبخر","marks":1},{"element":"تحديد أن التغيرين ماصان للطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن حجم الجزيئات يكبر بالتسخين","إهمال دور قوى التجاذب في التفسير","وصف التغيرين بأنهما طاردان للطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.319Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2229, null, null, null, 'التغيرات الماصة للطاقة (تحتاج حرارة): الانصهار (صلب ← سائل)، والتبخر (سائل ← غاز)، والتسامي (صلب ← غاز). التغيرات الطاردة للطاقة (تطلق حرارة): التجمد (سائل ← صلب)، والتكثف (غاز ← سائل)، والترسيب (غاز ← صلب). وكل تغير طارد هو عكس تغير ماص: التجمد عكس الانصهار، والتكثف عكس التبخر، والترسيب عكس التسامي.', '["الماصة: الانصهار والتبخر والتسامي","الطاردة: التجمد والتكثف والترسيب","الأزواج المتعاكسة: انصهار/تجمد، تبخر/تكثف، تسامي/ترسيب"]'::jsonb, '[]'::jsonb, '[{"element":"التغيرات الماصة الثلاثة","marks":2},{"element":"التغيرات الطاردة الثلاثة","marks":2},{"element":"الأزواج المتعاكسة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف كامل صحيح مع الأزواج الثلاثة"},{"level":"4–5 درجات","description":"تصنيف صحيح مع خطأ في زوج أو تغير واحد"},{"level":"2–3 درجات","description":"تصنيف إحدى المجموعتين فقط صحيحًا"},{"level":"1 درجة","description":"تغير واحد أو اثنان مصنفان صحيحًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد التجمد ماصًا للطاقة لارتباطه بالبرودة","جعل الترسيب عكس التبخر بدل التسامي","الخلط بين التسامي والترسيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:23.319Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2230, null, null, null, 'عند 100 °C يبدأ الماء بالغليان (تغير ماص للطاقة). تُستهلك الطاقة المضافة في هذه المدة في التغلب على قوى التجاذب بين جزيئات الماء لتفلت إلى الحالة الغازية، لا في زيادة طاقتها الحركية المتوسطة، لذلك تبقى درجة الحرارة ثابتة حتى يتحول الماء كله إلى بخار، ثم ترتفع درجة حرارة البخار بعد ذلك.', '["ثبات درجة الحرارة أثناء تغير الحالة","الطاقة تُستهلك في التغلب على قوى التجاذب","لا تزداد الطاقة الحركية المتوسطة (درجة الحرارة) أثناء الغليان"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن الماء يغلي (تغير حالة) عند 100 °C","marks":1},{"element":"الطاقة تُستهلك في التغلب على قوى التجاذب","marks":1},{"element":"ربط ذلك بعدم تغير الطاقة الحركية المتوسطة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء توقف عن امتصاص الحرارة","الاعتقاد أن درجة الحرارة ترتفع أثناء الغليان","إغفال شرط ثبات الضغط والمادة النقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.319Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2231, 0, 'الانصهار هو تحول المادة من الحالة الصلبة إلى الحالة السائلة عند امتصاصها كمية كافية من الطاقة الحرارية.', '["","هذا تعريف التجمد، وهو عكس الانصهار.","هذا تعريف التسامي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:23.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2232, 1, 'تحول الجليد (صلب) إلى ماء (سائل) هو انصهار.', '["هذا تكثف (غاز ← سائل).","","هذا تسامي (صلب ← غاز مباشرة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2233, 2, 'يحتاج الانصهار إلى امتصاص حرارة لتتغلب الجسيمات على قوى التجاذب التي تثبتها، فهو تغير ماص للطاقة.', '["التغير الطارد هو التجمد عكس الانصهار.","كل تغير حالة يصاحبه انتقال للطاقة امتصاصًا أو انطلاقًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2234, 0, 'أثناء الانصهار تزداد اهتزازات الجسيمات حتى تتغلب على قوى التجاذب التي تثبتها في مواقعها في الشبكة البلورية، فتتحرر من مواقعها الثابتة وتنزلق بعضها فوق بعض كما في السائل.', '["","الإفلات التام والانتشار في الوعاء يصف الحالة الغازية لا السائلة.","نقص الاهتزاز وزيادة الانتظام يصف التجمد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:23.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2235, 1, 'المادة (ب) تحولت من صلب إلى سائل، وهذا هو الانصهار.', '["المادة (أ) تحولت من سائل إلى غاز، وهذا تبخر.","","المادة (ج) تحولت من صلب إلى غاز مباشرة، وهذا تسامٍ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2236, 2, 'الانصهار صلب ← سائل، وعكسه تحول السائل إلى صلب وهو التجمد.', '["التكثف عكس التبخر (غاز ← سائل).","التسامي صلب ← غاز، وعكسه الترسيب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.323Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2237, 0, 'تحول الزبدة من صلب إلى سائل انصهار، وقد حدث لأنها امتصت طاقة حرارية من الهواء الأسخن منها.', '["","التجمد تحول السائل إلى صلب ويصاحبه فقد طاقة، وهو عكس ما حدث.","التسامي تحول إلى غاز مباشرة، والزبدة صارت سائلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.324Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2238, null, null, null, 'الانصهار هو تحول المادة من الحالة الصلبة إلى الحالة السائلة عند امتصاصها كمية كافية من الطاقة الحرارية. وهو تغير ماص للطاقة. مثاله: انصهار مكعبات الجليد إلى ماء، أو انصهار الشمع أو الزبدة عند تسخينهما.', '["التعريف: تحول الصلب إلى سائل","تغير ماص للطاقة","مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"نوعه من حيث الطاقة","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الانصهار والذوبان (ذوبان السكر في الماء)","وصفه بأنه طارد للطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.324Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2239, null, null, null, 'في المادة الصلبة البلورية تهتز الجسيمات حول مواقع ثابتة في الشبكة البلورية بفعل قوى التجاذب. عند امتصاص الطاقة الحرارية تزداد اهتزازات الجسيمات (طاقتها الحركية)، وعندما تصبح قوية بما يكفي للتغلب على قوى التجاذب التي تثبتها تتحرر من مواقعها وتنزلق بعضها فوق بعض، فتتحول المادة إلى سائل.', '["الجسيمات في الصلب تهتز حول مواقع ثابتة","امتصاص الطاقة يزيد الاهتزازات","التغلب على قوى التجاذب","الجسيمات تنزلق بعضها فوق بعض (سائل)"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الحالة الصلبة","marks":1},{"element":"زيادة الاهتزازات بامتصاص الطاقة","marks":1},{"element":"التغلب على قوى التجاذب","marks":1},{"element":"وصف الناتج السائل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجسيمات تنتشر تمامًا كالغاز","القول إن الجسيمات تتمدد أو يكبر حجمها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:23.324Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2240, null, null, null, 'الانصهار: الحالة الابتدائية صلبة والنهائية سائلة، والمادة تمتص الطاقة (ماص). التجمد: الحالة الابتدائية سائلة والنهائية صلبة، والمادة تطلق الطاقة إلى المحيط (طارد). فهما تغيران متعاكسان.', '["الانصهار صلب ← سائل","التجمد سائل ← صلب","الانصهار ماص والتجمد طارد"]'::jsonb, '[]'::jsonb, '[{"element":"حالتا الانصهار","marks":1},{"element":"حالتا التجمد","marks":1},{"element":"اتجاه الطاقة في كل منهما","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس اتجاه الطاقة","القول إن التجمد يمتص البرودة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.324Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2241, 1, 'التبخر هو تحول المادة من الحالة السائلة إلى الحالة الغازية (البخار) عند امتصاصها طاقة كافية.', '["هذا تعريف التكثف.","","هذا تعريف التسامي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.327Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2242, 0, 'يحتاج التبخر إلى امتصاص طاقة لتتغلب جزيئات السائل على قوى التجاذب وتفلت إلى الحالة الغازية.', '["","الطارد للطاقة هو التكثف عكس التبخر.","تغيرات الحالة كلها يصاحبها انتقال طاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.328Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2243, 2, 'الغليان نوع من التبخر يحدث في جميع أجزاء السائل، أما التبخر السطحي فيحدث عند السطح فقط.', '["التبخر السطحي يحدث عند سطح السائل فقط.","التكثف ليس نوعًا من التبخر بل عكسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.328Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2244, 0, 'يتبخر الجزيء عندما يمتلك طاقة كافية للتغلب على قوى التجاذب مع الجزيئات المجاورة فيفلت إلى الحالة الغازية، وقد يحدث ذلك دون بلوغ درجة الغليان.', '["","التبخر يحدث عند درجات أقل من الغليان أيضًا (التبخر السطحي)؛ هذا مفهوم خاطئ شائع.","فقد الطاقة يؤدي إلى التكثف لا التبخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:23.328Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2245, 2, 'جفاف الأرض يعني تحول الماء السائل إلى بخار، وهو تبخر.', '["الصقيع ترسيب (غاز ← صلب).","هذا تجمد (سائل ← صلب).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.328Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2246, 0, 'الكتلة المفقودة (المتبخرة) ازدادت من 2 g عند 20 °C إلى 9 g عند 60 °C، فارتفاع درجة الحرارة يزيد معدل التبخر. كما أن الماء فقد كتلة عند درجات أقل من 100 °C، فالتبخر يحدث دون الغليان.', '["","العينات تبخرت عند 20 و40 و60 °C، وكلها أقل من درجة الغليان.","البيانات تُظهر عكس ذلك؛ الكتلة المفقودة تزداد بارتفاع الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:23.329Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2247, 1, 'التبخر سائل ← غاز، وعكسه غاز ← سائل وهو التكثف.', '["الترسيب غاز ← صلب، وهو عكس التسامي.","","الانصهار صلب ← سائل، وعكسه التجمد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.329Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2248, null, null, null, 'التبخر هو تحول المادة من الحالة السائلة إلى الحالة الغازية (البخار) عند امتصاصها طاقة كافية تمكن جسيماتها من التغلب على قوى التجاذب. وله نوعان: التبخر السطحي الذي يحدث عند سطح السائل فقط وعند درجات حرارة أقل من درجة الغليان، والغليان الذي يحدث في جميع أجزاء السائل عند درجة الغليان.', '["تعريف التبخر","التبخر السطحي: عند السطح فقط","الغليان: في جميع أجزاء السائل"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"التبخر السطحي","marks":1},{"element":"الغليان والفرق بينهما","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن التبخر لا يحدث إلا عند الغليان","الخلط بين التبخر والتكثف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.329Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2249, null, null, null, 'ترتبط جزيئات السائل بعضها ببعض بقوى تجاذب. ولكي يتحول الجزيء إلى الحالة الغازية يجب أن يتغلب على هذه القوى ويبتعد عن الجزيئات المجاورة، وهذا يتطلب طاقة يمتصها من المحيط فتزداد طاقته الحركية حتى يفلت. لذلك يحتاج التبخر إلى امتصاص طاقة فهو تغير ماص للطاقة.', '["وجود قوى تجاذب بين جزيئات السائل","التغلب عليها يحتاج طاقة","الطاقة تُمتص من المحيط فالتغير ماص"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر قوى التجاذب","marks":1},{"element":"الحاجة إلى طاقة للتغلب عليها","marks":1},{"element":"الاستنتاج: ماص للطاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجزيئات تطلق طاقة عند الإفلات","إغفال قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.329Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2250, null, null, null, 'يجف المنديل الموضوع في الشمس أسرع. لأن درجة حرارته أعلى، فيمتلك عدد أكبر من جزيئات الماء طاقة حركية كافية للتغلب على قوى التجاذب والإفلات إلى الحالة الغازية، فيزداد معدل التبخر.', '["التوقع: المنديل في الشمس يجف أسرع","ارتفاع درجة الحرارة يزيد الطاقة الحركية للجزيئات","عدد أكبر من الجزيئات يتبخر فيزداد معدل التبخر"]'::jsonb, '[]'::jsonb, '[{"element":"التوقع الصحيح","marks":1},{"element":"ربط الحرارة بالطاقة الحركية","marks":1},{"element":"تفسير زيادة معدل التبخر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء في الظل لا يتبخر إطلاقًا","القول إن الماء في الشمس يغلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T13:13:23.329Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2251, 2, 'التسامي هو تحول المادة من الحالة الصلبة إلى الحالة الغازية مباشرة دون المرور بالحالة السائلة.', '["هذا تعريف الترسيب، وهو عكس التسامي.","هذا تعريف الانصهار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:23.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2252, 0, 'الثلج الجاف (ثاني أكسيد الكربون الصلب) يتحول إلى غاز مباشرة عند الضغط الجوي دون أن يصبح سائلًا.', '["","الجليد ينصهر إلى ماء سائل عند الظروف العادية.","ملح الطعام مركب أيوني ذو درجة انصهار مرتفعة ولا يتسامى عند الظروف العادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2253, 1, 'عدم ترك أثر سائل يعني أن النفثالين تحول من صلب إلى غاز مباشرة، وهذا هو التسامي.', '["لو انصهر أولًا لظهر سائل، لكن لم يُلاحظ أي أثر سائل.","","الترسيب تحول غاز إلى صلب، وهو عكس ما حدث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-11T13:13:23.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2254, 1, 'التسامي يحتاج إلى امتصاص طاقة لتتغلب جسيمات الصلب على قوى التجاذب وتتحول إلى غاز، فهو ماص للطاقة.', '["الطارد للطاقة هو الترسيب عكس التسامي.","","كل تغير حالة يصاحبه انتقال للطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:23.333Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2255, 0, 'المواد التي تتسامى تكون قوى التجاذب بين جسيماتها ضعيفة نسبيًا، فتستطيع جسيمات السطح الإفلات إلى الحالة الغازية مباشرة.', '["","قوى التجاذب القوية تجعل الإفلات إلى الغاز صعبًا فلا يسهل التسامي.","جميع الجسيمات تمتلك طاقة حركية؛ ولولاها لما حدث أي تغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:23.334Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2256, 2, 'العملية (3) تحولت فيها المادة من صلب إلى غاز مباشرة، وهذا تعريف التسامي.', '["العملية (1) غاز ← صلب، وهي ترسيب.","العملية (2) صلب ← سائل، وهي انصهار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:23.334Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2257, 1, 'التسامي (صلب ← غاز) يمتص الطاقة، وعكسه الترسيب (غاز ← صلب) يطلقها، وكلاهما لا يمر بالحالة السائلة.', '["الترسيب طارد للطاقة لا ماص.","","هذا عكس الصحيح؛ التسامي يمتص الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.334Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2258, null, null, null, 'التسامي هو تحول المادة من الحالة الصلبة إلى الحالة الغازية مباشرة دون المرور بالحالة السائلة، وهو تغير ماص للطاقة. من أمثلته: تسامي الثلج الجاف (CO₂ الصلب)، وتسامي كرات النفثالين، وتسامي اليود الصلب.', '["التعريف: صلب ← غاز مباشرة","دون المرور بالحالة السائلة","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال عبارة «مباشرة دون المرور بالحالة السائلة»","ذكر انصهار الجليد مثالًا على التسامي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.334Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2259, null, null, null, 'الثلج الجاف يتسامى؛ أي يتحول من صلب إلى غاز مباشرة دون أن يصبح سائلًا، فلا يترك ماءً أو بللًا في صناديق النقل كما يفعل الجليد العادي عند انصهاره. كما أن التسامي ماص للطاقة، فيمتص الحرارة من المحيط ومن المثلجات فيحافظ على برودتها.', '["الثلج الجاف يتسامى (صلب ← غاز مباشرة)","لا يترك سائلًا بخلاف الجليد","التسامي ماص للطاقة فيمتص الحرارة ويبرد"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن الثلج الجاف يتسامى","marks":1},{"element":"عدم تكوّن سائل","marks":1},{"element":"امتصاص الحرارة (ماص)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الثلج الجاف ينصهر ثم يتبخر","القول إنه يطلق البرودة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:23.334Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2260, null, null, null, 'التسامي: الحالة النهائية غازية، ولا تمر المادة بالحالة السائلة، وهو ماص للطاقة. الانصهار: الحالة النهائية سائلة، فالحالة السائلة هي الناتج، وهو ماص للطاقة أيضًا. فكلاهما يبدأ بالحالة الصلبة ويمتص الطاقة، ويختلفان في الحالة النهائية.', '["التسامي ناتجه غاز والانصهار ناتجه سائل","التسامي لا يمر بالحالة السائلة","كلاهما ماص للطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة النهائية لكل منهما","marks":2},{"element":"المرور بالحالة السائلة","marks":1},{"element":"اتجاه الطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التسامي طارد للطاقة","الخلط بين التسامي والترسيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:23.335Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
