(2265, 2, 'التجمد طارد للطاقة: يفقد الماء طاقته إلى هواء المجمد الأبرد منه.', '["البرودة ليست طاقة تنتقل؛ هذا مفهوم خاطئ شائع.","الطاقة تنتقل من الأسخن (الماء) إلى الأبرد (المجمد) لا العكس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:23.339Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2266, 1, 'ثبات درجة الحرارة عند 0 °C أثناء التبريد يدل على أن الماء يتجمد؛ وهو يطلق طاقة إلى المحيط دون أن تنخفض درجة حرارته حتى يتجمد كله.', '["العينة تُبرّد لا تُسخّن، والانصهار يحتاج إلى امتصاص طاقة.","","التكثف تحول غاز إلى سائل ويحدث عند 100 °C للماء، والعينة سائلة عند 0 °C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T13:13:23.339Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2267, 2, 'التجمد سائل ← صلب، وعكسه صلب ← سائل وهو الانصهار.', '["التكثف عكس التبخر.","الترسيب عكس التسامي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.339Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2268, null, null, null, 'التجمد هو تحول المادة من الحالة السائلة إلى الحالة الصلبة عند انتزاع الطاقة منها. وهو تغير طارد للطاقة، والتغير المعاكس له هو الانصهار.', '["التعريف: سائل ← صلب","طارد للطاقة","عكسه الانصهار"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"نوعه من حيث الطاقة","marks":1},{"element":"التغير المعاكس","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف التجمد بأنه ماص للطاقة","جعل عكس التجمد التكثف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.340Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2269, null, null, null, 'الاعتقاد خاطئ لأن البرودة ليست طاقة تنتقل؛ الذي ينتقل هو الطاقة الحرارية من الجسم الأسخن إلى الأبرد. التفسير الصحيح: يفقد الماء طاقة إلى هواء المجمد الأبرد منه، فتقل الطاقة الحركية لجزيئاته حتى تتمكن قوى التجاذب من تثبيتها في مواقع منتظمة فيتحول إلى جليد. لذا فالتجمد تغير طارد للطاقة.', '["البرودة لا تنتقل؛ الطاقة هي التي تنتقل","الماء يفقد طاقة إلى المجمد","تقل الطاقة الحركية وتثبت قوى التجاذب الجزيئات","التجمد طارد للطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"بيان خطأ الاعتقاد","marks":1},{"element":"فقد الماء الطاقة","marks":1},{"element":"التفسير الجزيئي","marks":1},{"element":"طارد للطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تكرار الفكرة الخاطئة بصياغة أخرى","إغفال دور قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:23.340Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2270, null, null, null, 'التجمد تغير طارد للطاقة؛ فعندما يتجمد الماء على الثمار يطلق طاقة حرارية إلى ما حوله ومنها الثمار، فتبقى درجة حرارة الثمار قريبة من 0 °C ولا تنخفض كثيرًا ما دام الماء يتجمد، فتقل الأضرار الناتجة عن البرودة الشديدة.', '["التجمد طارد للطاقة","الماء المتجمد يطلق حرارة إلى الثمار","تبقى درجة حرارة الثمار قريبة من 0 °C"]'::jsonb, '[]'::jsonb, '[{"element":"التجمد طارد للطاقة","marks":1},{"element":"انتقال الحرارة إلى الثمار","marks":1},{"element":"النتيجة: حماية الثمار","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجليد يعزل الثمار فقط دون ذكر انطلاق الطاقة","القول إن التجمد يمتص الحرارة من الثمار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:23.340Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
