(2274, 0, 'عند فقد الطاقة تقل الطاقة الحركية لجزيئات البخار فتتمكن قوى التجاذب من تقريبها بعضها من بعض فتتكون الحالة السائلة.', '["","زيادة الطاقة الحركية تمنع التكثف.","التثبت في مواقع منتظمة يصف الحالة الصلبة (ترسيب أو تجمد)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.345Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2275, 2, 'الصقيع يتكون بتحول بخار الماء إلى بلورات جليد مباشرة (ترسيب)، أما الضباب على المرآة والندى فهما تكثف لبخار الماء إلى قطرات سائلة.', '["ضباب المرآة قطرات ماء سائل ناتجة عن تكثف البخار.","الندى قطرات ماء سائل ناتجة عن التكثف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:23.345Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2276, 0, 'التبخر (سائل ← غاز) ماص للطاقة، والتكثف (غاز ← سائل) طارد لها، فهما متعاكسان.', '["","التكثف طارد للطاقة لا ماص.","هذا عكس الصحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:23.355Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2277, 1, 'في الحالة (2) يتحول بخار الماء إلى ماء سائل، وهذا تكثف.', '["الحالة (1) بخار ← جليد مباشرة، وهي ترسيب.","","الحالة (3) ماء سائل ← بخار، وهي تبخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.356Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2278, null, null, null, 'التكثف هو تحول المادة من الحالة الغازية إلى الحالة السائلة عند فقدها الطاقة. مثاله: تكوّن قطرات الماء على السطح الخارجي لكوب ماء بارد، أو تكوّن الندى. وهو تغير طارد للطاقة.', '["التعريف: غاز ← سائل","مثال صحيح","طارد للطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال","marks":1},{"element":"نوعه من حيث الطاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الصقيع مثالًا على التكثف","وصف التكثف بأنه ماص للطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.356Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2279, null, null, null, 'يحتوي الهواء على بخار ماء. عندما يلامس البخار السطح البارد للكأس المثلج يفقد طاقة فتقل الطاقة الحركية لجزيئاته وتقربها قوى التجاذب بعضها من بعض فيتكثف إلى قطرات ماء سائل. أما الكأس الدافئ فسطحه ليس باردًا بما يكفي لينتزع طاقة كافية من جزيئات البخار، فلا يحدث تكثف ملحوظ.', '["مصدر القطرات بخار الماء في الهواء","السطح البارد ينتزع الطاقة من البخار فيتكثف","الكأس الدافئ لا ينتزع طاقة كافية"]'::jsonb, '[]'::jsonb, '[{"element":"مصدر القطرات","marks":1},{"element":"تفسير التكثف بفقد الطاقة","marks":1},{"element":"تفسير عدم التكثف على الكأس الدافئ","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء تسرب من داخل الكأس","القول إن البرودة خرجت من الكأس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.356Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2280, null, null, null, 'التكثف: يبدأ بالحالة الغازية وينتهي بالحالة السائلة، وهو طارد للطاقة، مثاله تكوّن الندى. الترسيب: يبدأ بالحالة الغازية وينتهي بالحالة الصلبة مباشرة، وهو طارد للطاقة أيضًا، مثاله تكوّن الصقيع. فكلاهما يبدأ بالغاز ويطلق الطاقة، ويختلفان في الحالة النهائية.', '["كلاهما يبدأ بالحالة الغازية","التكثف ينتهي بسائل والترسيب بصلب","كلاهما طارد للطاقة","مثال لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة الابتدائية والنهائية","marks":2},{"element":"اتجاه الطاقة","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد الترسيب ماصًا للطاقة","تبديل المثالين بين الندى والصقيع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.357Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2281, 0, 'الترسيب هو تحول المادة من الحالة الغازية إلى الحالة الصلبة مباشرة دون المرور بالحالة السائلة.', '["","هذا تعريف التسامي، وهو عكس الترسيب.","هذا تعريف التكثف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.361Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2282, 1, 'الصقيع يتكون عندما يتحول بخار الماء في الهواء مباشرة إلى بلورات جليد على الأسطح الباردة، وهذا ترسيب.', '["الندى قطرات سائلة ناتجة عن التكثف.","","تحول الثلج الجاف إلى غاز تسامٍ لا ترسيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.361Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2283, 2, 'في الترسيب يفقد الغاز طاقة كافية لتتثبت جسيماته في الحالة الصلبة، فهو تغير طارد للطاقة.', '["الماص للطاقة هو التسامي عكس الترسيب.","كل تغير حالة يصاحبه انتقال للطاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.361Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2284, 1, 'الترسيب غاز ← صلب مباشرة، وعكسه صلب ← غاز مباشرة وهو التسامي.', '["التكثف غاز ← سائل، وهو عكس التبخر.","","التجمد سائل ← صلب، وهو عكس الانصهار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2285, 1, 'في الترسيب يتحول بخار الماء مباشرة إلى بلورات جليد (صقيع)؛ أما كلمة «قطرات» فتوحي بالحالة السائلة، وهذا يصف التكثف لا الترسيب.', '["القطرات السائلة ناتج التكثف لا الترسيب.","","الضباب قطيرات ماء سائل ناتجة عن التكثف وليس مادة صلبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:23.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2286, 0, 'الترسيب تحول من غاز إلى صلب مباشرة مع انطلاق طاقة، وهذا ما يبينه الصف (1).', '["","الصف (2) صلب ← غاز مع امتصاص طاقة، وهذا تسامٍ.","الصف (3) جعل الترسيب ماصًا للطاقة، وهو طارد لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2287, 0, 'يفقد بخار الماء طاقة إلى الزجاج البارد فتقل طاقته الحركية كثيرًا وتتثبت جزيئاته مباشرة في شبكة بلورية صلبة دون المرور بالحالة السائلة.', '["","امتصاص الطاقة يزيد حركة الجزيئات ولا يثبتها.","المرور بالحالة السائلة ثم التجمد ليس ترسيبًا؛ الترسيب يحدث مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:23.362Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2288, null, null, null, 'الترسيب هو تحول المادة من الحالة الغازية إلى الحالة الصلبة مباشرة دون المرور بالحالة السائلة. مثاله تكوّن الصقيع في ليالي الشتاء الباردة حين يتحول بخار الماء مباشرة إلى بلورات جليد على الأسطح الباردة. وهو تغير طارد للطاقة.', '["التعريف: غاز ← صلب مباشرة","مثال: الصقيع","طارد للطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال","marks":1},{"element":"نوعه من حيث الطاقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بينه وبين الترسيب في التفاعلات الكيميائية (تكوّن راسب)","ذكر الندى مثالًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.363Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2289, null, null, null, 'الترسيب في تغيرات الحالة تغير فيزيائي تتحول فيه المادة نفسها من الحالة الغازية إلى الحالة الصلبة مباشرة دون تكوّن مادة جديدة، مثل تحول بخار الماء إلى صقيع. أما الراسب في التفاعلات الكيميائية فمادة صلبة جديدة غير ذائبة تتكون نتيجة تفاعل مواد في محلول، وهو تغير كيميائي.', '["الترسيب الفيزيائي: غاز ← صلب للمادة نفسها","لا تتكون مادة جديدة فيه","الراسب الكيميائي مادة جديدة صلبة من تفاعل في محلول"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الترسيب الفيزيائي","marks":1},{"element":"عدم تكوّن مادة جديدة","marks":1},{"element":"وصف الراسب الكيميائي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد الصقيع مادة جديدة","الخلط بين المعنيين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.363Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2290, null, null, null, 'التغير الأول: تكوّن الصقيع، وهو ترسيب (تحول بخار الماء إلى بلورات جليد مباشرة)، وهو طارد للطاقة لأن البخار يفقد طاقته إلى الزجاج البارد. التغير الثاني: اختفاء الصقيع دون ظهور سائل، وهو تسامٍ (تحول الجليد إلى بخار مباشرة)، وهو ماص للطاقة لأن الجليد يمتص طاقة من أشعة الشمس.', '["التغير الأول ترسيب","الترسيب طارد للطاقة","التغير الثاني تسامٍ","التسامي ماص للطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"تسمية الترسيب","marks":1},{"element":"نوع الترسيب من حيث الطاقة","marks":1},{"element":"تسمية التسامي","marks":1},{"element":"نوع التسامي من حيث الطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية تكوّن الصقيع تكثفًا","تسمية اختفائه انصهارًا رغم عدم ظهور سائل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:23.363Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2291, 1, 'التبخر السطحي تبخر يحدث عند سطح السائل فقط، ويحدث عند درجات حرارة أقل من درجة الغليان.', '["هذا وصف الغليان.","","هذا وصف التكثف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.366Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2292, 0, 'جفاف الملابس يحدث بتبخر الماء من سطحها عند درجة حرارة الجو الأقل من درجة الغليان، فهو تبخر سطحي.', '["","ظهور الفقاعات في جميع أجزاء السائل غليان.","تكوّن القطرات على الغطاء تكثف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.366Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2293, 2, 'جزيئات السائل لا تمتلك الطاقة الحركية نفسها؛ فبعض جزيئات السطح تمتلك طاقة كافية للتغلب على قوى التجاذب فتفلت إلى الحالة الغازية.', '["الجزيئات تتفاوت في طاقتها الحركية، وهذا التفاوت هو سبب التبخر السطحي.","قوى التجاذب موجودة عند السطح أيضًا، لكن بعض الجزيئات تتغلب عليها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2294, 0, 'كلما زادت مساحة السطح (من 20 إلى 200 cm²) قل وقت الجفاف (من 48 إلى 6 h)، لأن عددًا أكبر من الجزيئات يكون عند السطح فيتبخر في الوقت نفسه.', '["","العمق قل مع زيادة المساحة لأن الكمية ثابتة، والعامل المؤثر هو مساحة السطح.","الكتلة متساوية في الأوعية الثلاثة فلا يمكن أن تفسر الفرق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:23.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2295, 1, 'يحدث التبخر السطحي عند سطح السائل فقط وعند أي درجة أقل من الغليان، أما الغليان فيحدث في جميع أجزاء السائل عند درجة الغليان.', '["كلاهما نوع من التبخر وكلاهما ماص للطاقة.","","التبخر السطحي يحدث لجميع السوائل، مثل الكحول والعطور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:23.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2296, 2, 'التبخر السطحي ماص للطاقة؛ فجزيئات الماء الأعلى طاقة تفلت آخذة طاقة من الجلد والماء المتبقي، فتنخفض درجة حرارة الجلد ويشعر الشخص بالبرودة.', '["التبخر ماص للطاقة لا طارد لها.","البرودة لا تنتقل؛ الذي ينتقل هو الطاقة من الجلد إلى الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-11T13:13:23.367Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2297, 0, 'ارتفاع درجة الحرارة يزيد عدد الجزيئات التي تمتلك طاقة كافية للإفلات من السطح، فيزداد معدل التبخر السطحي.', '["","التغطية تمنع البخار من الابتعاد وتقلل المساحة المكشوفة فيقل صافي التبخر.","انخفاض درجة الحرارة يقلل عدد الجزيئات القادرة على الإفلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.368Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2298, null, null, null, 'التبخر السطحي هو تبخر يحدث عند سطح السائل فقط، ويحدث عند درجات حرارة أقل من درجة الغليان. ويزداد معدله بارتفاع درجة الحرارة، وبزيادة مساحة سطح السائل المكشوفة.', '["التعريف: عند السطح فقط","يحدث عند درجات أقل من الغليان","العامل الأول: ارتفاع درجة الحرارة","العامل الثاني: زيادة مساحة السطح"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"العامل الأول","marks":1},{"element":"العامل الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التبخر السطحي يحدث عند درجة الغليان","ذكر زيادة كمية السائل عاملًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.368Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2299, null, null, null, 'التبخر السطحي: يحدث عند سطح السائل فقط، وعند أي درجة حرارة أقل من درجة الغليان، مثل جفاف الملابس المبللة. الغليان: يحدث في جميع أجزاء السائل، وعند درجة الغليان فقط (يتساوى عندها الضغط البخاري مع الضغط الجوي)، مثل غليان الماء في القدر عند 100 °C و1 atm.', '["مكان الحدوث لكل منهما","درجة الحرارة لكل منهما","مثال لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"مكان الحدوث","marks":2},{"element":"درجة الحرارة","marks":2},{"element":"المثالان","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة كاملة في الجوانب الثلاثة مع مثالين صحيحين"},{"level":"4–5 درجات","description":"مقارنة صحيحة ينقصها جانب لأحدهما"},{"level":"2–3 درجات","description":"جانب واحد صحيح للاثنين"},{"level":"1 درجة","description":"معلومة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين مكاني الحدوث","القول إن التبخر السطحي يحتاج إلى تسخين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:23.368Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2300, null, null, null, 'يتبخر الماء المتسرب من سطح الإناء تبخرًا سطحيًا، والتبخر السطحي ماص للطاقة؛ إذ تفلت الجزيئات الأعلى طاقة آخذة معها طاقة من الإناء والماء الذي بداخله، فتقل الطاقة الحركية المتوسطة للماء المتبقي فتنخفض درجة حرارته ويبقى أبرد من الجو.', '["حدوث تبخر سطحي للماء المتسرب","التبخر ماص للطاقة","الجزيئات الأعلى طاقة تفلت فتنخفض درجة حرارة المتبقي"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد التبخر السطحي","marks":1},{"element":"التبخر ماص للطاقة","marks":1},{"element":"تفسير انخفاض درجة الحرارة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفخار مادة باردة بطبيعتها","القول إن الماء يطلق حرارة عند تبخره"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (2%)"}],"at":"2026-10-11T13:13:23.368Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2301, 1, 'الضغط البخاري هو الضغط الذي يبذله بخار السائل فوق سطحه في وعاء مغلق عندما يتساوى معدل التبخر مع معدل التكثف.', '["هذا الضغط الجوي، وهو ضغط خارجي لا ينتج عن بخار السائل.","","هذا ضغط السائل نفسه لا ضغط بخاره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.372Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2302, 2, 'في الوعاء المغلق تتبخر الجزيئات ويتكثف بعضها، وعندما يتساوى المعدلان يثبت عدد جزيئات البخار فيثبت الضغط البخاري.', '["الضغط البخاري يُقاس والسائل موجود؛ لا يلزم تبخره كله.","التبخر لا يتوقف، بل يستمر بمعدل يساوي معدل التكثف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:23.373Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2303, 0, 'ارتفع الضغط البخاري من 2.3 kPa عند 20 °C إلى 101.3 kPa عند 100 °C، لأن ارتفاع درجة الحرارة يزيد عدد الجزيئات التي تمتلك طاقة كافية للتبخر.', '["","البيانات تُظهر زيادة لا نقصانًا.","القيم تتغير بوضوح مع درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.373Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2304, 2, 'السائل ذو قوى التجاذب الأضعف تفلت جزيئاته بسهولة أكبر فيكون ضغطه البخاري أعلى؛ وثنائي إيثيل الإيثر له أعلى ضغط بخاري (58.7 kPa).', '["الماء له أقل ضغط بخاري، فقوى التجاذب بين جزيئاته أقوى.","ضغط الإيثانول البخاري أقل بكثير من الإيثر، فقوى التجاذب فيه أقوى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:23.373Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2305, 1, 'الضغط البخاري يعتمد على نوع السائل ودرجة حرارته، ولا يعتمد على كمية السائل، فهو متساوٍ في الوعاءين لأنهما عند الدرجة نفسها.', '["الاعتقاد بأن زيادة كمية السائل تزيد الضغط البخاري مفهوم خاطئ شائع.","","كمية السائل الأقل لا تعني ضغطًا بخاريًا أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.373Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2306, 1, 'عندما يتساوى الضغط البخاري مع الضغط الجوي يتكون البخار في جميع أجزاء السائل فيغلي، وتُسمى هذه الدرجة درجة الغليان.', '["التجمد يرتبط بانتزاع الطاقة لا بتساوي الضغط البخاري مع الجوي.","","التسامي تحول صلب إلى غاز، والمادة هنا سائلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.374Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2307, 0, 'ارتفاع درجة الحرارة يزيد الطاقة الحركية للجزيئات، فيزداد عدد الجزيئات القادرة على التغلب على قوى التجاذب والتبخر، فيزداد عدد جزيئات البخار ويزداد ضغطه.', '["","زيادة قوى التجاذب كانت ستقلل التبخر والضغط البخاري.","حجم الوعاء المغلق ثابت، والضغط البخاري لا يعتمد عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:23.374Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2308, null, null, null, 'الضغط البخاري هو الضغط الذي يبذله بخار السائل فوق سطحه في وعاء مغلق عندما يتساوى معدل التبخر مع معدل التكثف. يتأثر بدرجة الحرارة: فيزداد الضغط البخاري بارتفاعها. ويتأثر بقوى التجاذب بين الجزيئات (نوع السائل): فكلما ضعفت قوى التجاذب ازداد الضغط البخاري.', '["التعريف مع شرط الوعاء المغلق وتساوي المعدلين","أثر درجة الحرارة","أثر قوى التجاذب"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"أثر درجة الحرارة","marks":1},{"element":"أثر قوى التجاذب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر كمية السائل عاملًا مؤثرًا","عكس أثر قوى التجاذب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.374Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2309, null, null, null, 'في البداية تتبخر جزيئات من سطح الماء فيزداد عدد جزيئات البخار فوقه، ومع ازديادها يصطدم بعضها بسطح السائل ويعود إليه (يتكثف)، فيزداد معدل التكثف تدريجيًا. وعندما يتساوى معدل التبخر مع معدل التكثف يثبت عدد جزيئات البخار فيثبت الضغط الذي يبذله، وهذا هو الضغط البخاري عند تلك الدرجة.', '["التبخر يزيد عدد جزيئات البخار","التكثف يبدأ ويزداد معدله","تساوي المعدلين","ثبات الضغط = الضغط البخاري"]'::jsonb, '[]'::jsonb, '[{"element":"وصف التبخر في البداية","marks":1},{"element":"وصف التكثف","marks":1},{"element":"تساوي المعدلين","marks":1},{"element":"ثبات الضغط البخاري","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التبخر يتوقف عند الاتزان","إغفال حدوث التكثف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:23.375Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2310, null, null, null, 'أ) يزداد الضغط البخاري للماء بارتفاع درجة الحرارة، لأن عددًا أكبر من الجزيئات يمتلك طاقة كافية للتبخر. ب) يغلي الماء عند 100 °C، لأن ضغطه البخاري عندها (101.3 kPa) يساوي الضغط الجوي، ودرجة الغليان هي الدرجة التي يتساوى عندها الضغط البخاري مع الضغط الجوي.', '["العلاقة طردية (يزداد بارتفاع الحرارة)","تفسير العلاقة","الماء يغلي عند 100 °C","تساوي الضغط البخاري مع الجوي"]'::jsonb, '[]'::jsonb, '[{"element":"وصف العلاقة","marks":1},{"element":"تفسيرها","marks":1},{"element":"تحديد درجة الغليان","marks":1},{"element":"التعليل بتساوي الضغطين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف العلاقة بأنها عكسية","اختيار 60 °C لأنها «ساخنة بما يكفي»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.375Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2311, 2, 'درجة الغليان هي درجة الحرارة التي يتساوى عندها الضغط البخاري للسائل مع الضغط الجوي (الخارجي)، فيتكون البخار في جميع أجزاء السائل.', '["التبخر السطحي يحدث عند درجات أقل من الغليان، فلا يرتبط بدرجة محددة.","هذه درجة التجمد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:23.378Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2312, 1, 'يغلي الماء النقي عند 100.00 °C عندما يكون الضغط الخارجي 1.00 atm.', '["هذه درجة تجمد الماء عند 1.00 atm.","","هذه درجة الحرارة الحرجة للماء لا درجة غليانه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.378Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2313, 0, 'في المرتفعات يكون الضغط الجوي أقل، فيصل الضغط البخاري للماء إلى قيمة الضغط الجوي عند درجة حرارة أقل من 100 °C.', '["","الضغط الجوي يقل بالارتفاع ولا يزيد، وزيادته ترفع درجة الغليان.","السبب هو انخفاض الضغط الجوي لا الشوائب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.378Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2314, 1, 'قدر الضغط يرفع الضغط فوق الماء إلى أكثر من 1 atm، فيحتاج الماء إلى درجة أعلى من 100 °C ليتساوى ضغطه البخاري مع هذا الضغط، فيُطهى الطعام عند درجة حرارة أعلى وفي وقت أقل.', '["زيادة الضغط ترفع درجة الغليان ولا تخفضها، والغليان المبكر لا يعني طهيًا أسرع.","","الماء يغلي في قدر الضغط لكن عند درجة أعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:23.379Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2315, 2, 'يغلي السائل عندما يتساوى ضغطه البخاري مع الضغط الخارجي؛ والضغط البخاري للماء 47.4 kPa عند 80 °C.', '["الضغط البخاري عند 60 °C هو 19.9 kPa، وهو أقل من الضغط الخارجي.","100 °C درجة الغليان عند 101.3 kPa لا عند 47.4 kPa.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:23.379Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2316, 0, 'كلما زاد الضغط الخارجي احتاج السائل إلى درجة حرارة أعلى ليصبح ضغطه البخاري مساويًا له، فترتفع درجة الغليان.', '["","انخفاض درجة الغليان يحدث عند نقص الضغط الخارجي.","درجة الغليان تعتمد على الضغط الخارجي، فالقول بثباتها مفهوم خاطئ شائع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.379Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2317, 2, 'عند درجة الغليان يتكون البخار في جميع أجزاء السائل (لا عند السطح فقط)، وتعتمد هذه الدرجة على الضغط الخارجي.', '["درجة الغليان 100 °C عند 1 atm فقط، وتتغير بتغير الضغط.","التبخر عند السطح فقط هو التبخر السطحي لا الغليان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.379Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2318, null, null, null, 'درجة الغليان هي درجة الحرارة التي يتساوى عندها الضغط البخاري للسائل مع الضغط الجوي (الخارجي). درجة غليان الماء النقي 100 °C عند 1 atm. ولا تبقى ثابتة؛ لأنها تعتمد على الضغط الخارجي، ففي المرتفعات حيث الضغط الجوي أقل يغلي الماء عند درجة أقل من 100 °C.', '["التعريف","100 °C عند 1 atm","لا تبقى ثابتة لاعتمادها على الضغط الخارجي"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"قيمة درجة غليان الماء","marks":1},{"element":"الحكم على الثبات مع التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الغليان بأنه بدء ظهور البخار","القول إن الماء يغلي عند 100 °C في كل مكان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.380Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2319, null, null, null, 'الضغط الجوي في المدينة الجبلية أقل منه في المدينة الساحلية، فيتساوى الضغط البخاري للماء مع الضغط الجوي عند درجة أقل من 100 °C، فيغلي الماء عند درجة حرارة أقل. ولأن الماء المغلي هناك أقل حرارة، يحتاج البيض إلى وقت أطول لينضج.', '["الضغط الجوي أقل في المرتفعات","درجة الغليان أقل من 100 °C","الماء المغلي أقل حرارة فيطول الطهي"]'::jsonb, '[]'::jsonb, '[{"element":"انخفاض الضغط الجوي","marks":1},{"element":"انخفاض درجة الغليان","marks":1},{"element":"الربط بزمن الطهي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء يغلي أسرع فينضج الطعام أسرع","القول إن الهواء في الجبال أبرد فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-11T13:13:23.380Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2320, null, null, null, 'أ) يغلي عند 60 °C، لأن الضغط البخاري للماء عندها 19.9 kPa وهو يساوي الضغط الخارجي. ب) لا يغلي، لأن ضغطه البخاري عند 80 °C (47.4 kPa) أقل من الضغط الخارجي (101.3 kPa)، فلا يتحقق شرط الغليان.', '["أ) 60 °C","تعليل أ بتساوي الضغطين","ب) لا يغلي","تعليل ب: الضغط البخاري أقل من الخارجي"]'::jsonb, '[]'::jsonb, '[{"element":"إجابة أ","marks":1},{"element":"تعليل أ","marks":1},{"element":"إجابة ب","marks":1},{"element":"تعليل ب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار 100 °C في كل الحالات","مقارنة درجة الحرارة بدل مقارنة الضغطين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:23.380Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2321, 0, 'درجة الانصهار هي درجة الحرارة التي تتحول عندها المادة الصلبة إلى سائلة.', '["","هذه درجة الغليان.","تحول الصلب إلى غاز تسامٍ ولا يُعرّف بدرجة الانصهار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.384Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2322, 1, 'ينصهر الجليد النقي عند 0 °C عند ضغط 1 atm.', '["هذه درجة غليان الماء عند 1 atm.","","هذه تقريبًا درجة الصفر المطلق ولا علاقة لها بانصهار الجليد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:23.385Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2323, 2, 'عند درجة الانصهار تصبح اهتزازات الجسيمات قوية بما يكفي للتغلب على قوى التجاذب التي تثبتها في مواقعها في الشبكة البلورية فتتحول إلى سائل.', '["توقف الاهتزاز لا يحدث عند الانصهار؛ بل تزداد الاهتزازات.","التقارب وزيادة التجاذب لا يؤديان إلى الانصهار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.386Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2324, 1, 'درجة انصهار المادة (ب) 80 °C، وهي أعلى من 25 °C، فلم تنصهر بعد وتكون صلبة.', '["تكون سائلة بين 80 °C و218 °C، و25 °C أقل من درجة انصهارها.","","تكون غازية فوق 218 °C فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.386Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2325, 0, 'للمادة البلورية النقية مثل الجليد درجة انصهار محددة، أما المواد غير المتبلورة مثل الزجاج فتلين تدريجيًا ولا تملك درجة انصهار محددة.', '["","هذا عكس الصحيح.","الجليد مادة بلورية، لذا انصهر عند درجة محددة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.387Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2326, 2, 'ثبات درجة الحرارة أثناء التسخين يعني حدوث تغير في الحالة (الانصهار هنا)، فدرجة الانصهار هي الدرجة التي ثبتت عندها: 44 °C.', '["لو كانت درجة الانصهار أقل لثبتت درجة الحرارة عند تلك الدرجة الأقل.","لو كانت أعلى لاستمرت درجة الحرارة في الارتفاع بعد 44 °C دون ثبات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:23.387Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2327, 0, 'المادة البلورية النقية تنصهر عند درجة محددة تميزها، وهذه خاصية لا تعتمد على كتلة العينة.', '["","0 °C درجة انصهار الجليد فقط؛ لكل مادة درجة انصهار خاصة بها.","درجة الانصهار خاصية مميزة لا تتغير بتغير الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:23.387Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2328, null, null, null, 'درجة الانصهار هي درجة الحرارة التي تتحول عندها المادة الصلبة إلى سائلة. درجة انصهار الجليد 0 °C عند 1 atm. وللمادة البلورية النقية درجة انصهار محددة، بينما تلين المواد غير المتبلورة (مثل الزجاج) تدريجيًا على مدى من درجات الحرارة.', '["التعريف","0 °C للجليد عند 1 atm","البلورية لها درجة محددة","غير المتبلورة تلين تدريجيًا"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"درجة انصهار الجليد","marks":1},{"element":"المواد البلورية","marks":1},{"element":"المواد غير المتبلورة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفها بأنها درجة تحول السائل إلى غاز","القول إن الزجاج ينصهر عند درجة محددة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:23.387Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2329, null, null, null, 'عند درجة الانصهار تصبح اهتزازات الجسيمات قوية بما يكفي للتغلب على قوى التجاذب التي تثبتها في مواقعها في الشبكة البلورية، فتتحرر وتنزلق بعضها فوق بعض. وتبقى درجة الحرارة ثابتة لأن الطاقة المضافة تُستهلك في التغلب على قوى التجاذب لا في زيادة الطاقة الحركية المتوسطة للجسيمات، حتى تتحول العينة كلها إلى سائل.', '["الاهتزازات تتغلب على قوى التجاذب عند درجة الانصهار","الجسيمات تتحرر من مواقعها","الطاقة تُستهلك في التغلب على قوى التجاذب","لا تزداد الطاقة الحركية المتوسطة فتثبت الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"التفسير الجزيئي للانصهار","marks":2},{"element":"تفسير ثبات درجة الحرارة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن مصدر الحرارة يتوقف","القول إن الجسيمات تتوقف عن الحركة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.388Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2330, null, null, null, 'عند 25 °C: صلبة، لأنها أقل من درجة الانصهار (80 °C). عند 150 °C: سائلة، لأنها بين درجة الانصهار (80 °C) ودرجة الغليان (218 °C). عند 250 °C: غازية، لأنها أعلى من درجة الغليان (218 °C).', '["25 °C صلبة","150 °C سائلة","250 °C غازية","التعليل بالمقارنة مع درجتي الانصهار والغليان"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة عند 25 °C","marks":1},{"element":"الحالة عند 150 °C","marks":1},{"element":"الحالة عند 250 °C","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد المادة سائلة عند 25 °C","الخلط بين درجتي الانصهار والغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.388Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2331, 0, 'درجة التجمد هي درجة الحرارة التي يتحول عندها السائل إلى مادة صلبة بلورية.', '["","تحول الغاز إلى سائل تكثف ولا يُعرّف بدرجة التجمد.","الجسيمات لا تتوقف عن الحركة عند التجمد؛ إنما تقل حركتها وتثبت في مواقع منتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:23.392Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2332, 0, 'يتجمد الماء النقي عند 0.00 °C عند ضغط 1.00 atm.', '["","الماء يتجمد عند 0.00 °C، ودرجة −10 °C أقل من درجة تجمده.","هذه درجة غليان الماء عند 1.00 atm."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:23.392Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2333, 2, 'للمادة النقية تكون درجة التجمد مساوية لدرجة الانصهار؛ فالماء يتجمد عند 0 °C والجليد ينصهر عند 0 °C عند 1 atm.', '["لا تكون أعلى؛ فهما الدرجة نفسها للمادة النقية.","الاعتقاد بأنها أقل مفهوم خاطئ شائع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.392Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2334, 1, 'درجة تجمد المادة النقية تساوي درجة انصهارها، فدرجة تجمد البنزين 5.5 °C.', '["درجتا التجمد والانصهار متساويتان للمادة النقية.","","درجتا التجمد والانصهار متساويتان للمادة النقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:23.392Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
