(2338, null, null, null, 'درجة التجمد هي درجة الحرارة التي يتحول عندها السائل إلى مادة صلبة بلورية. وللمادة النقية تساوي درجة التجمد درجة الانصهار؛ فالماء يتجمد عند 0 °C والجليد ينصهر عند 0 °C عند ضغط 1 atm.', '["التعريف","درجة التجمد = درجة الانصهار للمادة النقية","مثال الماء: 0 °C عند 1 atm"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"العلاقة بدرجة الانصهار","marks":1},{"element":"مثال الماء","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن درجة التجمد أقل من درجة الانصهار","إغفال شرط المادة النقية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.393Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2339, null, null, null, 'أ) درجة التجمد 6 °C لأن درجة الحرارة ثبتت عندها أثناء التبريد. ب) درجة الانصهار 6 °C أيضًا لأن درجتي التجمد والانصهار متساويتان للمادة النقية. ج) أثناء التجمد يطلق السائل طاقة عند تكوّن قوى التجاذب التي تثبت الجسيمات في الشبكة البلورية، وتعوض هذه الطاقة ما يُنتزع بالتبريد، فتبقى درجة الحرارة ثابتة حتى يتجمد السائل كله.', '["درجة التجمد 6 °C","درجة الانصهار 6 °C","تفسير الثبات بانطلاق الطاقة عند تكوّن قوى التجاذب"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد درجة التجمد","marks":1},{"element":"تحديد درجة الانصهار","marks":1},{"element":"تفسير ثبات درجة الحرارة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار −4 °C درجة للتجمد","القول إن الحرارة تثبت لأن التبريد توقف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.394Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2340, null, null, null, 'تنخفض درجة حرارة الماء تدريجيًا لأنه يفقد طاقة إلى المجمد حتى تصل إلى 0 °C، ثم تثبت عند 0 °C مدة يتجمد فيها الماء (تغير طارد للطاقة يطلق فيه الماء طاقة إلى المجمد)، وبعد أن يتجمد كله تنخفض درجة حرارة الجليد حتى تصل إلى −18 °C.', '["انخفاض درجة الحرارة حتى 0 °C","ثبات درجة الحرارة عند 0 °C أثناء التجمد","التجمد طارد للطاقة","انخفاض درجة حرارة الجليد حتى −18 °C"]'::jsonb, '[]'::jsonb, '[{"element":"الانخفاض حتى 0 °C","marks":1},{"element":"الثبات عند 0 °C","marks":1},{"element":"نوع التغير طارد","marks":1},{"element":"الانخفاض بعد التجمد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء يتجمد عند −18 °C","إغفال مرحلة ثبات درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:23.394Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2341, 1, 'يتحكم في حالة المادة متغيران هما درجة الحرارة والضغط، ولذلك يُرسم مخطط الحالة الفيزيائية بالضغط مقابل درجة الحرارة.', '["الكتلة والحجم لا يحددان الحالة؛ فكتلة كبيرة أو صغيرة من الماء قد تكون سائلة في الظروف نفسها.","","الكثافة واللون خواص للمادة وليسا متغيرين يتحكمان في حالتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:23.398Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2342, 0, 'رفع درجة الحرارة يزيد الطاقة الحركية للجسيمات فيزداد معدل التبخر.', '["","زيادة معدل التكثف ترتبط بزيادة الضغط.","رفع درجة الحرارة يزيد معدل التبخر لا يقلله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.398Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2343, 1, 'زيادة الضغط تقرّب الجسيمات بعضها من بعض فتزيد معدل التكثف.', '["زيادة معدل التبخر ترتبط برفع درجة الحرارة.","","الضغط أحد المتغيرين اللذين يتحكمان في حالة المادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.398Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
