(2344, 2, 'زيادة الضغط إلى 2 atm ترفع درجة الغليان فوق 100 °C، فيبقى الماء عند 100 °C سائلًا؛ وهذا يبين أن الضغط يتحكم في الحالة مع درجة الحرارة.', '["يكون الماء بخارًا عند 100 °C إذا كان الضغط أقل من 1 atm، لا عند 2 atm.","درجة 100 °C أعلى بكثير من منطقة الصلب في مخطط الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-11T13:13:23.399Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2345, 0, 'الحالتان (1) و(2) عند درجة الحرارة نفسها (100 °C) لكن الحالة مختلفة (بخار وسائل) بسبب اختلاف الضغط، فدرجة الحرارة وحدها لا تحدد الحالة.', '["","الحالتان (1) و(3) تختلفان في درجة الحرارة لا في الضغط، فلا تُظهران أثر الضغط.","الحالتان (2) و(3) تختلفان في درجة الحرارة والضغط معًا، فلا تعزلان أثر الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.399Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2346, 1, 'زيادة الضغط تقرّب جزيئات البخار وتزيد معدل التكثف، فيمكن تحويل البخار إلى سائل عند درجة الحرارة نفسها (ما دامت أقل من درجة الحرارة الحرجة).', '["تقليل الضغط يزيد التبخر ولا يساعد على التكثف.","","زيادة حجم الوعاء تقلل الضغط فتعيق التكثف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.399Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2347, 2, 'الحالة الفيزيائية للمادة تعتمد على درجة الحرارة والضغط معًا، ولهذا يوضح مخطط الحالة الفيزيائية أثر المتغيرين معًا.', '["الاعتقاد بأن درجة الحرارة وحدها تحدد الحالة مفهوم خاطئ شائع؛ الماء عند 100 °C قد يكون سائلًا أو بخارًا حسب الضغط.","الضغط وحده لا يكفي؛ فدرجة الحرارة تؤثر أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:23.400Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2348, null, null, null, 'المتغيران هما درجة الحرارة والضغط. ارتفاع درجة الحرارة يزيد الطاقة الحركية للجسيمات فيزيد معدل التبخر. وزيادة الضغط تقرّب الجسيمات بعضها من بعض فتزيد معدل التكثف.', '["المتغير الأول: درجة الحرارة","أثرها: زيادة معدل التبخر","المتغير الثاني: الضغط","أثره: زيادة معدل التكثف"]'::jsonb, '[]'::jsonb, '[{"element":"درجة الحرارة","marks":1},{"element":"أثر درجة الحرارة","marks":1},{"element":"الضغط","marks":1},{"element":"أثر الضغط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الكتلة أو الحجم متغيرًا","عكس أثري المتغيرين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:23.400Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2349, null, null, null, 'زيادة الضغط من 1 atm إلى 2 atm تقرّب جزيئات الماء بعضها من بعض وتزيد معدل التكثف، فيحتاج الماء إلى درجة حرارة أعلى من 100 °C ليغلي؛ لذا يبقى سائلًا عند 100 °C تحت ضغط 2 atm. ويدل ذلك على أن حالة المادة لا تتحدد بدرجة الحرارة وحدها، بل بدرجة الحرارة والضغط معًا.', '["زيادة الضغط تزيد معدل التكثف","درجة الغليان ترتفع فوق 100 °C عند 2 atm","الاستنتاج: الحالة تعتمد على المتغيرين معًا"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير أثر الضغط","marks":1},{"element":"ارتفاع درجة الغليان","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء عند 100 °C يغلي دائمًا","إغفال الاستنتاج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.401Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2350, null, null, null, 'عند (25 °C، 1 atm): سائل، لأن 25 °C بين درجتي التجمد (0 °C) والغليان (100 °C) عند 1 atm. عند (200 °C، 1 atm): بخار، لأنها أعلى من درجة الغليان (100 °C) عند 1 atm. عند (75 °C، 3 atm): سائل، لأن زيادة الضغط ترفع درجة الغليان فوق 100 °C، و75 °C أقل منها وأعلى من درجة التجمد.', '["(25 °C، 1 atm) سائل","(200 °C، 1 atm) بخار","(75 °C، 3 atm) سائل","التعليل باستخدام درجتي التجمد والغليان وأثر الضغط"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة الأولى","marks":1},{"element":"الحالة الثانية","marks":1},{"element":"الحالة الثالثة","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد الماء بخارًا عند 75 °C و3 atm","إغفال أثر الضغط في الحالة الثالثة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-11T13:13:23.401Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2351, 0, 'مخطط الحالة الفيزيائية رسم بياني للضغط مقابل درجة الحرارة يوضح حالة المادة (صلبة أو سائلة أو غازية) تحت ظروف مختلفة.', '["","هذا منحنى التسخين لا مخطط الحالة.","هذا منحنى قانون بويل لا مخطط الحالة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.405Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2352, 1, 'يمثل مخطط الحالة الفيزيائية الضغط مقابل درجة الحرارة، وهما المتغيران اللذان يتحكمان في حالة المادة.', '["الحجم ليس من محوري مخطط الحالة.","","الضغط مقابل الحجم يمثل قانون بويل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.406Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2353, 2, 'يقسم مخطط الحالة للماء إلى ثلاث مناطق، كل منطقة تمثل حالة واحدة: صلبة وسائلة وغازية.', '["المخطط يشمل الحالة الصلبة أيضًا، فالمناطق ثلاث.","النقطة الحرجة نقطة على المخطط وليست منطقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.406Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2354, 1, 'كل منحنى فاصل يمثل قيم الضغط ودرجة الحرارة التي توجد عندها الحالتان على جانبيه معًا في حالة اتزان، مثل منحنى (سائل–غاز).', '["حركة الجسيمات لا تتوقف عند أي نقطة على المخطط.","","الحالات الثلاث توجد معًا عند النقطة الثلاثية فقط لا على امتداد المنحنى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.407Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2355, 0, 'عند 1.00 atm يتجمد الماء عند 0.00 °C ويغلي عند 100.00 °C، فيكون سائلًا بين الدرجتين.', '["","الماء صلب عند 1.00 atm في درجات أقل من 0.00 °C فقط.","100.00 °C درجة الغليان عند 1.00 atm؛ أما 217.75 atm فهو الضغط الحرج المقترن بدرجة 373.99 °C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:23.407Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2356, 2, 'مخطط الحالة الفيزيائية يوضح حالة المادة عند أي ضغط ودرجة حرارة.', '["منحنى التسخين يبين تغير درجة الحرارة مع الزمن عند ضغط واحد فقط.","الجدول الدوري ينظم العناصر ولا يبين حالة المادة عند ظروف مختلفة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-11T13:13:23.407Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2357, 0, 'حالة المادة تتحدد بدرجة الحرارة والضغط، لذا يُرسم المخطط بهما ليبين الحالة عند أي توليفة منهما.', '["","الكتلة والحجم وغيرهما قابلة للقياس أيضًا؛ السبب أنهما يتحكمان في الحالة.","درجة الحرارة والضغط يمكن تغييرهما، وتغييرهما هو ما يغير الحالة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.408Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2358, null, null, null, 'مخطط الحالة الفيزيائية رسم بياني للضغط مقابل درجة الحرارة يوضح حالة المادة تحت ظروف مختلفة. مكوناته: المحور الرأسي للضغط والأفقي لدرجة الحرارة؛ وثلاث مناطق تمثل الحالات الصلبة والسائلة والغازية؛ وثلاثة منحنيات تفصل بين المناطق (صلب–سائل، وسائل–غاز، وصلب–غاز)؛ والنقطة الثلاثية والنقطة الحرجة.', '["التعريف","المحوران: الضغط ودرجة الحرارة","ثلاث مناطق","ثلاثة منحنيات","النقطة الثلاثية والنقطة الحرجة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"المحوران","marks":1},{"element":"المناطق والمنحنيات","marks":2},{"element":"النقطتان المميزتان","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تعريف كامل وجميع المكونات"},{"level":"4–5 درجات","description":"تعريف صحيح مع نقص مكون واحد أو اثنين"},{"level":"2–3 درجات","description":"تعريف صحيح دون مكونات أو مكونات دون تعريف"},{"level":"1 درجة","description":"معلومة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل محوري المخطط الحجم ودرجة الحرارة","الخلط بين مخطط الحالة ومنحنى التسخين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.408Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2359, null, null, null, 'مخطط الحالة الفيزيائية: يمثل الضغط مقابل درجة الحرارة، ويبين حالة المادة عند أي توليفة من الضغط ودرجة الحرارة والظروف التي توجد عندها حالتان أو ثلاث معًا. منحنى التسخين: يمثل درجة الحرارة مقابل الزمن (أو الطاقة المضافة) عند ضغط ثابت، ويبين كيف ترتفع درجة حرارة المادة وثباتها أثناء تغيرات الحالة.', '["محورا مخطط الحالة: الضغط ودرجة الحرارة","محورا منحنى التسخين: درجة الحرارة والزمن","معلومات كل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"محورا مخطط الحالة","marks":1},{"element":"محورا منحنى التسخين","marks":1},{"element":"المعلومات التي يقدمها كل منهما","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين محوري الرسمين","القول إن منحنى التسخين يبين أثر الضغط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.408Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2360, null, null, null, 'أ) النقطة داخل منطقة تمثل ضغطًا ودرجة حرارة توجد عندهما المادة في حالة واحدة فقط هي حالة تلك المنطقة. ب) النقطة على منحنى (سائل–غاز) تمثل ضغطًا ودرجة حرارة توجد عندهما الحالتان السائلة والغازية معًا في حالة اتزان، أي ظروف الغليان أو التكثف، مثل (100.00 °C، 1.00 atm) للماء.', '["النقطة داخل المنطقة: حالة واحدة","النقطة على المنحنى: حالتان معًا في اتزان","مثال: 100.00 °C و1.00 atm"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير أ","marks":1},{"element":"تفسير ب","marks":1},{"element":"المثال أو ذكر الغليان/التكثف","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن النقطة على المنحنى تمثل الحالات الثلاث","إغفال مفهوم الاتزان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.409Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2361, 0, 'فائدة مخطط الحالة أنه يبين الضغط ودرجة الحرارة اللذين تكون عندهما المادة في الحالات الثلاث.', '["","التوزيع الإلكتروني لا علاقة له بمخطط الحالة.","مخطط الحالة لا يبين كتلًا أو حجومًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.413Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2362, 1, '200 °C أعلى من درجة غليان الماء عند 1 atm (100 °C)، فيكون الماء بخارًا.', '["الماء صلب عند 1 atm في درجات أقل من 0 °C فقط.","","الماء سائل عند 1 atm بين 0 °C و100 °C فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:23.413Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2363, 0, 'منحنى (سائل–غاز) في مخطط الحالة يبين درجة الغليان عند كل ضغط، بينما 100 °C تخص ضغط 1 atm فقط.', '["","هذه معلومة معروفة من درجة الغليان العادية نفسها.","مخطط الحالة لا يبين التركيب الكيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:23.414Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2364, 1, 'الضغط 0.20 atm أقل من ضغط النقطة الثلاثية (0.50 atm)، وتحت هذا الضغط لا توجد منطقة سائلة، فتتحول المادة الصلبة إلى غاز مباشرة (تسامٍ).', '["الحالة السائلة لا توجد عند ضغوط أقل من ضغط النقطة الثلاثية.","","التسخين يغير الحالة؛ لا تبقى المادة صلبة عند درجات الحرارة العالية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.414Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2365, 2, '180 °C أعلى من درجة الحرارة الحرجة للمادة X (150 °C)، وفوقها لا يمكن أن توجد المادة في الحالة السائلة مهما زاد الضغط.', '["زيادة الضغط فوق الضغط الحرج لا تُسيّل الغاز إذا كانت درجة الحرارة أعلى من الحرجة.","0.50 atm ضغط النقطة الثلاثية ولا يرتبط بالتسييل عند 180 °C.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.414Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2366, 1, 'مخطط الحالة يبين حالة الماء عند أي ضغط ودرجة حرارة، فبتحديد موقع النقطة يعرف الفني الحالة (وهي سائلة هنا لأن درجة الغليان عند 10 atm أعلى من 150 °C).', '["درجة الغليان 100 °C تخص 1 atm فقط، فالمقارنة بها وحدها تعطي نتيجة خاطئة عند 10 atm.","","الكتلة لا تحدد الحالة الفيزيائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.415Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2367, 2, 'مخطط الحالة يبين الحالة عند ظروف معينة وظروف الاتزان بين الحالات والنقطتين الثلاثية والحرجة، لكنه لا يبين سرعة (معدل) تحول المادة.', '["المنحنيات تمثل ظروف وجود حالتين في اتزان.","النقطة الحرجة تظهر على المخطط في نهاية منحنى (سائل–غاز).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:23.416Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2368, null, null, null, 'يبين مخطط الحالة الفيزيائية الضغط ودرجة الحرارة اللذين تكون عندهما المادة في الحالات الثلاث (الصلبة والسائلة والغازية)، والظروف التي توجد عندها حالتان أو ثلاث معًا. مثالان من مخطط الماء: عند (100 °C، 2 atm) يكون الماء سائلًا، وعند (200 °C، 1 atm) يكون بخارًا.', '["الفائدة: يبين الضغط ودرجة الحرارة لكل حالة","المثال الأول صحيح","المثال الثاني صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"الفائدة","marks":2},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر تعريف المخطط بدل فائدته","أمثلة لا تتضمن ضغطًا ودرجة حرارة معًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:23.417Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2369, null, null, null, 'عند (100 °C، 2 atm): سائل. عند (75 °C، 3 atm): سائل. عند (200 °C، 1 atm): بخار. تُظهر الأمثلة أن المخطط يحدد حالة المادة عند أي توليفة من الضغط ودرجة الحرارة، وأن درجة الحرارة وحدها لا تكفي؛ فالماء عند 100 °C قد يكون سائلًا إذا زاد الضغط على 1 atm.', '["الحالة الأولى سائل","الحالة الثانية سائل","الحالة الثالثة بخار","فائدة المخطط في تحديد الحالة بالمتغيرين معًا"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة الأولى","marks":1},{"element":"الحالة الثانية","marks":1},{"element":"الحالة الثالثة","marks":1},{"element":"بيان الفائدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد الماء بخارًا عند 100 °C و2 atm","إغفال دور الضغط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:23.417Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2370, null, null, null, 'أ) لا يمكن؛ لأن 0.20 atm أقل من ضغط النقطة الثلاثية (0.50 atm)، ولا توجد منطقة سائلة في المخطط عند ضغوط أقل منه، فتتسامى المادة الصلبة مباشرة إلى غاز. ب) لا يمكن؛ لأن 200 °C أعلى من درجة الحرارة الحرجة (150 °C)، وفوقها لا توجد المادة سائلة مهما زاد الضغط. وهكذا يحدد المخطط الظروف التي توجد عندها كل حالة.', '["أ) لا، لأن الضغط أقل من ضغط النقطة الثلاثية","ب) لا، لأن درجة الحرارة أعلى من الحرجة","ربط الإجابة بفائدة المخطط"]'::jsonb, '[]'::jsonb, '[{"element":"إجابة أ مع التعليل","marks":2},{"element":"إجابة ب مع التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين النقطة الثلاثية والحرجة","القول إن زيادة الضغط تُسيّل أي غاز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.418Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2371, 1, 'النقطة الحرجة هي النقطة على مخطط الحالة التي تمثل درجة الحرارة الحرجة والضغط الحرج، وينتهي عندها منحنى (سائل–غاز).', '["هذا تعريف النقطة الثلاثية.","","درجة الغليان العادية نقطة على منحنى (سائل–غاز) عند 1 atm وليست نهايته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.422Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2372, 0, 'تقع النقطة الحرجة للماء عند 373.99 °C و217.75 atm.', '["","هذه نقطة الغليان العادية للماء.","هذه نقطة التجمد العادية للماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.422Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2373, 2, '400 °C أعلى من درجة الحرارة الحرجة للماء (373.99 °C)، وفوقها لا يمكن أن يوجد الماء في الحالة السائلة مهما زاد الضغط.', '["217.75 atm هو الضغط الحرج، لكنه لا يُسيّل البخار عند درجة أعلى من الحرجة.","1.00 atm لا يكفي لتسييل البخار حتى عند 100 °C فما فوق.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.422Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2374, 0, 'النقطة الحرجة هي النهاية العليا لمنحنى (سائل–غاز)، وبعدها لا يمكن التمييز بين السائل والبخار.', '["","منحنى (صلب–سائل) يبدأ من النقطة الثلاثية لا من النقطة الحرجة.","منحنى (صلب–غاز) ينتهي عند النقطة الثلاثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.422Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2375, 1, 'يمكن تسييل الغاز بالضغط فقط إذا كانت درجة حرارته أقل من درجة حرارته الحرجة؛ ودرجة الحرارة الحرجة لـ CO₂ (31 °C) أعلى من 25 °C، بينما درجتا N₂ وO₂ أقل بكثير من 25 °C.', '["درجة الحرارة الحرجة لـ N₂ (−147 °C) أقل من 25 °C، فلا يُسيّل بالضغط عند درجة الغرفة.","","درجة الحرارة الحرجة لـ O₂ (−119 °C) أقل من 25 °C، فلا يُسيّل بالضغط عند درجة الغرفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.423Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2376, 2, 'النقطة الحرجة تحدد درجة الحرارة التي لا يمكن فوقها وجود المادة سائلة مهما زاد الضغط، أما النقطة الثلاثية فتوجد عندها الحالات الثلاث معًا في اتزان.', '["هذه صفة النقطة الثلاثية لا الحرجة؛ والخلط بينهما مفهوم خاطئ شائع.","درجة الغليان العادية (100 °C للماء) أقل بكثير من درجة الحرارة الحرجة (373.99 °C).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.423Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2377, 1, 'عند النقطة الحرجة (373.99 °C، 217.75 atm) ينتهي منحنى (سائل–غاز)، ولا يمكن بعدها تمييز السائل من البخار، فيختفي الحد الفاصل بينهما.', '["التجمد يحدث عند درجات حرارة منخفضة قرب 0 °C لا عند النقطة الحرجة.","","عند النقطة الحرجة لا يمكن التمييز بين السائل والبخار، فلا يتحول أحدهما إلى الآخر كليًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.423Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2378, null, null, null, 'النقطة الحرجة هي النقطة على مخطط الحالة الفيزيائية التي تمثل درجة الحرارة الحرجة والضغط الحرج، وينتهي عندها منحنى (سائل–غاز). للماء: 373.99 °C و217.75 atm. ودرجة الحرارة الحرجة هي الدرجة التي لا يمكن فوقها أن توجد المادة في الحالة السائلة مهما زاد الضغط.', '["التعريف","373.99 °C","217.75 atm","معنى درجة الحرارة الحرجة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"قيمتا الماء","marks":2},{"element":"معنى درجة الحرارة الحرجة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين قيم النقطة الحرجة وقيم الغليان العادية","تعريف النقطة الحرجة بتعريف النقطة الثلاثية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.424Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2379, null, null, null, 'النقطة الحرجة: تقع في نهاية منحنى (سائل–غاز)، وتمثل درجة الحرارة الحرجة والضغط الحرج؛ فوق درجة الحرارة الحرجة لا توجد المادة سائلة مهما زاد الضغط. النقطة الثلاثية: تقع عند التقاء المنحنيات الثلاثة، وتمثل الضغط ودرجة الحرارة اللذين توجد عندهما الحالات الثلاث (الصلبة والسائلة والغازية) معًا في حالة اتزان.', '["موقع النقطة الحرجة","ما تمثله النقطة الحرجة","موقع النقطة الثلاثية","ما تمثله النقطة الثلاثية"]'::jsonb, '[]'::jsonb, '[{"element":"موقع الحرجة","marks":1},{"element":"ما تمثله الحرجة","marks":1},{"element":"موقع الثلاثية","marks":1},{"element":"ما تمثله الثلاثية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل التعريفين","القول إن النقطة الحرجة توجد عندها الحالات الثلاث"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:23.424Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2380, null, null, null, 'يمكن تسييل الغاز بالضغط وحده فقط إذا كانت درجة حرارته أقل من درجة حرارته الحرجة. درجة حرارة الغرفة (25 °C) أقل من درجة الحرارة الحرجة لـ CO₂ (31 °C)، فيمكن تسييله بزيادة الضغط. أما N₂ فدرجة حرارته الحرجة (−147 °C) أقل بكثير من 25 °C، وفوق درجة الحرارة الحرجة لا يمكن أن توجد المادة سائلة مهما زاد الضغط، فيجب تبريده إلى ما دون −147 °C أولًا.', '["شرط التسييل بالضغط: T أقل من درجة الحرارة الحرجة","25 °C < 31 °C فيُسيّل CO₂","25 °C > −147 °C فلا يُسيّل N₂ بالضغط وحده"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر شرط التسييل","marks":1},{"element":"تطبيقه على CO₂","marks":1},{"element":"تطبيقه على N₂","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن N₂ يحتاج فقط إلى ضغط أكبر","مقارنة الضغط بدل درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.425Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2381, 2, 'النقطة الثلاثية هي النقطة على مخطط الحالة التي تمثل الضغط ودرجة الحرارة اللذين توجد عندهما الحالات الثلاث (الصلبة والسائلة والغازية) معًا في حالة اتزان.', '["هذا وصف درجة الحرارة الحرجة (النقطة الحرجة).","هذا وصف درجة الغليان العادية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.429Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2382, 0, 'تلتقي عند النقطة الثلاثية المنحنيات الثلاثة (صلب–سائل، وسائل–غاز، وصلب–غاز)، ولذلك تتلاقى عندها المناطق الثلاث.', '["","نهاية منحنى (سائل–غاز) هي النقطة الحرجة.","النقطة الثلاثية لا تقع على محور الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:23.429Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2383, 2, 'عند النقطة الثلاثية توجد الحالات الثلاث: الصلبة والسائلة والغازية معًا في حالة اتزان.', '["حالة واحدة توجد داخل أي منطقة من مناطق المخطط.","حالتان توجدان على أي نقطة من المنحنيات الفاصلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.430Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2384, 0, 'النقطة A (الثلاثية) توجد عندها الحالات الثلاث معًا، والنقطة B (الحرجة) ينتهي عندها منحنى (سائل–غاز).', '["","هذا تبديل لتعريفي النقطتين.","الحالات الثلاث توجد معًا عند النقطة الثلاثية فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.430Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2385, 1, 'هذه الظروف هي إحداثيات النقطة الثلاثية، وعندها توجد الحالات الثلاث معًا في اتزان.', '["الحالة الصلبة وحدها توجد داخل منطقة الصلب لا عند النقطة الثلاثية.","","الحالة الغازية وحدها توجد داخل منطقة الغاز لا عند النقطة الثلاثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.431Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2386, 1, 'تحت ضغط أقل من ضغط النقطة الثلاثية (5.1 atm لـ CO₂) لا توجد الحالة السائلة، فيتحول الصلب إلى غاز مباشرة عند التسخين؛ و1 atm أقل من 5.1 atm.', '["1 atm أقل من 5.1 atm لا أعلى منه؛ ولو كان أعلى لأمكن أن ينصهر.","","درجة حرارة الغرفة (نحو 25 °C) أعلى بكثير من درجة النقطة الثلاثية (−56.6 °C)، والعامل الحاسم هو الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-11T13:13:23.431Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2387, 2, 'عند النقطة الثلاثية توجد الحالات الثلاث معًا لا حالتان فقط؛ فالحالتان توجدان معًا على المنحنيات الفاصلة.', '["عبارة صحيحة؛ لكل مادة نقية ضغط ودرجة حرارة محددان لنقطتها الثلاثية.","عبارة صحيحة؛ المناطق الثلاث تتلاقى عند النقطة الثلاثية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.431Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2388, null, null, null, 'النقطة الثلاثية هي النقطة على مخطط الحالة الفيزيائية التي تمثل الضغط ودرجة الحرارة اللذين توجد عندهما الحالات الثلاث (الصلبة والسائلة والغازية) معًا في حالة اتزان. وتقع عند التقاء المنحنيات الثلاثة الفاصلة بين المناطق (صلب–سائل، وسائل–غاز، وصلب–غاز).', '["التعريف: الحالات الثلاث معًا","في حالة اتزان","الموقع: التقاء المنحنيات الثلاثة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"الموقع","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفها بتعريف النقطة الحرجة","القول إنها تقع في نهاية منحنى (سائل–غاز)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:23.432Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2389, null, null, null, 'أ) النقطة داخل منطقة: توجد المادة في حالة واحدة. ب) النقطة على منحنى فاصل: توجد حالتان معًا في اتزان. ج) النقطة الثلاثية: توجد الحالات الثلاث (الصلبة والسائلة والغازية) معًا في اتزان. وسُميت «ثلاثية» لأن الحالات الثلاث توجد عندها معًا، ولأنها تلتقي عندها المنحنيات الثلاثة.', '["أ) حالة واحدة","ب) حالتان في اتزان","ج) ثلاث حالات في اتزان","سبب التسمية"]'::jsonb, '[]'::jsonb, '[{"element":"أ","marks":1},{"element":"ب","marks":1},{"element":"ج","marks":1},{"element":"سبب التسمية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المنحنى تمثل عليه الحالات الثلاث","تفسير التسمية بوجود ثلاث مناطق فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.432Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2390, null, null, null, 'لا توجد الحالة السائلة لأي مادة عند ضغط أقل من ضغط نقطتها الثلاثية، فإذا سُخّنت المادة الصلبة تحت هذا الضغط تتسامى مباشرة إلى غاز. الضغط الجوي (1 atm) أقل من ضغط النقطة الثلاثية لـ CO₂ (5.1 atm)، فيتسامى الثلج الجاف. أما للماء فالضغط الجوي (1 atm) أعلى من ضغط نقطته الثلاثية (نحو 0.006 atm)، فتوجد الحالة السائلة وينصهر الجليد.', '["لا توجد حالة سائلة تحت ضغط النقطة الثلاثية","1 atm < 5.1 atm فيتسامى CO₂","1 atm > 0.006 atm فينصهر الجليد"]'::jsonb, '[]'::jsonb, '[{"element":"القاعدة العامة","marks":1},{"element":"تطبيقها على CO₂","marks":1},{"element":"تطبيقها على H₂O","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقارنة درجات الحرارة بدل الضغوط","القول إن CO₂ لا يمكن أن يكون سائلًا مطلقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-11T13:13:23.433Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2391, 0, 'قانون بويل: حجم كمية محددة من الغاز يتناسب تناسبًا عكسيًا مع ضغطه عند ثبوت درجة الحرارة، والعلاقة P1V1 = P2V2.', '["","العلاقة بين الحجم والضغط عكسية لا طردية.","هذا نص قانون شارل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:23.437Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2392, 1, 'قانون شارل: حجم كمية محددة من الغاز يتناسب تناسبًا طرديًا مع درجة حرارته بالكلفن عند ثبوت الضغط، والعلاقة V1/T1 = V2/T2.', '["هذا نص قانون جاي لوساك.","","العلاقة بين الحجم ودرجة الحرارة طردية لا عكسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:23.437Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2393, 2, 'قانون جاي لوساك: ضغط الغاز يتناسب طرديًا مع درجة حرارته بالكلفن عند ثبوت الحجم وكمية الغاز، فتكون النسبة P/T ثابتة: P1/T1 = P2/T2.', '["حاصل الضرب الثابت يعني علاقة عكسية، والعلاقة بين P وT طردية.","هذه علاقة قانون بويل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:23.437Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2394, 0, 'القانون العام للغازات يربط بين الضغط والحجم ودرجة الحرارة لكمية محددة من الغاز (عدد مولات ثابت)، فالثابت هو كمية الغاز فقط.', '["","درجة الحرارة تتغير في القانون العام؛ ثباتها يحوله إلى قانون بويل.","الضغط يتغير في القانون العام؛ ثباته يحوله إلى قانون شارل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:23.437Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2395, 1, 'في قانون شارل يكون الضغط وكمية الغاز ثابتين لا الحجم؛ لأن الحجم هو أحد متغيري القانون. أما الصفان (1) و(3) فصحيحان.', '["الصف (1) صحيح: في قانون بويل تثبت درجة الحرارة وكمية الغاز.","","الصف (3) صحيح: في قانون جاي لوساك يثبت الحجم وكمية الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.438Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2396, 2, 'القانون العام للغازات يجمع القوانين الثلاثة: الضغط يتناسب عكسيًا مع الحجم وطرديًا مع درجة الحرارة بالكلفن، والعلاقة P1V1/T1 = P2V2/T2.', '["قانون بويل لا يتضمن درجة الحرارة متغيرًا.","قانون جاي لوساك لا يتضمن الحجم متغيرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:23.438Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2397, 1, 'تتناسب الحجوم والضغوط طرديًا مع درجة الحرارة المطلقة، لذا تُستخدم درجة الحرارة بالكلفن دائمًا: TK = TC + 273.', '["التعويض بالدرجة السيليزية خطأ شائع يعطي نتائج غير صحيحة (وقد تكون صفرًا أو سالبة).","","الفهرنهايت ليست درجة مطلقة ولا تُستخدم في هذه القوانين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.438Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2398, null, null, null, 'قانون بويل: يتناسب حجم كمية محددة من الغاز تناسبًا عكسيًا مع ضغطه عند ثبوت درجة الحرارة: P1V1 = P2V2. قانون شارل: يتناسب حجم كمية محددة من الغاز تناسبًا طرديًا مع درجة حرارته بالكلفن عند ثبوت الضغط: V1/T1 = V2/T2. قانون جاي لوساك: يتناسب ضغط كمية محددة من الغاز تناسبًا طرديًا مع درجة حرارته بالكلفن عند ثبوت الحجم: P1/T1 = P2/T2.', '["نص بويل","علاقة بويل","نص شارل","علاقة شارل","نص جاي لوساك","علاقة جاي لوساك"]'::jsonb, '[]'::jsonb, '[{"element":"قانون بويل نصًا وعلاقة","marks":2},{"element":"قانون شارل نصًا وعلاقة","marks":2},{"element":"قانون جاي لوساك نصًا وعلاقة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"النصوص والعلاقات الثلاث صحيحة كاملة"},{"level":"4–5 درجات","description":"خطأ أو نقص في نص أو علاقة واحدة"},{"level":"2–3 درجات","description":"قانون واحد كامل أو نصوص دون علاقات"},{"level":"1 درجة","description":"معلومة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة شارل بالصورة V1T1 = V2T2","إغفال شرط ثبوت المتغير الثالث","إغفال أن درجة الحرارة بالكلفن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T13:13:23.438Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2399, null, null, null, 'القانون العام للغازات: ضغط كمية محددة من الغاز يتناسب عكسيًا مع حجمها وطرديًا مع درجة حرارتها المطلقة، والعلاقة P1V1/T1 = P2V2/T2 عند ثبوت كمية الغاز. إذا ثبتت درجة الحرارة (T1 = T2) تُحذف من الطرفين فنحصل على قانون بويل P1V1 = P2V2. وإذا ثبت الضغط (P1 = P2) يُحذف من الطرفين فنحصل على قانون شارل V1/T1 = V2/T2.', '["نص القانون العام","العلاقة P1V1/T1 = P2V2/T2","استنتاج بويل بثبوت T","استنتاج شارل بثبوت P"]'::jsonb, '[]'::jsonb, '[{"element":"النص","marks":1},{"element":"العلاقة","marks":1},{"element":"استنتاج قانون بويل","marks":1},{"element":"استنتاج قانون شارل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال ثبوت كمية الغاز","حذف المتغير الخطأ عند الاستنتاج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T13:13:23.439Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2400, null, null, null, 'أ) قانون جاي لوساك: حجم الإطار ثابت تقريبًا، فارتفاع درجة الحرارة يزيد الضغط (P1/T1 = P2/T2). ب) قانون بويل: درجة الحرارة ثابتة، فزيادة الضغط تقلل الحجم (P1V1 = P2V2). ج) قانون شارل: الضغط ثابت، فارتفاع درجة الحرارة يزيد الحجم (V1/T1 = V2/T2).', '["أ) جاي لوساك مع التعليل","ب) بويل مع التعليل","ج) شارل مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"الموقف أ","marks":1},{"element":"الموقف ب","marks":1},{"element":"الموقف ج","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"2 درجتان","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين شارل وجاي لوساك","عدم تحديد المتغير الثابت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:23.439Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2401, 1, 'بتطبيق قانون بويل: V2 = P1V1 ÷ P2 = (1.20 × 2.50) ÷ 3.00 = 1.00 L؛ زيادة الضغط تقلل الحجم.', '["عكس النسبة: V1 × P2 ÷ P1، فازداد الحجم مع زيادة الضغط وهذا يخالف العلاقة العكسية.","","ضرب القيم الثلاث بدل القسمة على P2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T13:13:23.443Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2402, 2, 'P2 = P1V1 ÷ V2 = (98.0 × 450.0) ÷ 300.0 = 147 kPa؛ نقص الحجم يزيد الضغط.', '["عكس النسبة: P1 × V2 ÷ V1، فنقص الضغط مع نقص الحجم وهذا خطأ.","افتراض أن الضغط لا يتغير مع تغير الحجم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.444Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2403, 0, 'P2 = P1V1 ÷ V2 = (760 × 5.00) ÷ 2.00 = 1900 mmHg = 1.90×10³ mmHg.', '["","عكس النسبة: 760 × 2.00 ÷ 5.00.","ناتج P1V1 دون القسمة على V2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T13:13:23.444Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2404, 1, 'وفق قانون بويل العلاقة عكسية: P1V1 = P2V2، فإذا أصبح P2 = 2P1 فإن V2 = V1/2.', '["التضاعف يعني علاقة طردية، والعلاقة بين P وV عكسية.","","الحجم يتغير بتغير الضغط عند ثبوت درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:23.445Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2405, 0, 'حاصل الضرب PV ثابت: 1.0 × 12.0 = 2.0 × 6.0 = 4.0 × 3.0 = 12 atm·L، فعند 3.0 atm: V = 12 ÷ 3.0 = 4.0 L.', '["","افتراض علاقة طردية خطية بين الضغط والحجم.","ضرب PV في الضغط بدل القسمة عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:23.445Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2406, 2, 'الضغط الجديد = 0.800 P1، وبتطبيق بويل: V2 = P1V1 ÷ P2 = 80.0 ÷ 0.800 = 100. L = 1.00×10² L.', '["ضرب الحجم في 0.800 كأن العلاقة طردية.","زيادة الحجم بنسبة 20% بدل تطبيق العلاقة العكسية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T13:13:23.446Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2407, 1, 'V2 = P1V1 ÷ P2 = (1.00 × 5.00) ÷ 0.400 = 12.5 L؛ يتمدد البالون لأن الضغط الخارجي يقل.', '["عكس النسبة: 5.00 × 0.400 ÷ 1.00، فصغر البالون مع نقص الضغط.","","جمع الضغط إلى الحجم، وهي عملية لا معنى لها فيزيائيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T13:13:23.446Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2408, null, null, null, 'المعطيات: V1 = 60.0 mL ، P1 = 1.00 atm ، V2 = 25.0 mL. المطلوب: P2. قانون بويل: P1V1 = P2V2 ← P2 = P1V1 ÷ V2 = (1.00 × 60.0) ÷ 25.0 = 2.40 atm.', '["تحديد المعطيات والمطلوب","كتابة قانون بويل","إعادة ترتيب العلاقة لإيجاد P2","التعويض","الناتج 2.40 atm"]'::jsonb, '["V1 = 60.0 mL ، P1 = 1.00 atm ، V2 = 25.0 mL","P1V1 = P2V2","P2 = P1V1 ÷ V2","P2 = (1.00 × 60.0) ÷ 25.0","P2 = 2.40 atm"]'::jsonb, '[{"element":"المعطيات والقانون","marks":1},{"element":"إعادة الترتيب","marks":1},{"element":"التعويض","marks":1},{"element":"الناتج","marks":1},{"element":"الوحدة والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح بخطوات واضحة ووحدات وأرقام معنوية صحيحة"},{"level":"4 درجات","description":"حل صحيح مع خطأ في الوحدة أو الأرقام المعنوية"},{"level":"3 درجات","description":"علاقة وتعويض صحيحان مع خطأ حسابي"},{"level":"1–2 درجة","description":"كتابة المعطيات أو العلاقة الصحيحة فقط"},{"level":"صفر","description":"علاقة خاطئة أو لا إجابة"}]'::jsonb, '["عكس النسبة (0.417 atm)","تحويل mL إلى L دون داعٍ ثم الخطأ فيه","كتابة الناتج 2.4 atm بأرقام معنوية ناقصة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.446Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2409, null, null, null, 'عند تقليل الحجم مع ثبوت درجة الحرارة تبقى سرعة الجسيمات (طاقتها الحركية المتوسطة) ثابتة، لكنها تصبح أقرب بعضها إلى بعض في حيز أصغر، فيزداد عدد تصادماتها مع جدران الوعاء في وحدة الزمن، فيزداد الضغط. والمنحنى البياني للضغط مقابل الحجم منحنى متناقص (علاقة عكسية): كلما زاد الضغط قل الحجم، وحاصل ضربهما ثابت.', '["ثبات سرعة الجسيمات عند ثبات درجة الحرارة","زيادة عدد التصادمات مع الجدران","زيادة الضغط","المنحنى متناقص (علاقة عكسية)"]'::jsonb, '[]'::jsonb, '[{"element":"ثبات الطاقة الحركية","marks":1},{"element":"زيادة التصادمات","marks":1},{"element":"الربط بزيادة الضغط","marks":1},{"element":"وصف المنحنى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن سرعة الجسيمات تزداد","رسم المنحنى خطًا مستقيمًا صاعدًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.449Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2410, null, null, null, 'يجب توحيد وحدتي الضغط لأن العلاقة P1V1 = P2V2 تتطلب أن يكون P1 وP2 بالوحدة نفسها. P1 = 760 mmHg = 1.00 atm. V2 = P1V1 ÷ P2 = (1.00 × 2.00) ÷ 1.50 = 1.33 L. ولو عُوّض دون تحويل لكان الناتج (760 × 2.00) ÷ 1.50 = 1013 L وهو غير معقول.', '["توضيح ضرورة توحيد الوحدات","تحويل 760 mmHg إلى 1.00 atm","تطبيق قانون بويل","الناتج 1.33 L"]'::jsonb, '["P1 = 760 mmHg = 1.00 atm","P1V1 = P2V2","V2 = (1.00 × 2.00) ÷ 1.50","V2 = 1.33 L"]'::jsonb, '[{"element":"أهمية توحيد الوحدات","marks":1},{"element":"التحويل","marks":1},{"element":"التعويض","marks":1},{"element":"الناتج بالوحدة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التعويض بـ 760 مباشرة مع 1.50 atm","الخلط بين mmHg وkPa"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T13:13:23.449Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2411, 2, 'نحوّل إلى كلفن: T1 = 27 + 273 = 300 K ، T2 = 127 + 273 = 400 K. وبقانون شارل V1/T1 = V2/T2: V2 = 3.00 × 400 ÷ 300 = 4.00 L.', '["عكس النسبة: 3.00 × 300 ÷ 400، فقل الحجم مع التسخين.","التعويض بالدرجات السيليزية: 3.00 × 127 ÷ 27.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.454Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2412, 1, 'T2 = T1 × V2 ÷ V1 = 300. × 750. ÷ 500. = 450. K.', '["عكس النسبة: 300. × 500. ÷ 750.","","إضافة الفرق في الحجم (250) إلى درجة الحرارة، وهذا لا يمثل التناسب الطردي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-11T13:13:23.455Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2413, 1, 'الحجم يتناسب مع درجة الحرارة بالكلفن: 293 K ← 313 K، فالنسبة 313 ÷ 293 ≈ 1.07، أي يزداد الحجم بنحو 7% فقط.', '["مضاعفة الدرجة السيليزية لا تضاعف الدرجة المطلقة؛ وهذا مفهوم خاطئ شائع.","","التسخين عند ثبوت الضغط يزيد الحجم ولا يقلله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T13:13:23.455Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2414, 0, 'النسبة V/T ثابتة: 2.00 ÷ 250 = 2.40 ÷ 300 = 2.80 ÷ 350 = 0.00800 L/K، فعند 400 K: V = 0.00800 × 400 = 3.20 L.', '["","افتراض أن الحجم يزداد 0.20 L لكل 50 K؛ والصحيح أنه يزداد 0.40 L لكل 50 K.","هذا الحجم عند 300 K لا عند 400 K."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.455Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2415, 1, 'T1 = 25.0 + 273 = 298 K ، T2 = −18.0 + 273 = 255 K. V2 = 2.50 × 255 ÷ 298 = 2.14 L.', '["عكس النسبة: 2.50 × 298 ÷ 255، فازداد الحجم مع التبريد.","","التعويض بالدرجات السيليزية أعطى حجمًا سالبًا، وهذا مستحيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.456Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2416, 0, 'ارتفاع درجة الحرارة يزيد سرعة الجسيمات وقوة تصادمها، فيزداد الحجم ليبقى الضغط ثابتًا.', '["","حجم الجسيمات نفسها لا يتغير؛ الذي يتغير المسافات بينها.","عدد الجسيمات ثابت لأن كمية الغاز ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.456Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2417, 2, 'V2 = 0.800 V1، وبقانون شارل T2 = T1 × V2 ÷ V1 = 350 × 0.800 = 280 K.', '["زيادة درجة الحرارة بنسبة 20% بدل نقصها.","قسمة 350 على 0.800 (عكس النسبة).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-11T13:13:23.456Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2418, null, null, null, 'المعطيات: V1 = 4.50 L ، T1 = 15.0 + 273 = 288 K ، T2 = 85.0 + 273 = 358 K. قانون شارل: V1/T1 = V2/T2 ← V2 = V1 × T2 ÷ T1 = 4.50 × 358 ÷ 288 = 5.59 L.', '["تحويل درجتي الحرارة إلى كلفن","كتابة قانون شارل","إعادة الترتيب","التعويض","الناتج 5.59 L"]'::jsonb, '["T1 = 15.0 + 273 = 288 K ، T2 = 85.0 + 273 = 358 K","V1/T1 = V2/T2","V2 = V1 × T2 ÷ T1","V2 = 4.50 × 358 ÷ 288","V2 = 5.59 L"]'::jsonb, '[{"element":"التحويل إلى كلفن","marks":1},{"element":"القانون وإعادة الترتيب","marks":1},{"element":"التعويض","marks":1},{"element":"الناتج","marks":1},{"element":"الوحدة والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح بخطوات واضحة ووحدات وأرقام معنوية صحيحة"},{"level":"4 درجات","description":"حل صحيح مع خطأ في الوحدة أو الأرقام المعنوية"},{"level":"3 درجات","description":"علاقة وتعويض صحيحان مع خطأ حسابي"},{"level":"1–2 درجة","description":"كتابة المعطيات أو العلاقة الصحيحة فقط"},{"level":"صفر","description":"علاقة خاطئة أو لا إجابة"}]'::jsonb, '["التعويض بالسيليزية (25.5 L)","عكس النسبة (3.62 L)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.457Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2419, null, null, null, 'حل الطالب خاطئ لأنه عوّض بالدرجات السيليزية؛ وقانون شارل يتطلب درجة الحرارة المطلقة (كلفن) لأن الحجم يتناسب طرديًا معها. التصحيح: T1 = 10 + 273 = 283 K ، T2 = 20 + 273 = 293 K. V2 = 1.00 × 293 ÷ 283 = 1.04 L. أي يزداد الحجم زيادة طفيفة ولا يتضاعف.', '["تحديد الخطأ: استخدام السيليزية","تعليل ضرورة الكلفن","التحويل الصحيح","الناتج 1.04 L"]'::jsonb, '["T1 = 283 K ، T2 = 293 K","V2 = V1 × T2 ÷ T1","V2 = 1.00 × 293 ÷ 283 = 1.04 L"]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"التعليل","marks":1},{"element":"التحويل والتعويض","marks":1},{"element":"الناتج الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول مضاعفة الحجم","التصحيح دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.457Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2420, null, null, null, 'T1 = 20.0 + 273 = 293 K ، V2 = 3V1. بقانون شارل: T2 = T1 × V2 ÷ V1 = 293 × 3 = 879 K. وبالسيليزية: T2 = 879 − 273 = 606 °C.', '["التحويل إلى كلفن","V2 = 3V1","T2 = 879 K","التحويل إلى 606 °C"]'::jsonb, '["T1 = 293 K","T2 = T1 × (V2 ÷ V1) = 293 × 3","T2 = 879 K","T2 = 879 − 273 = 606 °C"]'::jsonb, '[{"element":"التحويل إلى كلفن","marks":1},{"element":"تطبيق القانون","marks":1},{"element":"الناتج بالكلفن","marks":1},{"element":"التحويل إلى سيليزية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة دقيقة تشمل جميع العناصر"},{"level":"3 درجات","description":"إجابة صحيحة ينقصها عنصر واحد"},{"level":"2 درجتان","description":"إجابة صحيحة جزئيًا تشمل نصف العناصر تقريبًا"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب 20.0 °C في 3 (60 °C)","نسيان التحويل الأخير إلى سيليزية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-11T13:13:23.458Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2421, 1, 'الحجم وكمية الغاز ثابتان، فنطبق P1/T1 = P2/T2 بالكلفن: T1 = 300.0 K ، T2 = 400.0 K ، P2 = 2.00 × 400.0 ÷ 300.0 = 2.67 atm.', '["ناتج عكس نسبة درجتي الحرارة (P1T1/T2)، فيقل الضغط مع التسخين وهذا يخالف العلاقة الطردية.","","ناتج التعويض بالدرجات السيليزية (2.00 × 127 ÷ 27) دون التحويل إلى كلفن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.461Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2422, 2, 'T1 = 35.0 + 273 = 308.0 K ، T2 = −15.0 + 273 = 258.0 K ، P2 = P1 × T2 ÷ T1 = 120.0 × 258.0 ÷ 308.0 = 100.5 kPa؛ التبريد يقلل الضغط.', '["ناتج عكس نسبة درجتي الحرارة، فزاد الضغط مع التبريد وهذا غير ممكن عند ثبوت الحجم.","ناتج التعويض بالدرجات السيليزية؛ الضغط السالب مستحيل وهو دليل على نسيان التحويل إلى كلفن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-11T13:13:23.462Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2423, 0, 'T2 = T1 × P2 ÷ P1 = 300. × 2.25 ÷ 1.50 = 450. K ، وبالسيليزي: 450 − 273 = 177 °C.', '["","هذه قيمة T2 بالكلفن (450 K) كُتبت بوحدة السيليزي دون طرح 273.","ناتج عكس نسبة الضغطين (200 K = −73 °C)، فتنخفض درجة الحرارة مع أن الضغط زاد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:23.462Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2424, 1, 'الضغط يتناسب طرديًا مع درجة الحرارة بالكلفن لا بالسيليزي: 373 K ← 473 K، والنسبة 473 ÷ 373 = 1.27، فيزداد الضغط بنحو 1.27 مرة.', '["مضاعفة الدرجة السيليزية لا تضاعف الدرجة المطلقة؛ الضغط يتضاعف فقط إذا تضاعفت درجة الحرارة بالكلفن.","","الحجم ثابت ودرجة الحرارة زادت، فلا بد أن يزداد الضغط وفق قانون جاي لوساك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.462Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2425, 1, 'نحوّل إلى كلفن: 273 K عند 1.00 atm، و400 K عند 127 °C. P2 = 1.00 × 400 ÷ 273 = 1.47 atm (ويتحقق الصف الثاني: 1.00 × 300 ÷ 273 = 1.10 atm).', '["ناتج التناسب مع الدرجات السيليزية (1.10 × 127 ÷ 27).","","ناتج عكس النسبة باستخدام الصف الثاني (1.10 × 300 ÷ 400)، فيقل الضغط مع التسخين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.463Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2426, 0, 'التناسب الطردي بين الضغط ودرجة الحرارة يبدأ من الصفر المطلق، فالضغط يتناسب مع T بالكلفن؛ أما السيليزي فقد يكون صفرًا أو سالبًا فيعطي نتائج مستحيلة.', '["","أرقام الكلفن أكبر من السيليزية لا أصغر، وسبب استخدامها علمي لا حسابي.","الدرجة السيليزية تُستخدم لكل المواد، لكنها لا تبدأ من الصفر المطلق فلا يصح التناسب معها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.463Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2427, 2, 'T1 = 298 K ، T2 = T1 × P2 ÷ P1 = 298 × 5.00 ÷ 3.50 = 426 K ، أي 426 − 273 = 153 °C.', '["ناتج التعويض بالدرجات السيليزية (25 × 5.00 ÷ 3.50).","ناتج عكس نسبة الضغطين (209 K ≈ −64 °C)، فتنخفض درجة الحرارة مع زيادة الضغط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:23.463Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2428, null, null, null, 'المعطيات: P1 = 98.0 kPa ، T1 = 22.0 + 273 = 295.0 K ، T2 = 85.0 + 273 = 358.0 K ، والحجم وكمية الغاز ثابتان. العلاقة: P1/T1 = P2/T2 ⇒ P2 = P1 × T2 ÷ T1 = 98.0 × 358.0 ÷ 295.0 = 119 kPa. التحويل: 119 ÷ 101.3 = 1.17 atm.', '["تحويل درجتي الحرارة إلى كلفن","كتابة قانون جاي لوساك P1/T1 = P2/T2","التعويض الصحيح","الناتج 119 kPa","التحويل إلى 1.17 atm"]'::jsonb, '["T1 = 295.0 K ، T2 = 358.0 K","P2 = P1 × T2 ÷ T1","P2 = 98.0 × 358.0 ÷ 295.0 = 119 kPa","P2 = 119 ÷ 101.3 = 1.17 atm"]'::jsonb, '[{"element":"التحويل إلى كلفن","marks":1},{"element":"القانون والتعويض","marks":1},{"element":"الناتج بوحدة kPa","marks":1},{"element":"التحويل إلى atm","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحويل صحيح وقانون وتعويض صحيحان وناتجان صحيحان 119 kPa و1.17 atm"},{"level":"3 درجات","description":"حل صحيح مع خطأ في التحويل إلى atm أو في الأرقام المعنوية"},{"level":"2 درجتان","description":"قانون صحيح مع نسيان التحويل إلى كلفن"},{"level":"1 درجة","description":"كتابة القانون فقط"},{"level":"صفر","description":"قانون خاطئ أو لا إجابة"}]'::jsonb, '["التعويض بالدرجات السيليزية فيكون الناتج 379 kPa","عكس النسبة T1/T2","ضرب الضغط في 101.3 بدل القسمة عند التحويل إلى atm"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.464Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2429, null, null, null, 'العلبة مغلقة وحجمها ثابت وكمية الغاز فيها ثابتة، فعند تسخينها تزداد درجة الحرارة المطلقة للغاز، فتزداد الطاقة الحركية لجسيماته وسرعتها، فتتصادم مع جدران العلبة بعدد أكبر وبقوة أكبر، فيزداد الضغط طرديًا مع درجة الحرارة بالكلفن (P1/T1 = P2/T2). وإذا تجاوز الضغط ما تتحمله العلبة فإنها تنفجر.', '["الحجم وكمية الغاز ثابتان (وعاء مغلق)","زيادة درجة الحرارة تزيد سرعة الجسيمات وطاقتها الحركية","زيادة عدد التصادمات وقوتها مع الجدران","الضغط يتناسب طرديًا مع درجة الحرارة المطلقة","خطر الانفجار عند تجاوز الضغط حد التحمل"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر ثبات الحجم وكمية الغاز","marks":1},{"element":"تفسير زيادة الضغط بحركة الجسيمات وتصادمها","marks":2},{"element":"ربط ذلك بقانون جاي لوساك والانفجار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط ثبات الحجم وحركة الجسيمات والتناسب الطردي وخطر الانفجار"},{"level":"3 درجات","description":"تفسير صحيح ينقصه عنصر واحد"},{"level":"2 درجتان","description":"ذكر زيادة الضغط بالتسخين دون تفسير جزيئي"},{"level":"1 درجة","description":"ذكر خطر الانفجار فقط"},{"level":"صفر","description":"تفسير خاطئ أو لا إجابة"}]'::jsonb, '["القول إن حجم الغاز يزداد داخل العلبة مع أن حجم العلبة ثابت","القول إن عدد جسيمات الغاز يزداد بالتسخين","الخلط بين قانون جاي لوساك وقانون بويل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.464Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2430, null, null, null, '(أ) T = 273 K و323 K و373 K؛ P/T = 91.0 ÷ 273 = 0.333 ، و107.7 ÷ 323 = 0.333 ، و124.3 ÷ 373 = 0.333 kPa/K. (ب) النسبة P/T ثابتة، أي أن الضغط يتناسب طرديًا مع درجة الحرارة بالكلفن عند ثبوت الحجم وكمية الغاز (قانون جاي لوساك). (ج) T = 473 K ، P = 91.0 × 473 ÷ 273 = 158 kPa.', '["التحويل الصحيح إلى كلفن","حساب النسبة P/T = 0.333 kPa/K للقياسات الثلاثة","استنتاج ثبات النسبة والعلاقة الطردية مع T المطلقة","توقع الضغط 158 kPa عند 200 °C"]'::jsonb, '["T: 273 K ، 323 K ، 373 K","P/T = 0.333 kPa/K في القياسات الثلاثة","النسبة ثابتة ⇒ P ∝ T (بالكلفن)","T = 200 + 273 = 473 K ⇒ P = 91.0 × 473 ÷ 273 = 158 kPa"]'::jsonb, '[{"element":"التحويل إلى كلفن","marks":1},{"element":"حساب النسب","marks":1},{"element":"الاستنتاج","marks":1},{"element":"التوقع الصحيح","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحويل ونسب صحيحة واستنتاج سليم وتوقع 158 kPa"},{"level":"4 درجات","description":"كل ما سبق مع خطأ بسيط في الأرقام المعنوية أو الوحدة"},{"level":"3 درجات","description":"نسب واستنتاج صحيحان مع خطأ في التوقع"},{"level":"2 درجتان","description":"تحويل صحيح ونسب صحيحة دون استنتاج"},{"level":"1 درجة","description":"تحويل درجات الحرارة فقط"},{"level":"صفر","description":"لا إجابة أو حسابات بالسيليزي بالكامل"}]'::jsonb, '["حساب P/T بالدرجات السيليزية فلا تظهر النسبة ثابتة (والقسمة على صفر عند 0 °C)","التوقع بمضاعفة الضغط لأن 200 °C ضعف 100 °C","نسيان وحدة النسبة kPa/K"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.465Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2431, 2, 'بضرب الطرفين في T2 والقسمة على P2: V2 = P1V1T2 / (P2T1)؛ فالحجم يتناسب عكسيًا مع الضغط وطرديًا مع درجة الحرارة المطلقة.', '["عُكست نسبة الضغطين، فيزداد الحجم بزيادة الضغط وهذا يخالف قانون بويل.","عُكست نسبة درجتي الحرارة، فيقل الحجم بالتسخين وهذا يخالف قانون شارل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:23.468Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2432, 0, 'T1 = 300.0 K ، T2 = 400.0 K ، V2 = P1V1T2/(P2T1) = 1.00 × 5.00 × 400.0 ÷ (2.00 × 300.0) = 3.33 L.', '["","ناتج التعويض بالدرجات السيليزية (127 و27) دون التحويل إلى كلفن.","ناتج عكس نسبة درجتي الحرارة (T1/T2 بدل T2/T1)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.469Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2433, 1, 'T1 = 298 K ، V2 = V1 × (P1/P2) × (T2/T1) = 250. × (740./760.) × (273/298) = 223 mL.', '["ناتج عكس نسبة الضغطين (760/740)، فيزداد الحجم مع أن الضغط زاد.","","ناتج عكس نسبة درجتي الحرارة (298/273)، فيزداد الحجم مع أن الغاز بُرِّد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.469Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2434, 1, 'V2 = V1 × (P1/P2) × (T2/T1) = V1 × (1/2) × 2 = V1؛ مضاعفة الضغط تنصف الحجم ومضاعفة درجة الحرارة تضاعفه، فيلغي أحدهما أثر الآخر.', '["هذا يحدث لو كان الحجم يتناسب طرديًا مع الضغط ومع درجة الحرارة معًا.","","هذا يحدث لو كان الحجم يتناسب عكسيًا مع الضغط ومع درجة الحرارة معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:23.469Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2435, 2, 'V2/V1 = (P1/P2) × (T2/T1) = (1.00/0.500) × (250./300.) = 1.67؛ أثر انخفاض الضغط (يضاعف الحجم) أكبر من أثر التبريد (يقلله)، فيزداد الحجم.', '["ناتج عكس نسبة الضغطين (0.500/1.00 × 250/300)، فيقل الحجم مع أن الضغط انخفض.","ناتج عكس نسبة درجتي الحرارة (2 × 300/250)، فيزيد التبريد الحجم وهذا خطأ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.470Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2436, 0, 'T2 = T1 × (P2V2)/(P1V1) = 300. × (3.00 × 1.00) ÷ (1.00 × 2.00) = 450. K.', '["","ناتج قلب النسبة (P1V1)/(P2V2).","ناتج ضرب نسبة الضغطين في نسبة الحجمين معكوسة (3 × 2)، أي استخدام V1/V2 بدل V2/V1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.470Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2437, 2, 'T1 = 293.0 K ، T2 = 333.0 K ، P2 = P1V1T2/(V2T1) = 100. × 4.00 × 333.0 ÷ (2.50 × 293.0) = 182 kPa.', '["ناتج التعويض بالدرجات السيليزية (60.0 و20.0).","ناتج عكس نسبة الحجمين (V2/V1)، فيقل الضغط مع أن الغاز انضغط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:23.470Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2438, null, null, null, 'المعطيات: V1 = 500. mL ، P1 = 1.20 atm ، T1 = 27.0 + 273 = 300.0 K ، P2 = 0.800 atm ، T2 = −23.0 + 273 = 250.0 K. العلاقة: P1V1/T1 = P2V2/T2 ⇒ V2 = P1V1T2/(P2T1) = 1.20 × 500. × 250.0 ÷ (0.800 × 300.0) = 625 mL.', '["تحويل درجتي الحرارة إلى كلفن","كتابة القانون العام وإعادة ترتيبه لحساب V2","التعويض الصحيح","الناتج 625 mL بالوحدة الصحيحة"]'::jsonb, '["T1 = 300.0 K ، T2 = 250.0 K","V2 = P1V1T2 / (P2T1)","V2 = 1.20 × 500. × 250.0 ÷ (0.800 × 300.0)","V2 = 625 mL"]'::jsonb, '[{"element":"التحويل إلى كلفن","marks":1},{"element":"القانون وإعادة الترتيب","marks":1},{"element":"التعويض","marks":1},{"element":"الناتج والوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات كاملة وناتج 625 mL"},{"level":"3 درجات","description":"خطوات صحيحة مع خطأ في الوحدة أو الأرقام المعنوية"},{"level":"2 درجتان","description":"قانون صحيح مع نسيان التحويل إلى كلفن أو خطأ في إعادة الترتيب"},{"level":"1 درجة","description":"كتابة القانون العام فقط"},{"level":"صفر","description":"قانون خاطئ أو لا إجابة"}]'::jsonb, '["التعويض بالدرجات السيليزية فيظهر حجم سالب","عكس نسبة الضغطين","تحويل mL إلى L دون داعٍ ثم الخطأ في التحويل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.471Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2439, null, null, null, '(أ) انخفاض الضغط إلى 0.300 من قيمته يزيد الحجم بعامل 1.00/0.300 = 3.33 (بويل)، وانخفاض درجة الحرارة من 300 K إلى 240 K يقلل الحجم بعامل 240/300 = 0.800 (شارل)؛ أثر الضغط أكبر، فيزداد الحجم. (ب) V2 = V1 × (P1/P2) × (T2/T1) = 10.0 × (1.00/0.300) × (240/300) = 26.7 L.', '["تحويل درجتي الحرارة إلى كلفن (300 K و240 K)","أثر انخفاض الضغط: زيادة الحجم","أثر انخفاض درجة الحرارة: نقص الحجم","استنتاج أن أثر الضغط أكبر فيزداد الحجم","حساب الحجم 26.7 L"]'::jsonb, '["T1 = 300 K ، T2 = 240 K","V2 = V1 × (P1/P2) × (T2/T1)","V2 = 10.0 × (1.00 ÷ 0.300) × (240 ÷ 300) = 26.7 L"]'::jsonb, '[{"element":"مقارنة أثري الضغط ودرجة الحرارة","marks":2},{"element":"التحويل إلى كلفن","marks":1},{"element":"الحساب والناتج","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة صحيحة مع تعليل وحساب صحيح 26.7 L"},{"level":"4 درجات","description":"حساب صحيح ومقارنة ناقصة التعليل"},{"level":"3 درجات","description":"مقارنة صحيحة وخطأ في الحساب (مثل نسيان الكلفن)"},{"level":"2 درجتان","description":"حكم صحيح بزيادة الحجم دون تعليل أو حساب سليم"},{"level":"1 درجة","description":"كتابة القانون العام فقط"},{"level":"صفر","description":"حكم خاطئ دون حساب أو لا إجابة"}]'::jsonb, '["الحكم بأن البالون ينكمش لأن الجو بارد مع إهمال أثر الضغط","استخدام الدرجات السيليزية (−33 و27) فيظهر حجم سالب","عكس نسبة الضغطين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.471Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2440, null, null, null, 'الخطأ: عوّض الطالب بدرجتي الحرارة بالسيليزي، والقانون العام يتطلب درجة الحرارة المطلقة بالكلفن لأن الحجم يتناسب طرديًا مع T بالكلفن. الحل الصحيح: T1 = 20.0 + 273 = 293.0 K ، T2 = 40.0 + 273 = 313.0 K ، V2 = 1.50 × (1.00/2.00) × (313.0/293.0) = 0.801 L. (مضاعفة الدرجة السيليزية لا تضاعف الحجم.)', '["تحديد الخطأ: استخدام الدرجات السيليزية","تعليل وجوب استخدام الكلفن","التحويل الصحيح إلى 293.0 K و313.0 K","الناتج الصحيح 0.801 L"]'::jsonb, '["T1 = 293.0 K ، T2 = 313.0 K","V2 = V1 × (P1/P2) × (T2/T1)","V2 = 1.50 × 0.500 × 1.068 = 0.801 L"]'::jsonb, '[{"element":"تحديد الخطأ وتعليله","marks":2},{"element":"التحويل إلى كلفن","marks":1},{"element":"الحل والناتج الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ وتعليله وحل صحيح 0.801 L"},{"level":"3 درجات","description":"تحديد الخطأ والحل الصحيح دون تعليل"},{"level":"2 درجتان","description":"تحديد الخطأ فقط أو حل صحيح دون تحديد الخطأ"},{"level":"1 درجة","description":"الإشارة إلى وجود خطأ دون تحديده بدقة"},{"level":"صفر","description":"الحكم بصحة حل الطالب أو لا إجابة"}]'::jsonb, '["الحكم بأن حل الطالب صحيح لأن أثر الضغط يلغي أثر درجة الحرارة","تحويل درجة حرارة واحدة فقط إلى كلفن","عكس نسبة الضغطين في الحل الصحيح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.472Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2441, 1, 'ينص مبدأ أفوجادرو على أن الحجوم المتساوية من الغازات المختلفة تحتوي على العدد نفسه من الجسيمات عند نفس درجة الحرارة والضغط.', '["الكتل تختلف باختلاف الكتلة المولية للغاز، والمبدأ يتحدث عن عدد الجسيمات لا الكتلة.","","المبدأ مشروط بتساوي درجة الحرارة والضغط؛ فتغيّرهما يغيّر الحجم الذي يشغله العدد نفسه من الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:23.475Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2442, 2, 'وفق مبدأ أفوجادرو يتساوى عدد الجسيمات في الحجوم المتساوية عند نفس درجة الحرارة والضغط، بغض النظر عن نوع الغاز.', '["المبدأ ينطبق على غازات مختلفة الكتل المولية والكثافات.","المبدأ لا يشترط تساوي الكتلة، وحجم الجسيمات مهمل مقارنة بالمسافات بينها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.477Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2443, 0, 'الحجم يتناسب طرديًا مع عدد المولات عند ثبوت P وT، فتبقى النسبة V/n ثابتة: V1/n1 = V2/n2.', '["","هذه علاقة تناسب عكسي، أي أن زيادة المولات تقلل الحجم، وهذا يخالف المبدأ.","هذه الصيغة تعكس النسبة فتعني تناسبًا عكسيًا بين الحجم وعدد المولات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:23.478Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2444, 1, 'حسب مبدأ أفوجادرو يحتوي الحجمان المتساويان عند نفس P وT العدد نفسه من الجزيئات، لكن الكتلة المولية لـ CO₂ (44.0 g/mol) أكبر من H₂ (2.0 g/mol) فكتلته أكبر.', '["حجم الجزيئات مهمل مقارنة بالمسافات بينها، فلا يؤثر في عدد الجزيئات.","","الكتلتان مختلفتان لاختلاف الكتلة المولية، وعدد الجزيئات متساوٍ لا مختلف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:23.478Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2445, 2, 'V2 = V1 × n2 ÷ n1 = 12.0 × 1.25 ÷ 0.500 = 30.0 L.', '["ناتج عكس النسبة (V1 × n1 ÷ n2)، فيقل الحجم مع زيادة عدد المولات.","ناتج ضرب الحجم في عدد المولات الجديد دون القسمة على عدد المولات الابتدائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.479Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2446, 1, 'وفق مبدأ أفوجادرو تمثل معاملات الغازات في المعادلة الموزونة نسب حجومها: N₂ : H₂ = 1 : 3، فحجم H₂ = 3 × 2.0 = 6.0 L.', '["افتراض أن الحجوم متساوية دائمًا مع إهمال معاملات المعادلة.","","قسمة الحجم على 3 بدل الضرب، أي عكس النسبة المولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.479Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2447, 0, 'عند نفس P وT يتناسب عدد الجزيئات طرديًا مع الحجم مهما كان نوع الغاز، ووعاء CH₄ أكبرها حجمًا (10.0 L) فيحتوي أكبر عدد من الجزيئات (ضعف كل من الوعاءين الآخرين).', '["","كبر الكتلة المولية لـ O₂ لا يزيد عدد الجزيئات؛ العدد يعتمد على الحجم فقط عند نفس P وT.","الوعاءان متساويان فعلًا، لكن عدد جزيئات كل منهما نصف عدد جزيئات وعاء CH₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:23.479Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2448, null, null, null, 'النص: الحجوم المتساوية من الغازات المختلفة تحتوي على العدد نفسه من الجسيمات عند نفس درجة الحرارة والضغط. العلاقة: V1/n1 = V2/n2، وهي علاقة طردية: يزداد حجم الغاز بزيادة عدد مولاته، بشرط ثبوت درجة الحرارة والضغط.', '["النص الصحيح للمبدأ","ذكر شرط تساوي درجة الحرارة والضغط","العلاقة V1/n1 = V2/n2","العلاقة طردية"]'::jsonb, '[]'::jsonb, '[{"element":"نص المبدأ","marks":1},{"element":"شرط ثبوت P وT","marks":1},{"element":"العلاقة الرياضية","marks":1},{"element":"نوع العلاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص كامل مع الشرط والعلاقة الصحيحة ونوعها"},{"level":"3 درجات","description":"ينقصه عنصر واحد"},{"level":"2 درجتان","description":"النص صحيح دون العلاقة أو العلاقة صحيحة دون النص"},{"level":"1 درجة","description":"ذكر جزئي للنص دون الشرط"},{"level":"صفر","description":"نص خاطئ أو لا إجابة"}]'::jsonb, '["إهمال شرط تساوي درجة الحرارة والضغط","ذكر «الكتلة نفسها» بدل «العدد نفسه من الجسيمات»","كتابة العلاقة V1n1 = V2n2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.480Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2449, null, null, null, 'وفق مبدأ أفوجادرو تحتوي الحجوم المتساوية من الغازات العدد نفسه من الجسيمات عند نفس P وT. والسبب أن جسيمات الغاز متباعدة جدًا، فحجم الجسيمات نفسها مهمل مقارنة بالفراغات بينها، فلا يؤثر حجم الجزيء في الحجم الكلي الذي يشغله الغاز؛ كما أن الكتلة لا تحدد عدد الجسيمات في الحجم، فالكتل تختلف (CO₂ أثقل) لكن عدد الجزيئات متساوٍ.', '["ذكر مبدأ أفوجادرو","جسيمات الغاز متباعدة وحجمها مهمل مقارنة بالفراغات","حجم الجزيء لا يؤثر في عدد الجزيئات في الحجم","الكتلة تختلف مع تساوي العدد"]'::jsonb, '[]'::jsonb, '[{"element":"ربط الإجابة بمبدأ أفوجادرو","marks":1},{"element":"تفسير إهمال حجم الجسيمات","marks":2},{"element":"التمييز بين العدد والكتلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط المبدأ بتباعد الجسيمات ويميز بين العدد والكتلة"},{"level":"3 درجات","description":"تفسير صحيح ينقصه التمييز بين العدد والكتلة"},{"level":"2 درجتان","description":"ذكر المبدأ فقط دون تفسير"},{"level":"1 درجة","description":"إجابة جزئية غير دقيقة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن CO₂ يحتوي جزيئات أقل لأن جزيئاته أكبر","الخلط بين تساوي العدد وتساوي الكتلة","إغفال شرط تساوي درجة الحرارة والضغط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:23.480Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2450, null, null, null, '(أ) V1/n1 = V2/n2 ⇒ V2 = V1 × n2 ÷ n1 = 3.00 × 0.400 ÷ 0.150 = 8.00 L. (ب) الزيادة = 8.00 − 3.00 = 5.00 L. (ج) يتحرك المكبس إلى الخارج لأن الحجم يزداد طرديًا بزيادة عدد المولات عند ثبوت P وT.', '["كتابة العلاقة V1/n1 = V2/n2","التعويض الصحيح","الحجم الجديد 8.00 L","الزيادة 5.00 L","تحرك المكبس للخارج"]'::jsonb, '["V2 = V1 × n2 ÷ n1","V2 = 3.00 × 0.400 ÷ 0.150 = 8.00 L","ΔV = 8.00 − 3.00 = 5.00 L"]'::jsonb, '[{"element":"العلاقة والتعويض","marks":1},{"element":"الحجم الجديد","marks":1},{"element":"حجم الزيادة","marks":1},{"element":"تحديد حركة المكبس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة 8.00 L و5.00 L مع تفسير حركة المكبس"},{"level":"3 درجات","description":"حسابات صحيحة دون تفسير حركة المكبس"},{"level":"2 درجتان","description":"حساب الحجم الجديد فقط"},{"level":"1 درجة","description":"كتابة العلاقة الصحيحة فقط"},{"level":"صفر","description":"علاقة خاطئة أو لا إجابة"}]'::jsonb, '["عكس النسبة فيظهر V2 = 1.13 L","اعتبار الحجم الجديد هو حجم الزيادة","القول إن المكبس يتحرك للداخل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.481Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2451, 0, 'الحجم المولاري هو الحجم الذي يشغله مول واحد من الغاز عند درجة الحرارة والضغط المعياريين (0 °C و1 atm)، وقيمته 22.4 L.', '["","التعريف مرتبط بمول واحد لا بغرام واحد؛ حجم 1 g يختلف من غاز لآخر.","حجم جزيء واحد صغير جدًا، والتعريف يخص مولًا كاملًا (6.02×10²³ جسيم)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.484Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2452, 1, 'الظروف المعيارية STP هي درجة حرارة 0 °C (273 K) وضغط 1 atm، وعندها يشغل 1 mol من أي غاز 22.4 L.', '["25 °C تقارب درجة حرارة الغرفة وليست درجة الحرارة المعيارية.","","الخلط بين 273 K و273 °C؛ درجة الحرارة المعيارية 273 K أي 0 °C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.484Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2453, 2, 'الحجم المولاري لا يعتمد على نوع الغاز؛ فكل غاز يشغل 22.4 L للمول الواحد عند STP.', '["الكتلة المولية لا تؤثر في الحجم المولاري؛ تؤثر في كتلة الحجم لا في مقداره.","عند درجة الحرارة نفسها لا تحدد سرعة الجزيئات الحجم المولاري؛ فهو واحد لجميع الغازات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.485Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2454, 0, 'الحجم المولاري حجم لكل مول، فوحدته لتر لكل مول (L/mol)، مثل 22.4 L/mol عند STP.', '["","mol/L وحدة التركيز المولاري (عدد المولات في لتر)، وهي مقلوب وحدة الحجم المولاري.","g/mol وحدة الكتلة المولية لا الحجم المولاري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.485Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2455, 1, 'الحجم المولاري 22.4 L خاص بالغازات فقط؛ والماء عند 0 °C و1 atm سائل أو صلب، وجسيماته متقاربة جدًا فيشغل 1 mol منه نحو 18 mL فقط.', '["الكتلة المولية لا تحدد الحجم المولاري للغازات، والسبب هو الحالة الفيزيائية.","","القطبية ليست السبب؛ السبب أن الماء ليس غازًا عند هذه الظروف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.485Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2456, 2, 'الحجم المولاري يُعرَّف عند STP (0 °C و1 atm)، وهي ظروف الغاز (أ) فقط، وقيمته 22.4 L. أما القيمتان الأخريان فلمول واحد لكن عند ظروف غير معيارية.', '["24.5 L حجم 1 mol عند 25 °C و1 atm، وهي ليست ظروفًا معيارية.","11.2 L حجم 1 mol عند ضغط 2 atm، وهي ليست ظروفًا معيارية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.485Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2457, 2, 'وفق مبدأ أفوجادرو تحتوي الحجوم المتساوية من الغازات عند نفس P وT العدد نفسه من الجسيمات، فالمول الواحد (6.02×10²³ جسيم) من أي غاز يشغل الحجم نفسه.', '["الكتل المولية للغازات مختلفة (H₂ = 2.0 و O₂ = 32.0 g/mol).","جزيئات الغازات مختلفة الحجم، لكن حجمها مهمل مقارنة بالفراغات بينها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.486Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2458, null, null, null, 'الحجم المولاري: الحجم الذي يشغله مول واحد من الغاز عند الظروف المعيارية (STP). قيمته 22.4 ووحدته L/mol. الظروف المعيارية: درجة حرارة 0 °C أي 273 K، وضغط 1 atm.', '["التعريف الصحيح (حجم 1 mol من الغاز)","القيمة 22.4","الوحدة L/mol","الظروف 0 °C = 273 K و1 atm"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"القيمة والوحدة","marks":1},{"element":"الظروف المعيارية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف صحيح مع القيمة والوحدة والظروف كاملة"},{"level":"2 درجتان","description":"تعريف صحيح مع نقص في القيمة أو الظروف"},{"level":"1 درجة","description":"ذكر القيمة 22.4 L فقط دون تعريف"},{"level":"صفر","description":"تعريف خاطئ أو لا إجابة"}]'::jsonb, '["كتابة «273 °C» أو «273°K» بدل 273 K","تعريفه بأنه حجم 1 g من الغاز","إهمال ذكر الظروف المعيارية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.486Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2459, null, null, null, 'العبارة خاطئة. الحجم المولاري (22.4 L/mol عند STP) خاص بالمواد في الحالة الغازية فقط، لأن جسيمات الغاز متباعدة جدًا وحجمها مهمل، فيتحدد الحجم بعدد الجسيمات لا بنوعها. أما الماء عند 0 °C و1 atm فهو سائل أو صلب، وجسيماته متقاربة، فيشغل 1 mol منه (18.0 g) نحو 18 mL فقط تقريبًا، لا 22.4 L.', '["الحكم بخطأ العبارة","الحجم المولاري خاص بالغازات","الماء عند STP ليس غازًا (سائل أو صلب)","تفسير ذلك بتقارب الجسيمات في السوائل والمواد الصلبة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"تعليل اقتصار الحجم المولاري على الغازات","marks":2},{"element":"ذكر حالة الماء عند STP","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تعليل كامل وذكر حالة الماء"},{"level":"3 درجات","description":"حكم صحيح وتعليل ناقص"},{"level":"2 درجتان","description":"حكم صحيح مع ذكر أن الماء ليس غازًا دون تفسير"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"تأييد العبارة أو لا إجابة"}]'::jsonb, '["تأييد العبارة لأن 22.4 L ثابت لكل المواد","تعليل الخطأ بالكتلة المولية للماء","الظن أن الماء غاز عند 0 °C"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.486Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2460, null, null, null, '(أ) غير صحيح؛ لأن 22.4 L/mol هو الحجم المولاري عند STP فقط (0 °C و1 atm)، وعند 25 °C تكون درجة الحرارة أعلى فيزداد الحجم (الحجم يتناسب طرديًا مع درجة الحرارة المطلقة عند ثبوت الضغط). (ب) V1/T1 = V2/T2: V2 = 22.4 × 298 ÷ 273 = 24.5 L.', '["الحكم بعدم صحة الاستخدام","22.4 L/mol صالح عند STP فقط","زيادة درجة الحرارة تزيد الحجم","التعويض في V1/T1 = V2/T2 بالكلفن","الناتج 24.5 L"]'::jsonb, '["T1 = 273 K ، T2 = 25 + 273 = 298 K","V2 = V1 × T2 ÷ T1","V2 = 22.4 × 298 ÷ 273 = 24.5 L"]'::jsonb, '[{"element":"الحكم والتعليل","marks":2},{"element":"التحويل إلى كلفن والقانون","marks":1},{"element":"الناتج 24.5 L","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم وتعليل صحيحان وحساب صحيح 24.5 L"},{"level":"3 درجات","description":"حكم وتعليل صحيحان مع خطأ في الحساب"},{"level":"2 درجتان","description":"حساب صحيح دون تعليل أو حكم صحيح بتعليل ناقص"},{"level":"1 درجة","description":"حكم صحيح فقط"},{"level":"صفر","description":"الحكم بصحة الاستخدام أو لا إجابة"}]'::jsonb, '["تأييد استخدام 22.4 L عند أي ظروف","التعويض بالسيليزي (22.4 × 25 ÷ 0)","عكس نسبة درجتي الحرارة فيظهر حجم أصغر (20.5 L)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.486Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2461, 1, 'V = n × 22.4 L/mol = 3.00 × 22.4 = 67.2 L.', '["ناتج قسمة الحجم المولاري على عدد المولات (22.4 ÷ 3.00).","","ناتج قسمة عدد المولات على الحجم المولاري (3.00 ÷ 22.4)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:23.490Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2462, 0, 'n = V ÷ 22.4 L/mol = 5.60 ÷ 22.4 = 0.250 mol.', '["","ناتج ضرب الحجم في الحجم المولاري بدل القسمة.","ناتج قسمة الحجم المولاري على الحجم (عكس العلاقة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T13:13:23.490Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
