(2463, 2, 'الكتلة المولية لـ CH₄ = 12.0 + 4(1.0) = 16.0 g/mol ، n = 8.00 ÷ 16.0 = 0.500 mol ، V = 0.500 × 22.4 = 11.2 L.', '["ضرب الكتلة مباشرة في 22.4 دون تحويلها إلى مولات.","حساب عدد المولات بقسمة الكتلة المولية على الكتلة (16.0 ÷ 8.00 = 2.00 mol).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:23.491Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2464, 0, 'n = 2.24 ÷ 22.4 = 0.100 mol ، الكتلة المولية لـ NH₃ = 14.0 + 3(1.0) = 17.0 g/mol ، m = 0.100 × 17.0 = 1.70 g.', '["","ضرب الحجم مباشرة في الكتلة المولية دون تحويله إلى مولات.","حساب عدد المولات بقسمة 22.4 على الحجم (10.0 mol) بدل العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.491Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2465, 1, 'n = 11.2 ÷ 22.4 = 0.500 mol ، عدد الجزيئات = 0.500 × 6.02×10²³ = 3.01×10²³ جزيء.', '["افتراض أن أي حجم من الغاز يحتوي مولًا واحدًا، مع أن 11.2 L نصف الحجم المولاري.","","ضرب الحجم مباشرة في عدد أفوجادرو دون تحويله إلى مولات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T13:13:23.492Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2466, 2, 'عدد المولات: H₂ = 4.00 ÷ 2.0 = 2.00 mol ← 44.8 L ، O₂ = 32.0 ÷ 32.0 = 1.00 mol ← 22.4 L ، CO₂ = 44.0 ÷ 44.0 = 1.00 mol ← 22.4 L؛ فعينة H₂ أكبرها حجمًا.', '["كتلة CO₂ هي الأكبر، لكن الحجم يعتمد على عدد المولات لا على الكتلة (1.00 mol فقط).","عينة O₂ تحتوي 1.00 mol فقط فتشغل 22.4 L، وهو نصف حجم عينة H₂.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T13:13:23.492Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2467, 1, 'كتلة 1 mol = 44.0 g وحجمه 22.4 L عند STP، فالكثافة = 44.0 ÷ 22.4 = 1.96 g/L.', '["ناتج قسمة الحجم المولاري على الكتلة المولية (22.4 ÷ 44.0)، وهذا مقلوب الكثافة.","","ناتج ضرب الكتلة المولية في الحجم المولاري بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-11T13:13:23.492Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2468, null, null, null, 'الكتلة المولية لـ SO₂ = 32.0 + 2(16.0) = 64.0 g/mol. عدد المولات n = 160. ÷ 64.0 = 2.50 mol. الحجم V = n × 22.4 L/mol = 2.50 × 22.4 = 56.0 L.', '["حساب الكتلة المولية 64.0 g/mol","تحويل الكتلة إلى مولات 2.50 mol","استخدام الحجم المولاري 22.4 L/mol","الناتج 56.0 L"]'::jsonb, '["M(SO₂) = 32.0 + 2 × 16.0 = 64.0 g/mol","n = 160. ÷ 64.0 = 2.50 mol","V = 2.50 × 22.4 = 56.0 L"]'::jsonb, '[{"element":"الكتلة المولية","marks":1},{"element":"عدد المولات","marks":1},{"element":"الحجم والوحدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"خطوات كاملة وناتج 56.0 L"},{"level":"2 درجتان","description":"خطأ في الكتلة المولية مع تطبيق صحيح للخطوات"},{"level":"1 درجة","description":"حساب الكتلة المولية فقط"},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة"}]'::jsonb, '["حساب الكتلة المولية 48.0 g/mol (نسيان ذرة أكسجين)","قسمة الحجم المولاري على عدد المولات","ضرب الكتلة مباشرة في 22.4"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T13:13:23.493Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2469, null, null, null, 'n = V ÷ 22.4 = 5.00 ÷ 22.4 = 0.223 mol. الكتلة المولية لـ Cl₂ = 2 × 35.5 = 71.0 g/mol، فالكتلة m = 0.223 × 71.0 = 15.8 g. عدد الجزيئات = 0.223 × 6.02×10²³ = 1.34×10²³ جزيء.', '["حساب عدد المولات 0.223 mol","الكتلة المولية لـ Cl₂ = 71.0 g/mol","الكتلة 15.8 g","عدد الجزيئات 1.34×10²³"]'::jsonb, '["n = 5.00 ÷ 22.4 = 0.223 mol","M(Cl₂) = 2 × 35.5 = 71.0 g/mol","m = 0.223 × 71.0 = 15.8 g","N = 0.223 × 6.02×10²³ = 1.34×10²³ جزيء"]'::jsonb, '[{"element":"عدد المولات","marks":1},{"element":"الكتلة المولية والكتلة","marks":2},{"element":"عدد الجزيئات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة كاملة: 15.8 g و1.34×10²³ جزيء"},{"level":"3 درجات","description":"خطأ في جزء واحد (مثل استخدام 35.5 كتلة مولية لـ Cl₂)"},{"level":"2 درجتان","description":"حساب عدد المولات وأحد المطلوبين فقط"},{"level":"1 درجة","description":"حساب عدد المولات فقط"},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة"}]'::jsonb, '["استخدام 35.5 g/mol كتلة مولية لـ Cl₂ فتظهر الكتلة 7.92 g","ضرب الحجم في 22.4 بدل القسمة","حساب عدد الذرات بدل الجزيئات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.493Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2470, null, null, null, 'الكتلة المولية لـ CaCO₃ = 40.0 + 12.0 + 3(16.0) = 100.0 g/mol. عدد مولات CaCO₃ = 25.0 ÷ 100.0 = 0.250 mol. من المعادلة: 1 mol CaCO₃ يعطي 1 mol CO₂، فعدد مولات CO₂ = 0.250 mol. الحجم = 0.250 × 22.4 = 5.60 L عند STP.', '["الكتلة المولية لـ CaCO₃ = 100.0 g/mol","عدد مولات CaCO₃ = 0.250 mol","النسبة المولية 1 : 1 من المعادلة","حجم CO₂ = 5.60 L"]'::jsonb, '["M(CaCO₃) = 40.0 + 12.0 + 48.0 = 100.0 g/mol","n(CaCO₃) = 25.0 ÷ 100.0 = 0.250 mol","n(CO₂) = n(CaCO₃) = 0.250 mol","V(CO₂) = 0.250 × 22.4 = 5.60 L"]'::jsonb, '[{"element":"الكتلة المولية وعدد المولات","marks":2},{"element":"النسبة المولية","marks":1},{"element":"الحجم النهائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات كاملة وناتج 5.60 L"},{"level":"3 درجات","description":"خطوات صحيحة مع خطأ في الأرقام المعنوية أو الوحدة"},{"level":"2 درجتان","description":"حساب مولات CaCO₃ صحيح مع خطأ في الربط بالمعادلة أو الحجم"},{"level":"1 درجة","description":"حساب الكتلة المولية فقط"},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة"}]'::jsonb, '["استخدام الحجم المولاري مع المادة الصلبة CaCO₃ مباشرة","الخطأ في الكتلة المولية لـ CaCO₃","ضرب الكتلة في 22.4 دون التحويل إلى مولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.493Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2471, 1, 'قانون الغاز المثالي: PV = nRT، حيث يتناسب حاصل ضرب الضغط في الحجم طرديًا مع عدد المولات ودرجة الحرارة المطلقة.', '["القسمة على T تعني أن PV يقل بالتسخين، وهذا يخالف قانوني شارل وجاي لوساك.","","ضرب الحجم في الطرف الأيمن يعني أن الضغط يزداد بزيادة الحجم، وهذا يخالف قانون بويل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.497Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2472, 2, 'يربط قانون الغاز المثالي بين المتغيرات الأربعة: الضغط P والحجم V ودرجة الحرارة T وعدد المولات n.', '["هذه متغيرات القانون العام للغازات الذي يفترض ثبات كمية الغاز.","أُغفلت درجة الحرارة وهي متغير أساسي في القانون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.497Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2473, 2, 'R = 0.0821 L·atm/(mol·K)؛ أما 8.314 فتستخدم مع kPa، و62.4 مع mmHg.', '["8.314 هي قيمة R عند قياس الضغط بوحدة kPa لا atm.","62.4 هي قيمة R عند قياس الضغط بوحدة mmHg لا atm.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:23.497Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2474, 0, 'وحدة R تتضمن الكلفن (L·atm/(mol·K))، ودرجة الحرارة في قوانين الغازات تكون مطلقة دائمًا، فتُعوّض بالكلفن.', '["","السيليزي لا يبدأ من الصفر المطلق، فقد يعطي قيمًا صفرية أو سالبة مستحيلة.","الفهرنهايت لا يتوافق مع وحدة R ولا يبدأ من الصفر المطلق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:23.497Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2475, 1, 'عند الضغط المنخفض تتباعد الجسيمات فيصبح حجمها مهملًا، وعند درجة الحرارة المرتفعة تكون طاقتها الحركية كبيرة فتضعف أثر قوى التجاذب بينها، فيقترب الغاز من السلوك المثالي.', '["هذه الظروف تُبعد الغاز عن السلوك المثالي؛ فتتقارب الجسيمات وتزداد أهمية قوى التجاذب وقد يتكثف الغاز.","","الضغط المرتفع يقرّب الجسيمات فيصبح حجمها مؤثرًا، فينحرف الغاز عن السلوك المثالي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.498Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2476, 2, 'T = 27 + 273 = 300 K ، n = PV/(RT) = (2.00 × 4.10) ÷ (0.0821 × 300) = 0.333 mol.', '["ناتج التعويض بالدرجة السيليزية (27) بدل الكلفن.","ناتج قلب العلاقة n = RT/(PV).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.498Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2477, 0, 'يجب أن تتوافق وحدة الضغط مع وحدة R؛ ومع mmHg تُستخدم R = 62.4 L·mmHg/(mol·K).', '["","8.314 تتوافق مع kPa، واستخدامها مع mmHg يعطي ناتجًا خاطئًا.","0.0821 تتوافق مع atm، واستخدامها مع mmHg دون تحويل يعطي ناتجًا خاطئًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:23.498Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2478, null, null, null, 'نص القانون: قانون الغاز المثالي يربط بين الضغط والحجم ودرجة الحرارة وعدد المولات لكمية من الغاز. العلاقة: PV = nRT. حيث P الضغط (atm)، وV الحجم (L)، وn عدد المولات (mol)، وR ثابت الغاز المثالي = 0.0821 L·atm/(mol·K)، وT درجة الحرارة المطلقة (K).', '["النص: يربط بين P وV وT وn","العلاقة PV = nRT","دلالة الرموز الخمسة","الوحدات الصحيحة (atm ، L ، mol ، K ، L·atm/(mol·K))"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون","marks":1},{"element":"العلاقة الرياضية","marks":1},{"element":"دلالة الرموز","marks":1},{"element":"الوحدات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نص صحيح وعلاقة صحيحة ودلالة الرموز ووحداتها كاملة"},{"level":"3 درجات","description":"ينقصه عنصر واحد (مثل وحدة R)"},{"level":"2 درجتان","description":"العلاقة صحيحة مع دلالة الرموز دون الوحدات أو النص"},{"level":"1 درجة","description":"كتابة العلاقة فقط"},{"level":"صفر","description":"علاقة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة وحدة درجة الحرارة °C","كتابة وحدة R خاطئة أو ناقصة","الخلط بين قانون الغاز المثالي والقانون العام للغازات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-11T13:13:23.498Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2479, null, null, null, 'T = 25.0 + 273 = 298 K. P = nRT/V = 0.250 × 0.0821 × 298 ÷ 5.00 = 1.22 atm. وبالكيلوباسكال: P = 0.250 × 8.314 × 298 ÷ 5.00 = 124 kPa. التحقق: 1.22 × 101.3 = 124 kPa، فالناتجان متسقان.', '["تحويل درجة الحرارة إلى 298 K","إعادة ترتيب القانون P = nRT/V","الناتج 1.22 atm","الناتج 124 kPa","التحقق من الاتساق"]'::jsonb, '["T = 298 K","P = nRT/V","P = 0.250 × 0.0821 × 298 ÷ 5.00 = 1.22 atm","P = 0.250 × 8.314 × 298 ÷ 5.00 = 124 kPa","1.22 × 101.3 = 124 kPa"]'::jsonb, '[{"element":"التحويل وإعادة الترتيب","marks":1},{"element":"الناتج بوحدة atm","marks":1},{"element":"الناتج بوحدة kPa","marks":1},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان مع التحقق"},{"level":"3 درجات","description":"حسابان صحيحان دون تحقق"},{"level":"2 درجتان","description":"حساب واحد صحيح"},{"level":"1 درجة","description":"كتابة القانون وإعادة ترتيبه فقط"},{"level":"صفر","description":"لا إجابة أو طريقة خاطئة"}]'::jsonb, '["التعويض بالدرجة السيليزية","استخدام 8.314 مع atm أو 0.0821 مع kPa","قسمة على 101.3 بدل الضرب في التحقق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.499Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2480, null, null, null, 'قانون بويل: عند ثبوت n وT يكون الطرف الأيمن nRT ثابتًا، فيبقى PV ثابتًا، أي P1V1 = P2V2 (علاقة عكسية بين الضغط والحجم). مبدأ أفوجادرو: بإعادة الترتيب V/n = RT/P، وعند ثبوت P وT يكون RT/P ثابتًا، فتبقى V/n ثابتة، أي V1/n1 = V2/n2 (الحجم يتناسب طرديًا مع عدد المولات).', '["بويل: ثبات n وT","PV = ثابت ⇒ P1V1 = P2V2","أفوجادرو: ثبات P وT","V/n = RT/P ثابت ⇒ V1/n1 = V2/n2"]'::jsonb, '[]'::jsonb, '[{"element":"اشتقاق قانون بويل مع الثوابت","marks":2},{"element":"اشتقاق مبدأ أفوجادرو مع الثوابت","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"اشتقاقان صحيحان مع تحديد الكميات الثابتة"},{"level":"3 درجات","description":"اشتقاقان صحيحان مع نقص في تحديد الثوابت"},{"level":"2 درجتان","description":"اشتقاق واحد صحيح كامل"},{"level":"1 درجة","description":"ذكر الكميات الثابتة دون اشتقاق"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار R متغيرًا","ذكر ثبات الضغط في قانون بويل","كتابة V1n1 = V2n2 لمبدأ أفوجادرو"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:23.499Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2481, 1, 'عندما يكون الضغط بوحدة atm والحجم باللتر تكون R = 0.0821 L·atm/(mol·K)؛ أما 8.314 فتقترن بوحدة kPa، و62.4 تقترن بوحدة mmHg.', '["القيمة 8.314 صحيحة لكن وحدتها L·kPa/(mol·K) وتُستخدم عندما يكون الضغط بوحدة kPa.","","القيمة 62.4 صحيحة لكن وحدتها L·mmHg/(mol·K) وتُستخدم عندما يكون الضغط بوحدة mmHg أو torr."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-11T13:13:23.504Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2482, 2, 'T = 27 + 273 = 300 K، ثم n = PV ÷ RT = (2.00 × 5.00) ÷ (0.0821 × 300) = 0.406 mol.', '["ناتج التعويض بدرجة الحرارة 27 °C دون تحويلها إلى كلفن.","ناتج قلب العلاقة (RT ÷ PV) بدل PV ÷ RT.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:23.505Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2483, 0, 'T = 57 + 273 = 330 K، ثم P = nRT ÷ V = (0.500 × 0.0821 × 330) ÷ 10.0 = 1.35 atm.', '["","ناتج استخدام 57 °C مباشرة دون التحويل إلى كلفن.","ناتج ضرب nRT في الحجم بدل القسمة عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:23.505Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2484, 1, 'T = 77 + 273 = 350 K، ثم V = nRT ÷ P = (2.00 × 0.0821 × 350) ÷ 1.50 = 38.3 L.', '["ناتج استخدام 77 °C دون تحويلها إلى كلفن.","","ناتج ضرب nRT في الضغط بدل القسمة عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.505Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2485, 2, 'T = PV ÷ nR = (1.20 × 5.00) ÷ (0.250 × 0.0821) = 292 K (وتعادل 19 °C تقريبًا).', '["19 هي درجة الحرارة بالسلسيوس (292 − 273)، وليست بالكلفن.","ناتج إضافة 273 إلى 292 K ظنًّا أن الناتج بالسلسيوس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.506Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2486, 0, 'من PV = nRT يكون P = nRT ÷ V، وعند ثبات V وT يتناسب الضغط طرديًا مع عدد المولات، فمضاعفة المولات تضاعف الضغط.', '["","هذا يعني تناسبًا عكسيًا بين الضغط وعدد المولات، والعلاقة طردية.","الضغط يعتمد على عدد المولات، فزيادة الجسيمات تزيد التصادمات بجدران الوعاء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-11T13:13:23.506Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2487, 1, 'n = PV ÷ RT: العينة (أ) = (2.0 × 3.0) ÷ (0.0821 × 300) = 0.24 mol، و(ب) = (1.0 × 4.0) ÷ (0.0821 × 250) = 0.19 mol، و(ج) = (3.0 × 1.5) ÷ (0.0821 × 400) = 0.14 mol؛ فالعينة (أ) هي الأكبر.', '["حجمها هو الأكبر لكن ضغطها منخفض، فعدد مولاتها 0.19 mol فقط.","","ضغطها هو الأكبر لكن حجمها صغير ودرجة حرارتها عالية، فعدد مولاتها 0.14 mol فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:23.506Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2488, null, null, null, 'المعطيات: V = 12.0 L ، P = 150. atm ، T = 25 + 273 = 298 K. المطلوب: n. من PV = nRT: n = PV ÷ RT = (150. × 12.0) ÷ (0.0821 × 298) = 73.6 mol.', '["تحويل درجة الحرارة إلى كلفن (298 K)","إعادة ترتيب القانون: n = PV ÷ RT","التعويض الصحيح","الناتج 73.6 mol بالوحدة الصحيحة"]'::jsonb, '["T = 25 + 273 = 298 K","n = PV ÷ RT","n = (150. × 12.0) ÷ (0.0821 × 298)","n = 1800 ÷ 24.47 = 73.6 mol"]'::jsonb, '[{"element":"تحويل درجة الحرارة إلى كلفن","marks":1},{"element":"إعادة ترتيب القانون","marks":1},{"element":"التعويض الصحيح","marks":1},{"element":"الناتج والوحدة والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات كاملة وناتج 73.6 mol بالوحدة الصحيحة"},{"level":"3 درجات","description":"خطوات صحيحة مع خطأ في الأرقام المعنوية أو الوحدة"},{"level":"2 درجتان","description":"ترتيب القانون صحيح مع نسيان التحويل إلى كلفن (877 mol)"},{"level":"1 درجة","description":"كتابة القانون PV = nRT فقط"},{"level":"صفر","description":"لا إجابة أو علاقة خاطئة"}]'::jsonb, '["التعويض بـ 25 °C فيكون الناتج 877 mol","كتابة n = RT ÷ PV","استخدام R = 8.314 مع الضغط بوحدة atm"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.507Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2489, null, null, null, 'T = 37 + 273 = 310 K. (أ) V = nRT ÷ P = (0.0500 × 8.314 × 310) ÷ 202.6 = 0.636 L. (ب) P = 202.6 ÷ 101.3 = 2.000 atm، V = (0.0500 × 0.0821 × 310) ÷ 2.000 = 0.636 L. الاستنتاج: الناتج واحد بالطريقتين بشرط أن تتوافق وحدة الضغط مع قيمة R المستخدمة.', '["تحويل درجة الحرارة إلى 310 K","الحل بالطريقة (أ) والوصول إلى 0.636 L","تحويل الضغط إلى 2.000 atm","الحل بالطريقة (ب) والوصول إلى 0.636 L","استنتاج ضرورة توافق وحدة الضغط مع وحدة R"]'::jsonb, '["T = 37 + 273 = 310 K","(أ) V = (0.0500 × 8.314 × 310) ÷ 202.6 = 0.636 L","(ب) P = 202.6 kPa ÷ 101.3 = 2.000 atm","V = (0.0500 × 0.0821 × 310) ÷ 2.000 = 0.636 L","المقارنة: الناتجان متساويان"]'::jsonb, '[{"element":"تحويل درجة الحرارة","marks":1},{"element":"الطريقة (أ)","marks":1},{"element":"تحويل الضغط إلى atm","marks":1},{"element":"الطريقة (ب)","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات كاملة صحيحة وناتج صحيح بالوحدة والأرقام المعنوية الصحيحة"},{"level":"4 درجات","description":"الحسابان صحيحان دون استنتاج واضح"},{"level":"3 درجات","description":"حساب واحد صحيح كامل مع خطأ في الآخر"},{"level":"2 درجتان","description":"تحويل درجة الحرارة والضغط صحيحان دون إكمال الحسابات"},{"level":"1 درجة","description":"تحويل واحد صحيح فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام R = 0.0821 مع الضغط بوحدة kPa فيكون الحجم صغيرًا جدًّا","ضرب الضغط في 101.3 بدل القسمة عند التحويل إلى atm","نسيان التحويل إلى كلفن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-11T13:13:23.507Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2490, null, null, null, 'التعليل: لأن الضغط والحجم يتناسبان طرديًا مع درجة الحرارة المطلقة؛ فالتدريج السلسيوسي يحوي صفرًا وقيمًا سالبة، والتعويض بها يعطي حجمًا أو ضغطًا صفريًّا أو سالبًا وهذا مستحيل، كما أن قيمة R محسوبة بالكلفن. الحساب: T = 20 + 273 = 293 K، P = nRT ÷ V = (0.150 × 62.4 × 293) ÷ 4.00 = 686 mmHg.', '["ذكر أن الضغط والحجم يتناسبان مع درجة الحرارة المطلقة","بيان أن التعويض بالسلسيوس قد يعطي قيمًا صفرية أو سالبة مستحيلة","تحويل درجة الحرارة إلى 293 K","الناتج 686 mmHg"]'::jsonb, '["T = 20 + 273 = 293 K","P = nRT ÷ V","P = (0.150 × 62.4 × 293) ÷ 4.00","P = 686 mmHg"]'::jsonb, '[{"element":"التعليل","marks":2},{"element":"تحويل درجة الحرارة والعلاقة","marks":1},{"element":"الناتج والوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل سليم وناتج 686 mmHg"},{"level":"3 درجات","description":"تعليل ناقص مع حساب صحيح، أو تعليل صحيح مع خطأ حسابي بسيط"},{"level":"2 درجتان","description":"تعليل صحيح فقط أو حساب صحيح فقط"},{"level":"1 درجة","description":"تحويل درجة الحرارة فقط أو تعليل ناقص فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الاكتفاء بقول «لأنه القانون» دون تفسير","استخدام 20 °C فيكون الناتج 46.8 mmHg","استخدام R = 0.0821 مع طلب الناتج بوحدة mmHg دون التحويل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.507Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2491, 0, 'PV = (m ÷ MM)RT، وبإعادة الترتيب: MM = mRT ÷ PV.', '["","هذه مقلوب العلاقة الصحيحة، وتعطي وحدة mol/g لا g/mol.","وضع الضغط والحجم في البسط خطأ في إعادة الترتيب؛ فهما في المقام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.511Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2492, 2, 'T = 300 K، MM = mRT ÷ PV = (1.28 × 0.0821 × 300) ÷ (2.00 × 0.500) = 31.5 g/mol.', '["ناتج التعويض بـ 27 °C دون تحويلها إلى كلفن.","ناتج مقلوب العلاقة (PV ÷ mRT).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T13:13:23.511Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2493, 1, 'T = 298 K، n = PV ÷ RT = (2.00 × 5.00) ÷ (0.0821 × 298) = 0.409 mol، ثم m = n × MM = 0.409 × 44.0 = 18.0 g.', '["ناتج استخدام 25 °C دون تحويلها إلى كلفن.","","ناتج قسمة عدد المولات على الكتلة المولية بدل الضرب فيها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-11T13:13:23.512Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2494, 0, 'MM = mRT ÷ PV = (1.60 × 0.0821 × 300) ÷ (1.00 × 1.23) = 32.0 g/mol، وهي الكتلة المولية للأكسجين O2.', '["","الكتلة المولية لـ N2 هي 28.0 g/mol، أقل من القيمة المحسوبة.","الكتلة المولية لـ CO2 هي 44.0 g/mol، أكبر من القيمة المحسوبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T13:13:23.512Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2495, 2, 'تساوي P وV وT يعني تساوي عدد المولات (n = PV ÷ RT)، وبما أن MM = m ÷ n فإن مضاعفة الكتلة مع ثبات n تعني مضاعفة الكتلة المولية.', '["هذا يعني علاقة عكسية بين الكتلة والكتلة المولية، والعلاقة طردية عند ثبات عدد المولات.","تساوي عدد المولات لا يعني تساوي الكتل المولية ما دامت الكتلتان مختلفتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.513Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2496, 1, 'الكتلة المولية تتناسب طرديًا مع T في العلاقة MM = mRT ÷ PV، والتعويض بـ 27 بدل 300 يجعل الناتج أصغر بنحو 11 مرة.', '["T في البسط، فتصغيرها يصغّر الناتج لا يكبّره.","","تغيير قيمة T المعوّضة يغيّر الناتج لأن T جزء من العلاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.513Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2497, 0, 'T = 127 + 273 = 400 K، n = PV ÷ RT = (3.00 × 10.0) ÷ (0.0821 × 400) = 0.914 mol، m = 0.914 × 17.0 = 15.5 g.', '["","هذا عدد المولات وليس الكتلة؛ لم يُضرب في الكتلة المولية.","ناتج استخدام 127 °C دون تحويلها إلى كلفن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-11T13:13:23.513Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2498, null, null, null, 'التحويلات: V = 250. mL = 0.250 L ، P = 745 ÷ 760 = 0.980 atm ، T = 27 + 273 = 300 K. MM = mRT ÷ PV = (0.548 × 0.0821 × 300) ÷ (0.980 × 0.250) = 55.1 g/mol.', '["تحويل الحجم إلى لتر","تحويل الضغط إلى atm","تحويل درجة الحرارة إلى كلفن","كتابة العلاقة MM = mRT ÷ PV والتعويض","الناتج 55.1 g/mol"]'::jsonb, '["V = 250. ÷ 1000 = 0.250 L","P = 745 ÷ 760 = 0.980 atm","T = 27 + 273 = 300 K","MM = (0.548 × 0.0821 × 300) ÷ (0.980 × 0.250)","MM = 55.1 g/mol"]'::jsonb, '[{"element":"تحويل الحجم","marks":1},{"element":"تحويل الضغط","marks":1},{"element":"تحويل درجة الحرارة","marks":1},{"element":"العلاقة والتعويض","marks":1},{"element":"الناتج والوحدة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التحويلات الثلاثة صحيحة وناتج 55.1 g/mol"},{"level":"4 درجات","description":"خطأ في تحويل واحد مع صحة بقية الخطوات"},{"level":"3 درجات","description":"خطآن في التحويلات مع علاقة صحيحة"},{"level":"2 درجتان","description":"العلاقة صحيحة دون تحويلات"},{"level":"1 درجة","description":"كتابة PV = nRT فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["التعويض بالحجم 250 mL فيكون الناتج 0.0551 g/mol","التعويض بالضغط 745 مع R = 0.0821","نسيان التحويل إلى كلفن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:23.514Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2499, null, null, null, 'MM(CH4) = 12.0 + 4(1.0) = 16.0 g/mol ، T = 293 K. n = PV ÷ RT = (5.00 × 20.0) ÷ (0.0821 × 293) = 4.16 mol ، m = n × MM = 4.16 × 16.0 = 66.5 g. (أو مباشرة m = PV·MM ÷ RT = 66.5 g)', '["حساب الكتلة المولية للميثان 16.0 g/mol","تحويل درجة الحرارة إلى 293 K","حساب عدد المولات 4.16 mol","حساب الكتلة 66.5 g"]'::jsonb, '["MM = 12.0 + 4 × 1.0 = 16.0 g/mol","T = 20 + 273 = 293 K","n = (5.00 × 20.0) ÷ (0.0821 × 293) = 4.16 mol","m = 4.16 × 16.0 = 66.5 g"]'::jsonb, '[{"element":"الكتلة المولية","marks":1},{"element":"تحويل درجة الحرارة","marks":1},{"element":"عدد المولات","marks":1},{"element":"الكتلة النهائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الخطوات صحيحة والناتج 66.5 g"},{"level":"3 درجات","description":"خطوات صحيحة مع خطأ حسابي بسيط أو في الأرقام المعنوية"},{"level":"2 درجتان","description":"حساب عدد المولات صحيحًا دون حساب الكتلة"},{"level":"1 درجة","description":"الكتلة المولية أو تحويل درجة الحرارة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["التعويض بـ 20 °C فيكون الناتج 974 g","قسمة عدد المولات على الكتلة المولية","حساب الكتلة المولية للميثان خطأً (مثل 13.0 g/mol)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-11T13:13:23.514Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2500, null, null, null, 'MM = mRT ÷ PV، وبما أن RT ÷ PV = (0.0821 × 273) ÷ (1.00 × 1.00) = 22.4 g/mol لكل غرام: X: 1.43 × 22.4 = 32.1 g/mol ← O2. Y: 1.25 × 22.4 = 28.0 g/mol ← N2. Z: 1.96 × 22.4 = 43.9 g/mol ← CO2. (CH4 كتلته المولية 16.0 g/mol ولا يطابق أيًّا منها.)', '["كتابة العلاقة MM = mRT ÷ PV","حساب MM للغاز X وتحديده O2","حساب MM للغاز Y وتحديده N2","حساب MM للغاز Z وتحديده CO2"]'::jsonb, '["RT ÷ PV = (0.0821 × 273) ÷ (1.00 × 1.00) = 22.4","MM(X) = 1.43 × 22.4 = 32.1 g/mol ← O2","MM(Y) = 1.25 × 22.4 = 28.0 g/mol ← N2","MM(Z) = 1.96 × 22.4 = 43.9 g/mol ← CO2"]'::jsonb, '[{"element":"العلاقة","marks":1},{"element":"الغاز X","marks":1},{"element":"الغاز Y","marks":1},{"element":"الغاز Z","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العلاقة صحيحة والغازات الثلاثة محددة بحسابات صحيحة"},{"level":"3 درجات","description":"غازان صحيحان"},{"level":"2 درجتان","description":"غاز واحد صحيح"},{"level":"1 درجة","description":"العلاقة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["قسمة الكتلة على 22.4 بدل الضرب","المطابقة بالكتلة بدل الكتلة المولية","نسيان أن الحجم 1.00 L في المقام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.515Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2501, 1, 'PV = (m ÷ MM)RT ⇒ m ÷ V = P·MM ÷ RT، أي D = P·MM ÷ RT.', '["هذه مقلوب العلاقة الصحيحة، ووحدتها L/g لا g/L.","","موضع P وT مقلوب؛ فالكثافة تزداد بزيادة الضغط وتقل بزيادة درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.518Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2502, 2, 'D = P·MM ÷ RT = (1.00 × 44.0) ÷ (0.0821 × 273) = 1.96 g/L (وتساوي أيضًا 44.0 ÷ 22.4).', '["ناتج مقلوب العلاقة (RT ÷ P·MM) أو 22.4 ÷ 44.0.","ناتج ضرب الكتلة المولية في 22.4 بدل القسمة عليه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:23.519Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2503, 0, 'T = 300 K، D = P·MM ÷ RT = (2.00 × 32.0) ÷ (0.0821 × 300) = 2.60 g/L.', '["","ناتج التعويض بـ 27 °C دون تحويلها إلى كلفن.","ناتج مقلوب العلاقة (RT ÷ P·MM)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.519Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2504, 2, 'MM = DRT ÷ P = (1.25 × 0.0821 × 273) ÷ 1.00 = 28.0 g/mol.', '["ناتج قسمة الكثافة على RT (أو على 22.4) بدل الضرب.","ناتج قسمة RT على الكثافة (RT ÷ DP).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:23.520Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2505, 1, 'من D = P·MM ÷ RT، عند ثبات الضغط والكتلة المولية تقل الكثافة بارتفاع درجة الحرارة، فيصبح الهواء الساخن أقل كثافة من الهواء المحيط فيرتفع المنطاد.', '["سرعة الجسيمات تزيد فعلًا لكن ذلك يباعد بينها ويقلل الكثافة لا يزيدها.","","ثبات الكتلة المولية لا يعني ثبات الكثافة؛ فدرجة الحرارة في مقام العلاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:23.520Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2506, 0, 'عند ثبات P وT تتناسب الكثافة طرديًا مع الكتلة المولية (D = P·MM ÷ RT)، وأكبر كتلة مولية في الجدول لـ Cl2 (71.0 g/mol)، فكثافته هي الأكبر.', '["","كتلته المولية 16.0 g/mol، أقل من Cl2، فكثافته أقل.","له أصغر كتلة مولية (4.0 g/mol)، فكثافته هي الأقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-11T13:13:23.520Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2507, 2, 'T = 323 K، MM = DRT ÷ P = (3.62 × 0.0821 × 323) ÷ 1.50 = 64.0 g/mol، وهي الكتلة المولية لـ SO2 (32.0 + 2 × 16.0).', '["كتلته المولية 32.0 g/mol، أي نصف القيمة المحسوبة.","كتلته المولية 71.0 g/mol، أكبر من القيمة المحسوبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:23.521Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2508, null, null, null, 'الاشتقاق: PV = nRT و n = m ÷ MM ⇒ PV = (m ÷ MM)RT ⇒ MM = mRT ÷ PV، وبما أن D = m ÷ V فإن MM = DRT ÷ P. الحساب: T = 300 K، MM = (2.40 × 0.0821 × 300) ÷ 1.50 = 39.4 g/mol.', '["التعويض عن n بـ m ÷ MM","التعويض عن m ÷ V بالكثافة والوصول إلى MM = DRT ÷ P","تحويل درجة الحرارة إلى 300 K","الناتج 39.4 g/mol"]'::jsonb, '["PV = (m ÷ MM)RT ⇒ MM = mRT ÷ PV","D = m ÷ V ⇒ MM = DRT ÷ P","T = 27 + 273 = 300 K","MM = (2.40 × 0.0821 × 300) ÷ 1.50 = 39.4 g/mol"]'::jsonb, '[{"element":"الاشتقاق","marks":2},{"element":"تحويل درجة الحرارة","marks":1},{"element":"التعويض والناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اشتقاق صحيح وناتج 39.4 g/mol"},{"level":"3 درجات","description":"اشتقاق ناقص مع حساب صحيح"},{"level":"2 درجتان","description":"حساب صحيح دون اشتقاق، أو اشتقاق صحيح دون حساب"},{"level":"1 درجة","description":"كتابة العلاقة النهائية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["التعويض بـ 27 °C فيكون الناتج 3.55 g/mol","كتابة MM = DP ÷ RT","الخلط بين الكثافة والكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:23.521Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2509, null, null, null, 'MM(Cl2) = 2 × 35.5 = 71.0 g/mol ، P = 740 ÷ 760 = 0.974 atm ، T = 298 K. D = P·MM ÷ RT = (0.974 × 71.0) ÷ (0.0821 × 298) = 2.83 g/L. بما أن كثافة الكلور أكبر من كثافة الهواء (نحو 2.5 مرة) فإنه يتجمع قرب سطح الأرض وفي الأماكن المنخفضة.', '["حساب الكتلة المولية 71.0 g/mol","تحويل الضغط إلى 0.974 atm ودرجة الحرارة إلى 298 K","حساب الكثافة 2.83 g/L","الاستنتاج: يتجمع قرب سطح الأرض لأن كثافته أكبر من الهواء"]'::jsonb, '["MM = 2 × 35.5 = 71.0 g/mol","P = 740 ÷ 760 = 0.974 atm ، T = 25 + 273 = 298 K","D = (0.974 × 71.0) ÷ (0.0821 × 298) = 2.83 g/L","المقارنة: 2.83 g/L > 1.15 g/L"]'::jsonb, '[{"element":"الكتلة المولية","marks":1},{"element":"التحويلات","marks":1},{"element":"الكثافة","marks":1},{"element":"المقارنة والاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة واستنتاج سليم مع التعليل"},{"level":"3 درجات","description":"خطأ في تحويل واحد مع استنتاج سليم"},{"level":"2 درجتان","description":"العلاقة صحيحة مع خطأين، أو استنتاج دون حساب"},{"level":"1 درجة","description":"الكتلة المولية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام 35.5 g/mol كتلةً مولية لجزيء الكلور","التعويض بالضغط 740 مع R = 0.0821","التعويض بـ 25 °C"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.521Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2510, null, null, null, '(أ) D = (1.00 × 44.0) ÷ (0.0821 × 273) = 1.96 g/L. (ب) D = (1.00 × 44.0) ÷ (0.0821 × 546) = 0.982 g/L. (ج) D = (2.00 × 44.0) ÷ (0.0821 × 273) = 3.93 g/L. التفسير: مضاعفة درجة الحرارة المطلقة عند ضغط ثابت تزيد طاقة حركة الجسيمات فتتباعد ويتضاعف الحجم فتقل الكثافة إلى النصف؛ ومضاعفة الضغط عند درجة حرارة ثابتة تقرّب الجسيمات فيقل الحجم إلى النصف وتتضاعف الكثافة.', '["الكثافة في (أ) 1.96 g/L","الكثافة في (ب) 0.982 g/L","الكثافة في (ج) 3.93 g/L","تفسير أثر درجة الحرارة (تباعد الجسيمات وزيادة الحجم)","تفسير أثر الضغط (تقارب الجسيمات ونقصان الحجم)"]'::jsonb, '["(أ) D = 44.0 ÷ (0.0821 × 273) = 1.96 g/L","(ب) D = 44.0 ÷ (0.0821 × 546) = 0.982 g/L","(ج) D = (2.00 × 44.0) ÷ (0.0821 × 273) = 3.93 g/L"]'::jsonb, '[{"element":"الحالة (أ)","marks":1},{"element":"الحالة (ب)","marks":1},{"element":"الحالة (ج)","marks":1},{"element":"تفسير أثر درجة الحرارة","marks":1},{"element":"تفسير أثر الضغط","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات الثلاثة صحيحة والتفسيران سليمان"},{"level":"4 درجات","description":"الحسابات صحيحة مع تفسير واحد"},{"level":"3 درجات","description":"الحسابات صحيحة دون تفسير، أو حسابان مع تفسيرين"},{"level":"2 درجتان","description":"حساب واحد صحيح مع تفسير واحد"},{"level":"1 درجة","description":"حساب واحد أو تفسير واحد فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الاعتقاد أن كتلة الغاز تتغير بتغير درجة الحرارة","الظن أن الكثافة تزداد بالتسخين لأن الجسيمات أسرع","نسيان الضغط في البسط عند الحالة (ج)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-11T13:13:23.523Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2511, 2, 'من خصائص الغاز المثالي أن أحجام جسيماته تكاد تكون معدومة، لأن المسافات بينها كبيرة جدًّا مقارنة بأحجامها.', '["حجم الوعاء هو حجم الغاز (الفراغ الذي يشغله)، وليس حجم الجسيمات نفسها.","لا يشغل حجم الجسيمات في الغاز المثالي جزءًا يُذكر من حجم الوعاء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.528Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2512, 1, 'يُفترض أن جسيمات الغاز المثالي لا تتجاذب ولا تتنافر، فلا تؤثر إحداها في الأخرى إلا لحظة التصادم.', '["التجاذب القوي صفة السوائل والمواد الصلبة، ويُهمل تمامًا في الغاز المثالي.","","لا يُفترض وجود تنافر بين جسيمات الغاز المثالي أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-11T13:13:23.528Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2513, 0, 'تصادمات جسيمات الغاز المثالي مرنة؛ أي تنتقل الطاقة الحركية بين الجسيمات دون أن يتغير مجموعها.', '["","لو فُقدت الطاقة الحركية في كل تصادم لتباطأت الجسيمات تدريجيًّا وانخفض الضغط ذاتيًّا، وهذا لا يحدث.","التصاق الجسيمات يتطلب قوى تجاذب، وهي معدومة في الغاز المثالي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:23.528Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2514, 2, 'تتحرك جسيمات الغاز المثالي حركة عشوائية سريعة في خطوط مستقيمة وفي جميع الاتجاهات حتى تصطدم بجسيم آخر أو بجدار الوعاء.', '["الحركة الاهتزازية حول مواضع ثابتة صفة جسيمات المادة الصلبة.","حركة الغاز في جميع الاتجاهات لا في اتجاه واحد، وهي سريعة لا بطيئة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T13:13:23.528Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2515, 1, 'متوسط الطاقة الحركية لجسيمات الغاز يتناسب طرديًا مع درجة الحرارة المطلقة (بالكلفن)، وجميع الغازات عند درجة الحرارة نفسها لها متوسط الطاقة الحركية نفسه.', '["تغيير حجم الوعاء عند ثبات درجة الحرارة لا يغيّر متوسط الطاقة الحركية.","","الغازات المختلفة عند درجة الحرارة نفسها لها متوسط الطاقة الحركية نفسه، وإن اختلفت سرعاتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.529Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2516, 2, 'الغاز المثالي تنطبق عليه العلاقة PV = nRT تمامًا، أي أن PV/nRT = 1، وهذا يتحقق في الحالة (ج).', '["القيمة 0.82 أقل من 1، فالغاز يحيد عن السلوك المثالي.","القيمة 1.25 أكبر من 1، فالغاز يحيد عن السلوك المثالي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.529Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2517, 1, 'من فروض الغاز المثالي انعدام التجاذب والتنافر بين جسيماته في جميع الظروف، فالتجاذب عند التقارب صفة الغاز الحقيقي.', '["الحركة العشوائية من خصائص الغاز المثالي.","","التصادمات المرنة من خصائص الغاز المثالي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-11T13:13:23.529Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2518, null, null, null, '1) أحجام جسيماته تكاد تكون معدومة مقارنة بالمسافات بينها. 2) لا توجد بين جسيماته قوى تجاذب أو تنافر. 3) تتحرك جسيماته حركة عشوائية سريعة في خطوط مستقيمة وفي جميع الاتجاهات. 4) تصادمات جسيماته مرنة. (ويقبل أيضًا: متوسط الطاقة الحركية لجسيماته يعتمد على درجة الحرارة، ويخضع لقوانين الغازات في جميع الظروف أي PV/nRT = 1.)', '["حجم جسيمات مهمل","انعدام التجاذب والتنافر","حركة عشوائية سريعة مستقيمة","تصادمات مرنة","(بديل) الطاقة الحركية تعتمد على درجة الحرارة / يخضع لقوانين الغازات"]'::jsonb, '[]'::jsonb, '[{"element":"الخاصية الأولى","marks":1},{"element":"الخاصية الثانية","marks":1},{"element":"الخاصية الثالثة","marks":1},{"element":"الخاصية الرابعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أربع خصائص صحيحة"},{"level":"3 درجات","description":"ثلاث خصائص صحيحة"},{"level":"2 درجتان","description":"خاصيتان صحيحتان"},{"level":"1 درجة","description":"خاصية واحدة صحيحة"},{"level":"صفر","description":"لا خصائص صحيحة"}]'::jsonb, '["القول إن جسيماته متقاربة","ذكر أن تصادماته تفقد طاقة","ذكر خصائص الغاز الحقيقي (حجم الجسيمات والتجاذب)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:23.529Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2519, null, null, null, 'يفترض نموذج الغاز المثالي أن جسيماته بلا حجم وأنه لا توجد بينها قوى تجاذب أو تنافر. لكن جسيمات أي غاز فعلي (ذرات أو جزيئات) لها حجم محدد مهما صغر، وتوجد بينها قوى تجاذب ولو ضعيفة. لذلك لا يحقق أي غاز هذين الفرضين تمامًا، وإنما يقترب بعضها (مثل H2 وHe) من السلوك المثالي في ظروف معينة.', '["ذكر أن الغاز المثالي يُفترض أن جسيماته بلا حجم","بيان أن جسيمات الغازات الفعلية لها حجم","ذكر أن الغاز المثالي لا تجاذب بين جسيماته","بيان أن الغازات الفعلية بينها قوى تجاذب"]'::jsonb, '[]'::jsonb, '[{"element":"فرض الحجم ومخالفته في الواقع","marks":2},{"element":"فرض انعدام التجاذب ومخالفته في الواقع","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير الخاصيتين مع بيان مخالفة الواقع لكل منهما"},{"level":"3 درجات","description":"خاصيتان مع قصور في بيان مخالفة إحداهما"},{"level":"2 درجتان","description":"خاصية واحدة مفسرة كاملة"},{"level":"1 درجة","description":"ذكر خاصية دون تفسير"},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة"}]'::jsonb, '["الاكتفاء بذكر الخصائص دون ربطها بالغازات الفعلية","القول إن H2 وHe غازات مثالية تمامًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-11T13:13:23.529Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2520, null, null, null, '(أ) لأن جسيمات الغاز تتحرك حركة عشوائية سريعة في جميع الاتجاهات، ولا توجد بينها قوى تجاذب تبقيها متجمعة، فتنتشر حتى تملأ الوعاء كله. (ب) لأن تصادمات الجسيمات مرنة فلا تُفقد طاقتها الحركية، ومتوسط طاقتها الحركية يعتمد على درجة الحرارة فقط؛ فما دامت درجة الحرارة ثابتة تبقى سرعة الجسيمات وعدد تصادماتها مع الجدران ثابتين فيبقى الضغط ثابتًا.', '["(أ) الحركة العشوائية السريعة في جميع الاتجاهات","(أ) انعدام قوى التجاذب","(ب) التصادمات المرنة لا تُفقد فيها طاقة","(ب) ثبات متوسط الطاقة الحركية بثبات درجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير (أ)","marks":2},{"element":"تفسير (ب)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسيران صحيحان مكتملان"},{"level":"3 درجات","description":"تفسير كامل وآخر ناقص"},{"level":"2 درجتان","description":"تفسير واحد كامل"},{"level":"1 درجة","description":"ذكر خاصية صحيحة دون ربط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تفسير (ب) بأن الجسيمات تتوقف عن الحركة","إغفال دور درجة الحرارة في ثبات الطاقة الحركية","تفسير (أ) بتمدد الجسيمات نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.530Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2521, 0, 'يُفترض أن جسيمات الغاز المثالي حجمها مهمل، أما جسيمات الغاز الحقيقي فلها حجم محدد يصبح مؤثرًا عند الضغط المرتفع.', '["","هذا عكس الصواب؛ فالحجم المهمل فرض من فروض الغاز المثالي.","حجم الجسيمات أحد أسباب حيود الغاز الحقيقي، فهو وجه اختلاف أساسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:23.534Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2522, 2, 'عند الضغط المنخفض تتباعد الجسيمات فيصبح حجمها مهملًا، وعند درجة الحرارة المرتفعة تكون طاقتها الحركية كبيرة فتتغلب على قوى التجاذب؛ فيقترب السلوك من المثالي.', '["هذه ظروف أكبر حيود عن السلوك المثالي.","الضغط المرتفع يقرّب الجسيمات فيزيد أثر حجمها وتجاذبها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:23.534Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2523, 1, 'خفض درجة الحرارة يقلل الطاقة الحركية للجسيمات، فتصبح قوى التجاذب بينها أكثر تأثيرًا نسبيًّا، فيبتعد سلوك الغاز عن المثالي.', '["حجم الجسيم نفسه لا يتغير بالتبريد.","","عدد المولات لا يتغير بتغيير درجة الحرارة في وعاء مغلق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-11T13:13:23.534Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2524, 0, 'الحالة (أ) تجمع بين أقل ضغط (0.5 atm) وأعلى درجة حرارة (500 K)، وهما الظرفان اللذان يقترب فيهما الغاز الحقيقي من السلوك المثالي.', '["","الضغط المرتفع (50 atm) ودرجة الحرارة المنخفضة (200 K) يزيدان الحيود عن السلوك المثالي.","الضغط أعلى ودرجة الحرارة أقل مقارنة بالحالة (أ)، فالحيود أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.535Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2525, 0, 'من فروض الغاز المثالي انعدام التجاذب بين جسيماته، أما جسيمات الغاز الحقيقي فبينها قوى تجاذب تزداد أهميتها بتقارب الجسيمات.', '["","هذا عكس الصواب.","الغاز المثالي يُفترض فيه انعدام التجاذب، فلا يتساوى مع الحقيقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:23.535Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2526, 1, 'الغاز المثالي يخضع لقوانين الغازات في جميع الظروف (PV/nRT = 1 دائمًا)، أما الغاز الحقيقي فيخضع لها تقريبيًّا عند الضغط المنخفض ودرجة الحرارة المرتفعة ويحيد عنها في غير ذلك.', '["الغاز الحقيقي يحيد عن القوانين عند الضغط المرتفع ودرجة الحرارة المنخفضة.","","هذا عكس الصواب؛ فالغاز المثالي هو الذي يخضع لها دائمًا بحكم تعريفه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-11T13:13:23.536Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2527, 2, 'زيادة الضغط تقرب الجسيمات بعضها من بعض، فيصبح حجمها جزءًا ملحوظًا من حجم الغاز، وتزداد قوى التجاذب بينها؛ فلا ينطبق فرضا الغاز المثالي.', '["الطاقة الحركية تعتمد على درجة الحرارة لا على الضغط.","زيادة الضغط لا تغير عدد الجسيمات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:23.536Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2528, null, null, null, '(أ) المثالي: حجم جسيماته مهمل. الحقيقي: لجسيماته حجم محدد. (ب) المثالي: لا تجاذب ولا تنافر. الحقيقي: توجد قوى تجاذب. (ج) المثالي: يخضع لها في جميع الظروف. الحقيقي: يخضع لها تقريبيًّا عند الضغط المنخفض ودرجة الحرارة المرتفعة ويحيد عنها عند الضغط المرتفع ودرجة الحرارة المنخفضة. (د) المثالي: PV/nRT = 1 دائمًا. الحقيقي: قد تختلف عن 1 (أكبر أو أصغر).', '["المقارنة في حجم الجسيمات","المقارنة في قوى التجاذب","المقارنة في الخضوع لقوانين الغازات","المقارنة في قيمة PV/nRT"]'::jsonb, '[]'::jsonb, '[{"element":"حجم الجسيمات","marks":1},{"element":"قوى التجاذب","marks":1},{"element":"الخضوع للقوانين","marks":1},{"element":"قيمة PV/nRT","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المقارنات الأربع صحيحة"},{"level":"3 درجات","description":"ثلاث مقارنات صحيحة"},{"level":"2 درجتان","description":"مقارنتان صحيحتان"},{"level":"1 درجة","description":"مقارنة واحدة صحيحة"},{"level":"صفر","description":"لا مقارنة صحيحة"}]'::jsonb, '["ذكر صفة أحد الغازين دون مقابلها في الآخر","القول إن الغاز الحقيقي لا يخضع لقوانين الغازات مطلقًا","الخلط بين حجم الجسيمات وحجم الغاز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:23.536Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2529, null, null, null, 'عند الضغط المرتفع تتقارب جزيئات N2 فيصبح حجمها جزءًا ملحوظًا من حجم الغاز ولا يمكن إهماله، وتزداد قوى التجاذب بينها لتقاربها. وعند درجة الحرارة المنخفضة تقل الطاقة الحركية للجزيئات فتعجز عن التغلب على قوى التجاذب. لذلك لا يتحقق فرضا الغاز المثالي (الحجم المهمل وانعدام التجاذب) فيحيد الغاز.', '["الضغط المرتفع يقرّب الجزيئات","حجم الجزيئات يصبح غير مهمل","زيادة أثر قوى التجاذب","انخفاض درجة الحرارة يقلل الطاقة الحركية"]'::jsonb, '[]'::jsonb, '[{"element":"أثر الضغط المرتفع","marks":2},{"element":"أثر درجة الحرارة المنخفضة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل لأثر الضغط ودرجة الحرارة"},{"level":"3 درجات","description":"تعليل كامل لعامل وناقص للآخر"},{"level":"2 درجتان","description":"تعليل عامل واحد فقط"},{"level":"1 درجة","description":"إشارة عامة إلى التجاذب دون ربط بالظروف"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الضغط يزيد حجم الجزيئات نفسها","القول إن التبريد يزيد الطاقة الحركية","إغفال فرضي الغاز المثالي في التعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.537Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2530, null, null, null, 'العينة (س) أقرب إلى 1، لأن ضغطها منخفض فتتباعد جزيئاتها ويُهمل حجمها، ودرجة حرارتها مرتفعة فتكون طاقتها الحركية كبيرة وتتغلب على قوى التجاذب؛ فيقترب سلوكها من المثالي. أما (ص) فضغطها مرتفع ودرجة حرارتها منخفضة فتتقارب جزيئاتها ويزداد أثر حجمها وتجاذبها. والقيمة البعيدة عن 1 تدل على أن الغاز يحيد عن سلوك الغاز المثالي (يسلك سلوك الغاز الحقيقي).', '["اختيار العينة (س)","تفسير أثر الضغط المنخفض","تفسير أثر درجة الحرارة المرتفعة","بيان دلالة القيمة البعيدة عن 1"]'::jsonb, '[]'::jsonb, '[{"element":"الاختيار الصحيح","marks":1},{"element":"تفسير أثر الضغط","marks":1},{"element":"تفسير أثر درجة الحرارة","marks":1},{"element":"دلالة القيمة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اختيار صحيح وتفسير كامل وبيان الدلالة"},{"level":"3 درجات","description":"اختيار صحيح مع تفسير ناقص لأحد العاملين"},{"level":"2 درجتان","description":"اختيار صحيح مع تفسير عامل واحد فقط"},{"level":"1 درجة","description":"اختيار صحيح دون تفسير"},{"level":"صفر","description":"اختيار خاطئ"}]'::jsonb, '["اختيار (ص) لأن ضغطها أكبر","الظن أن القيمة البعيدة عن 1 تعني خطأ في القياس","تفسير الاختيار بعدد المولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-11T13:13:23.537Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2531, 1, 'الغاز الحقيقي هو الغاز الذي يحيد عن سلوك الغاز المثالي باختلاف درجة الحرارة والضغط؛ فيحيد عند الضغط المرتفع ودرجة الحرارة المنخفضة، ويقترب من المثالي عند الضغط المنخفض ودرجة الحرارة المرتفعة.', '["هذا تعريف الغاز المثالي.","","هذه فروض الغاز المثالي، أما جسيمات الغاز الحقيقي فلها حجم وتتجاذب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:23.541Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2532, 0, 'لا يوجد في الحقيقة غاز مثالي؛ فكل غاز فعلي جسيماته لها حجم وبينها قوى تجاذب ولو ضعيفة، فجميع الغازات حقيقية وإن اقترب بعضها من السلوك المثالي.', '["","H2 وHe يقتربان من السلوك المثالي في ظروف كثيرة، لكنهما غازان حقيقيان.","الغازات غير القطبية أيضًا غازات حقيقية، وإن كان حيودها أقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-11T13:13:23.541Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2533, 2, 'يحيد الغاز الحقيقي لأن لجسيماته حجمًا لا يمكن إهماله دائمًا، ولأن بينها قوى تجاذب، وكلاهما يخالف فرضي الغاز المثالي.', '["قانون الغاز المثالي يأخذ عدد المولات في الحسبان، فهو ليس سببًا للحيود.","السرعة العالية (درجة الحرارة المرتفعة) تقرّب السلوك من المثالي لا تبعده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.541Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2534, 1, 'الغاز الحقيقي يحيد عن سلوك الغاز المثالي باختلاف درجة الحرارة والضغط: يزداد حيوده بزيادة الضغط ونقصان درجة الحرارة.', '["الكتلة وعدد المولات ليسا العاملين المذكورين في تعريف الغاز الحقيقي.","","شكل الوعاء لا يؤثر في سلوك الغاز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.542Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2535, 2, 'هذه صفات الغاز الحقيقي: لجسيماته حجم وبينها تجاذب، ويحيد عن السلوك المثالي عند الضغط المرتفع ودرجة الحرارة المنخفضة.', '["جسيمات الغاز المثالي عديمة الحجم ولا تتجاذب ويخضع للقوانين دائمًا.","الغازات النبيلة اسم لمجموعة عناصر في الجدول الدوري، وهي أيضًا غازات حقيقية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:23.542Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2536, 0, 'للغاز المثالي PV/nRT = 1 دائمًا، وأي قيمة مختلفة عن 1 تدل على حيود الغاز عن السلوك المثالي، أي أنه يسلك سلوك الغاز الحقيقي.', '["","السلوك المثالي يتطلب أن تكون النسبة 1 تمامًا.","النسبة تساوي 1 للغاز المثالي فقط، أما الغازات الحقيقية فقد تختلف قيمتها عن 1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:23.542Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2537, 0, 'الإسالة تتطلب أن تتماسك الجسيمات بقوى تجاذب عندما تقل طاقتها الحركية، وهذه القوى موجودة في الغاز الحقيقي ومعدومة في الغاز المثالي.', '["","جسيمات الغاز الحقيقي لها حجم، والحجم المعدوم فرض للغاز المثالي.","التصادمات المرنة فرض للغاز المثالي ولا تفسر التماسك والإسالة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.542Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2538, null, null, null, 'الغاز الحقيقي: غاز لجسيماته حجم وبينها قوى تجاذب، فلا ينطبق عليه سلوك الغاز المثالي تمامًا ويحيد عنه باختلاف درجة الحرارة والضغط. يزداد حيوده عند الضغط المرتفع ودرجة الحرارة المنخفضة، ويقترب من سلوك الغاز المثالي عند الضغط المنخفض ودرجة الحرارة المرتفعة.', '["تعريف صحيح للغاز الحقيقي","ظروف زيادة الحيود: ضغط مرتفع","ظروف زيادة الحيود: درجة حرارة منخفضة","ظروف الاقتراب: ضغط منخفض ودرجة حرارة مرتفعة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"ظروف زيادة الحيود","marks":1},{"element":"ظروف الاقتراب من المثالي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح والظروف كاملة"},{"level":"3 درجات","description":"تعريف صحيح مع خطأ في أحد الظروف"},{"level":"2 درجتان","description":"تعريف صحيح فقط أو الظروف فقط"},{"level":"1 درجة","description":"تعريف ناقص"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["عكس الظروف (ضغط منخفض يزيد الحيود)","تعريف الغاز الحقيقي بأنه الغاز الموجود في الطبيعة فقط دون ذكر الحيود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:23.543Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2539, null, null, null, '(1) غاز حقيقي. (2) غاز مثالي. (3) غاز حقيقي. (4) غاز مثالي.', '["(1) حقيقي","(2) مثالي","(3) حقيقي","(4) مثالي"]'::jsonb, '[]'::jsonb, '[{"element":"العبارة 1","marks":1},{"element":"العبارة 2","marks":1},{"element":"العبارة 3","marks":1},{"element":"العبارة 4","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التصنيفات الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة تصنيفات صحيحة"},{"level":"2 درجتان","description":"تصنيفان صحيحان"},{"level":"1 درجة","description":"تصنيف واحد صحيح"},{"level":"صفر","description":"لا تصنيف صحيح"}]'::jsonb, '["عدّ PV/nRT = 1 صفة للغاز الحقيقي","عدّ انعدام التجاذب صفة للغاز الحقيقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:23.543Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2540, null, null, null, 'لأن الغازات الحقيقية تسلك سلوكًا قريبًا جدًّا من سلوك الغاز المثالي في الظروف المعتادة (ضغط منخفض نسبيًّا ودرجة حرارة غير منخفضة)، حيث تكون جسيماتها متباعدة فيُهمل حجمها، وطاقتها الحركية كافية لتغلب على التجاذب؛ فتكون نتائج القانون قريبة من القيم الفعلية. ويجب الحذر عند الضغط المرتفع ودرجة الحرارة المنخفضة، وكذلك مع الغازات القطبية أو ذات الجزيئات الكبيرة، لأن الحيود يصبح كبيرًا.', '["الغازات الحقيقية تقترب من السلوك المثالي في الظروف المعتادة","التفسير: تباعد الجسيمات وتغلب الطاقة الحركية على التجاذب","الحذر عند الضغط المرتفع ودرجة الحرارة المنخفضة","(إضافي) الغازات القطبية وذات الجزيئات الكبيرة"]'::jsonb, '[]'::jsonb, '[{"element":"سبب استخدام القانون","marks":2},{"element":"ظروف الحذر","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل وظروف الحذر صحيحة"},{"level":"3 درجات","description":"تفسير صحيح مع ظروف ناقصة"},{"level":"2 درجتان","description":"أحد الجزأين صحيح فقط"},{"level":"1 درجة","description":"إجابة عامة دون تفسير"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن القانون يعطي نتائج خاطئة دائمًا للغازات الحقيقية","عكس ظروف الحذر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.544Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2541, 2, 'جزيئات الغاز القطبي لها أطراف ذات شحنات جزئية متعاكسة، فتتجاذب جزيئاته بقوى أقوى، وهذا يخالف فرض انعدام التجاذب في الغاز المثالي.', '["صغر حجم الجزيئات يقرّب السلوك من المثالي لا يبعده.","التصادمات المرنة من فروض الغاز المثالي، فلا تفسر الحيود.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-10-11T13:13:23.547Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2542, 0, 'NH3 جزيء قطبي تتجاذب جزيئاته بقوى أكبر، أما H2 فغير قطبي وقوى التجاذب بين جزيئاته ضعيفة جدًّا؛ لذا يحيد NH3 أكثر، ويقترب H2 من السلوك المثالي.', '["","خفة جزيئات H2 وعدم قطبيتها يجعلانه أقرب إلى السلوك المثالي.","قوى التجاذب بين جزيئات NH3 أكبر بكثير، فلا يتساوى الحيود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:23.548Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2543, 1, 'بخار الماء H2O مكون من جزيئات قطبية تتجاذب بقوة، فيحيد أكثر رغم أن كتلته المولية (18.0 g/mol) أقل من N2 وقريبة من CH4؛ أما CH4 وN2 فغير قطبيين.', '["CH4 غير قطبي وكتلته المولية قريبة من H2O، فالتجاذب بين جزيئاته أضعف.","","N2 أثقل لكنه غير قطبي، فالتجاذب بين جزيئاته ضعيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:23.548Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2544, 1, 'الغازات القطبية تتجاذب جزيئاتها بقوى ملحوظة، فيسقط فرض انعدام التجاذب والتنافر بين جسيمات الغاز المثالي.', '["جزيئات الغاز القطبي تتحرك حركة عشوائية أيضًا.","","متوسط الطاقة الحركية لجزيئات أي غاز يعتمد على درجة الحرارة، قطبيًّا كان أم لا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-11T13:13:23.548Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2545, 0, 'جزيء NH3 قطبي؛ لأن النيتروجين أعلى سالبية كهربائية من الهيدروجين والشكل هرمي، فيتكون طرف سالب جزئيًّا وأطراف موجبة جزئيًّا، فتتجاذب الأطراف المتعاكسة في الجزيئات المتجاورة.', '["","الحركة في خطوط مستقيمة صفة لجميع جزيئات الغازات، ولا تفسر التجاذب.","مرونة التصادمات فرض للغاز المثالي ولا علاقة لها بالتجاذب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-11T13:13:23.549Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2546, 2, 'تقارب الكتلتين الموليتين يجعل القطبية هي الفارق: جزيء F2 غير قطبي فقوى التجاذب بين جزيئاته أضعف، بينما HCl قطبي فيحيد أكثر.', '["الفرق في الكتلة المولية صغير جدًّا، والعامل الحاسم هنا هو القطبية.","القطبية تزيد التجاذب فتبعد الغاز عن السلوك المثالي لا تقربه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-11T13:13:23.549Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2547, 1, 'رفع درجة الحرارة يزيد الطاقة الحركية فتتغلب الجزيئات على قوى التجاذب القطبية، وخفض الضغط يباعد الجزيئات فيضعف أثر التجاذب.', '["هذه الظروف تزيد أثر التجاذب فتزيد الحيود.","","زيادة الضغط تقرّب الجزيئات فيزداد أثر التجاذب القطبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-11T13:13:23.549Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2548, null, null, null, 'لأن جزيئات الغاز القطبي لها أطراف ذات شحنات جزئية موجبة وسالبة، فتتجاذب الأطراف المتعاكسة في الجزيئات المتجاورة بقوى تجاذب قوية نسبيًّا. وهذا يخالف فرض الغاز المثالي القائل بانعدام قوى التجاذب والتنافر بين الجسيمات، فيحيد الغاز القطبي عن السلوك المثالي.', '["جزيئات الغاز القطبي لها أطراف ذات شحنات جزئية","وجود قوى تجاذب قوية بين الجزيئات","مخالفة فرض انعدام التجاذب في الغاز المثالي"]'::jsonb, '[]'::jsonb, '[{"element":"سبب القطبية (الشحنات الجزئية)","marks":1},{"element":"قوى التجاذب","marks":1},{"element":"الربط بفرض الغاز المثالي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعليل كامل بعناصره الثلاثة"},{"level":"2 درجتان","description":"ذكر التجاذب وربطه بالفرض دون تفسير القطبية"},{"level":"1 درجة","description":"ذكر وجود تجاذب فقط"},{"level":"صفر","description":"لا إجابة أو تعليل خاطئ"}]'::jsonb, '["تعليل الحيود بكبر حجم الجزيئات القطبية","القول إن الجزيئات القطبية تتنافر فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-10-11T13:13:23.549Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2549, null, null, null, 'H2 أقرب إلى سلوك الغاز المثالي، وNH3 يحيد أكثر. التفسير: جزيء H2 غير قطبي (ذرتان متماثلتان) وصغير، فقوى التجاذب بين جزيئاته ضعيفة جدًّا. أما جزيء NH3 فقطبي؛ لأن النيتروجين أعلى سالبية كهربائية من الهيدروجين وشكل الجزيء هرمي ثلاثي، فتتكون عليه شحنات جزئية تجعل جزيئاته تتجاذب بقوة، وهذا يخالف فرض انعدام التجاذب.', '["الحكم: H2 أقرب إلى المثالي","تفسير عدم قطبية H2 وضعف تجاذبه","تفسير قطبية NH3 (فرق السالبية والشكل الهرمي)","ربط تجاذب NH3 بالحيود"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"تفسير H2","marks":1},{"element":"تفسير قطبية NH3","marks":1},{"element":"الربط بالحيود","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح وتفسير كامل للغازين"},{"level":"3 درجات","description":"حكم صحيح مع قصور في تفسير أحد الغازين"},{"level":"2 درجتان","description":"حكم صحيح مع تفسير غاز واحد"},{"level":"1 درجة","description":"حكم صحيح دون تفسير"},{"level":"صفر","description":"حكم خاطئ"}]'::jsonb, '["الحكم بأن NH3 أقرب لأنه أثقل","إغفال سبب قطبية NH3","القول إن H2 غاز مثالي تمامًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-11T13:13:23.549Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2550, null, null, null, 'عند درجة الحرارة المرتفعة تكون الطاقة الحركية لجزيئات NH3 كبيرة، فتتحرك بسرعة تمكنها من التغلب على قوى التجاذب القطبية، فيقل أثر هذه القوى. وعند الضغط المنخفض تتباعد الجزيئات كثيرًا، وقوى التجاذب تضعف بزيادة المسافة، كما يصبح حجم الجزيئات مهملًا مقارنة بالمسافات بينها. لذلك يقترب سلوكه من المثالي رغم قطبيته.', '["زيادة الطاقة الحركية عند درجة الحرارة المرتفعة","التغلب على قوى التجاذب","تباعد الجزيئات عند الضغط المنخفض وضعف التجاذب","إهمال حجم الجزيئات"]'::jsonb, '[]'::jsonb, '[{"element":"أثر درجة الحرارة المرتفعة","marks":2},{"element":"أثر الضغط المنخفض","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل لأثر العاملين"},{"level":"3 درجات","description":"تفسير كامل لعامل وناقص للآخر"},{"level":"2 درجتان","description":"تفسير عامل واحد"},{"level":"1 درجة","description":"إشارة عامة دون تفسير"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن الجزيئات تفقد قطبيتها عند التسخين","القول إن الضغط المنخفض يصغّر حجم الجزيئات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-11T13:13:23.550Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2551, 0, 'جزيئات البيوتان كبيرة نسبيًّا، فيشغل حجمها جزءًا ملحوظًا من حجم الغاز ولا يمكن إهماله، فيسقط فرض الحجم المهمل لجسيمات الغاز المثالي.', '["","جزيئات البيوتان تتحرك حركة عشوائية كغيرها من الغازات.","مرونة التصادمات ليست سبب حيود الغازات ذات الجزيئات الكبيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.554Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2552, 1, 'ذرات He صغيرة جدًّا فيكون حجمها مهملًا، والتجاذب بينها ضعيف جدًّا؛ أما جزيئات C4H10 فكبيرة الحجم ويزداد التجاذب بينها بكبرها، فتحيد أكثر.', '["كبر الجزيء يزيد حجمه والتجاذب بين جزيئاته فيبعده عن السلوك المثالي.","","عدم القطبية لا يكفي؛ فحجم الجزيء عامل مستقل يؤثر في الحيود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-10-11T13:13:23.554Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2553, 2, 'الغازات الثلاثة غير قطبية، فالفارق هو حجم الجسيمات: جزيء C4H10 أكبرها حجمًا، فيكون حجمه أقل قابلية للإهمال والتجاذب بين جزيئاته أكبر، فيحيد أكثر.', '["ذرات He أصغر الجسيمات حجمًا، فهو الأقرب إلى السلوك المثالي.","جزيء CH4 أصغر من C4H10 بكثير، فحيوده أقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-11T13:13:23.555Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2554, 0, 'عند الضغط المرتفع يقل الحيز الفارغ بين الجزيئات، فيصبح حجم الجزيئات نفسها نسبة ملحوظة من حجم الغاز، ويظهر أثره أكثر في الجزيئات الكبيرة.', '["","حجم الجزيء ثابت ولا يكبر بزيادة الضغط.","الجزيئات الأثقل تتحرك أبطأ عند درجة الحرارة نفسها، والسرعة ليست سبب الحيود هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.556Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2555, 2, 'الغازات الثلاثة غير قطبية، ويزداد الحيود بزيادة حجم الجسيم: ذرة He الأصغر ثم جزيء CH4 ثم جزيء البروبان C3H8 الأكبر.', '["هذا الترتيب معكوس؛ فالبروبان أكثرها حيودًا لا أقلها.","ذرة He أصغر من جزيء CH4، فحيود He أقل من حيود CH4.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:23.557Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2556, 1, 'المقصود بالغازات «كبيرة الحجم» الغازات ذات الجسيمات الكبيرة. عند الضغط ودرجة الحرارة نفسيهما تكون المسافات بين الجسيمات متماثلة في العينتين، فحيودهما متساوٍ مهما اختلف حجم العينة.', '["حجم العينة لا يغير المسافات بين الجسيمات عند ثبات الضغط ودرجة الحرارة.","","زيادة عدد الجسيمات مع زيادة الحجم بالنسبة نفسها لا تغير تقاربها، فلا يتغير الحيود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-11T13:13:23.557Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2557, 0, 'جزيئات البيوتان تشغل بنفسها جزءًا من حجم الوعاء، فيكون الحيز الفارغ المتاح لحركتها أقل من حجم الوعاء؛ وهذا أحد أسباب حيوده عن السلوك المثالي.', '["","التساوي يفترض أن حجم الجزيئات مهمل، وهذا فرض الغاز المثالي.","لا يمكن أن يتجاوز الحيز المتاح حجم الوعاء نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-11T13:13:23.558Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2558, null, null, null, 'لأن جزيئات البيوتان كبيرة الحجم (14 ذرة في الجزيء) فيشغل حجمها جزءًا ملحوظًا من حجم الغاز ولا يمكن إهماله، كما أن قوى التجاذب بين الجزيئات الكبيرة أكبر. أما ذرات الهيليوم فصغيرة جدًّا وحجمها مهمل والتجاذب بينها ضعيف جدًّا، فيقترب سلوكه من المثالي.', '["كبر حجم جزيئات البيوتان وعدم إمكان إهماله","زيادة التجاذب بين الجزيئات الكبيرة","صغر ذرات الهيليوم وإهمال حجمها"]'::jsonb, '[]'::jsonb, '[{"element":"أثر حجم جزيئات البيوتان","marks":2},{"element":"زيادة التجاذب","marks":1},{"element":"المقارنة بالهيليوم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل بعناصره"},{"level":"3 درجات","description":"تعليل الحجم والمقارنة دون ذكر التجاذب"},{"level":"2 درجتان","description":"تعليل الحجم فقط"},{"level":"1 درجة","description":"إشارة عامة إلى الحيود"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["تعليل الحيود بقطبية البيوتان (وهو غير قطبي)","الخلط بين حجم الجزيء وحجم عينة الغاز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-10-11T13:13:23.558Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2559, null, null, null, 'الترتيب: He ثم CH4 ثم C3H8. التفسير: الغازات الثلاثة غير قطبية، فالعامل المؤثر هو حجم الجسيمات؛ ذرة He أصغرها حجمًا فيُهمل حجمها والتجاذب بين ذراته ضعيف جدًّا، ثم جزيء CH4 الأكبر قليلًا، ثم جزيء C3H8 الأكبر حجمًا الذي يشغل حيزًا أكبر وتتجاذب جزيئاته بقوى أكبر، فهو الأبعد عن السلوك المثالي.', '["الترتيب الصحيح He ثم CH4 ثم C3H8","بيان أن الغازات الثلاثة غير قطبية","ربط الحيود بازدياد حجم الجسيم","ربط حجم الجسيم بزيادة التجاذب أو عدم إهمال الحجم"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":1},{"element":"استبعاد عامل القطبية","marks":1},{"element":"ربط الحيود بحجم الجسيم","marks":1},{"element":"التفسير على مستوى الجسيمات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتفسير كامل"},{"level":"3 درجات","description":"ترتيب صحيح وتفسير ينقصه عنصر"},{"level":"2 درجتان","description":"ترتيب صحيح مع تفسير مختصر"},{"level":"1 درجة","description":"ترتيب صحيح فقط"},{"level":"صفر","description":"ترتيب خاطئ"}]'::jsonb, '["الترتيب العكسي","كتابة صيغة البروبان C3H6 بدل C3H8","تفسير الترتيب بالقطبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-11T13:13:23.558Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2560, null, null, null, 'عند الضغط المنخفض جدًّا تتباعد جزيئات البيوتان كثيرًا، فتصبح المسافات بينها كبيرة جدًّا مقارنة بحجم الجزيئات نفسها، فيُهمل حجمها كما في الغاز المثالي. كما أن تباعد الجزيئات يُضعف قوى التجاذب بينها. لذلك يقترب سلوكه من المثالي.', '["تباعد الجزيئات عند الضغط المنخفض","صغر حجم الجزيئات نسبيًّا مقارنة بالمسافات بينها فيُهمل","ضعف قوى التجاذب بتباعد الجزيئات"]'::jsonb, '[]'::jsonb, '[{"element":"تباعد الجزيئات","marks":1},{"element":"إهمال الحجم النسبي","marks":1},{"element":"ضعف التجاذب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل بعناصره الثلاثة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["القول إن حجم الجزيء نفسه يصغر عند خفض الضغط","إغفال المقارنة بين حجم الجزيئات والمسافات بينها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-11T13:13:23.558Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2561, 1, 'ينص مبدأ أفوجادرو على أن الحجوم المتساوية من الغازات المختلفة عند الضغط ودرجة الحرارة نفسيهما تحتوي على العدد نفسه من الجسيمات (المولات)، ولذلك تمثل معاملات الغازات في المعادلة الموزونة نسب حجومها.', '["الغازات المختلفة لها كتل مولية مختلفة، فالحجوم المتساوية منها تختلف كتلها.","","المبدأ يتعلق بعدد الجسيمات لا بحجم الجسيم الواحد، ويشترط تساوي الضغط ودرجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:23.562Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2562, 2, 'نسبة الحجوم C3H8 : O2 = 1 : 5، إذن V(O2) = 4.0 L × 5 = 20 L.', '["افتراض أن النسبة 1 : 1 وإهمال معامل الأكسجين.","قسمة الحجم على 5 بدل الضرب (عكس النسبة).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-10-11T13:13:23.563Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
