(2565, 1, 'تمثل المعاملات نسب المولات، وبحسب مبدأ أفوجادرو تمثل أيضًا نسب الحجوم عند الضغط ودرجة الحرارة نفسيهما.', '["الكتل لا تتناسب مع المعاملات لاختلاف الكتل المولية.","","الكثافة تعتمد على الكتلة المولية لا على المعاملات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-11T13:13:23.564Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2566, 0, 'نسبة الحجوم C2H6 : O2 = 2 : 7، إذن V(O2) = 10.0 L × (7 ÷ 2) = 35.0 L.', '["","ضرب الحجم في 7 مع إهمال معامل الإيثان (2).","استخدام النسبة مقلوبة (2 ÷ 7)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-10-11T13:13:23.565Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2567, 2, 'النسبة الحجمية المتوقعة H2 : Cl2 : HCl = 1 : 1 : 2، وهذا يتحقق في التجربة (ب): 2.0 : 2.0 : 4.0.', '["حجم HCl الناتج يجب أن يكون ضعف حجم H2، لا مساويًا له.","حجم Cl2 فيها ضعف حجم H2، والنسبة الصحيحة 1 : 1.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-11T13:13:23.565Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2568, null, null, null, 'المعادلة: C3H8(g) + 5O2(g) → 3CO2(g) + 4H2O(g). بحسب مبدأ أفوجادرو تمثل المعاملات نسب الحجوم: V(O2) = 4.0 L × 5 = 20 L ، V(CO2) = 4.0 L × 3 = 12 L.', '["كتابة الصيغة الصحيحة للبروبان C3H8","وزن المعادلة 1 : 5 : 3 : 4","حساب حجم الأكسجين 20 L","حساب حجم CO2 الناتج 12 L"]'::jsonb, '["C3H8(g) + 5O2(g) → 3CO2(g) + 4H2O(g)","V(O2) = 4.0 × (5 ÷ 1) = 20 L","V(CO2) = 4.0 × (3 ÷ 1) = 12 L"]'::jsonb, '[{"element":"المعادلة الموزونة بالصيغة الصحيحة","marks":2},{"element":"حجم الأكسجين","marks":1},{"element":"حجم CO2","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة صحيحة وحسابان صحيحان"},{"level":"3 درجات","description":"معادلة صحيحة مع خطأ في أحد الحسابين"},{"level":"2 درجتان","description":"معادلة صحيحة فقط، أو الحسابان صحيحان بمعادلة غير موزونة"},{"level":"1 درجة","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["كتابة البروبان C3H6 (وهو البروبين) بدل C3H8","عدم وزن المعادلة","استخدام النسبة 1 : 1"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:23.566Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2569, null, null, null, 'نسبة الحجوم CH4 : O2 = 1 : 2، إذن V(O2) = 3.00 × 2 = 6.00 L. حجم الهواء = 6.00 ÷ 0.21 = 28.6 L (نحو 29 L).', '["استخدام نسبة الحجوم 1 : 2","حساب حجم الأكسجين 6.00 L","قسمة حجم الأكسجين على 0.21","حجم الهواء 28.6 L"]'::jsonb, '["V(O2) = 3.00 L × (2 ÷ 1) = 6.00 L","V(الهواء) = V(O2) ÷ 0.21","V(الهواء) = 6.00 ÷ 0.21 = 28.6 L"]'::jsonb, '[{"element":"نسبة الحجوم","marks":1},{"element":"حجم الأكسجين","marks":1},{"element":"طريقة حساب حجم الهواء","marks":1},{"element":"الناتج النهائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان كاملان"},{"level":"3 درجات","description":"حجم الأكسجين صحيح مع خطأ حسابي بسيط في حجم الهواء"},{"level":"2 درجتان","description":"حجم الأكسجين صحيح فقط"},{"level":"1 درجة","description":"نسبة الحجوم صحيحة فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ضرب حجم الأكسجين في 0.21 بدل القسمة (1.26 L)","استخدام النسبة 1 : 1 فيكون حجم الأكسجين 3.00 L"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-11T13:13:23.566Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2570, null, null, null, '(أ) V(O2) = 15 × (1 ÷ 2) = 7.5 L ، V(CO2) = 15 × (2 ÷ 2) = 15 L. (ب) رأيه خاطئ: مجموع حجوم المتفاعلات 22.5 L وحجم الناتج 15 L، لأن الحجم يتناسب مع عدد المولات (مبدأ أفوجادرو) وعدد المولات قد يتغير في التفاعل (3 مول ← 2 مول). أما الكتلة فمحفوظة لأن عدد الذرات من كل نوع ثابت على طرفي المعادلة، فالحجوم لا تُحفظ بالضرورة بخلاف الكتل.', '["حجم O2 = 7.5 L","حجم CO2 = 15 L","الحجم يتناسب مع عدد المولات لا مع الكتلة","عدد المولات يتغير (3 ← 2) بينما الذرات والكتلة محفوظة"]'::jsonb, '["V(O2) = 15 × (1 ÷ 2) = 7.5 L","V(CO2) = 15 × (2 ÷ 2) = 15 L","مجموع حجوم المتفاعلات = 22.5 L ≠ 15 L"]'::jsonb, '[{"element":"حجم O2","marks":1},{"element":"حجم CO2","marks":1},{"element":"تفسير نقص الحجم بتغير عدد المولات","marks":2},{"element":"بيان أن الكتلة محفوظة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان ومناقشة كاملة"},{"level":"4 درجات","description":"حسابان صحيحان ومناقشة ينقصها بيان حفظ الكتلة"},{"level":"3 درجات","description":"حسابان صحيحان مع مناقشة ضعيفة، أو حساب واحد مع مناقشة كاملة"},{"level":"2 درجتان","description":"حسابان صحيحان فقط"},{"level":"1 درجة","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["الظن أن الحجوم محفوظة مثل الكتل","حساب حجم O2 بضرب 15 في 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-11T13:13:23.567Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2571, 2, 'الحجم المولاري للغاز عند STP يساوي 22.4 L/mol، ويمكن التحقق منه: V = nRT ÷ P = (1 × 0.0821 × 273) ÷ 1 = 22.4 L.', '["هذه القيمة العددية لثابت الغاز R وليست حجمًا مولاريًّا.","حجم مول الغاز عند STP أكبر بكثير من لتر واحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.570Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2572, 0, 'n(CaCO3) = 25.0 ÷ 100.0 = 0.250 mol ، والنسبة 1 : 1 فإن n(CO2) = 0.250 mol ، V = 0.250 × 22.4 = 5.60 L.', '["","ضرب الكتلة في 22.4 مباشرة دون تحويلها إلى مولات.","قسمة الكتلة على 22.4 دون استخدام الكتلة المولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T13:13:23.571Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
