(2574, 1, 'n(H2) = 33.6 ÷ 22.4 = 1.50 mol ، n(NH3) = 1.50 × (2 ÷ 3) = 1.00 mol ، m = 1.00 × 17.0 = 17.0 g.', '["إهمال النسبة المولية واعتبارها 1 : 1.","","استخدام النسبة المولية مقلوبة (3 ÷ 2)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:23.572Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2575, 2, 'n(Na) = 4.60 ÷ 23.0 = 0.200 mol ، n(H2) = 0.200 × (1 ÷ 2) = 0.100 mol ، V = 0.100 × 22.4 = 2.24 L.', '["إهمال النسبة المولية Na : H2 = 2 : 1.","القسمة على 4 بدل 2 (خطأ في النسبة المولية).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-11T13:13:23.573Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2576, 0, 'نحول كتلة المعطى إلى مولات (n = m ÷ MM)، ثم نستخدم النسبة المولية من المعادلة الموزونة لإيجاد مولات المطلوب، ثم نحولها إلى حجم (V = n × 22.4 عند STP).', '["","لا يمكن تحويل كتلة المادة إلى حجم غاز آخر قبل حساب المولات، ولا تمثل المعاملات نسب كتل.","المعاملات تمثل نسب المولات لا نسب الكتل، ولا بد من المرور بالمولات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-11T13:13:23.574Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2577, 1, 'n(C3H8) = 5.60 ÷ 22.4 = 0.250 mol ، n(CO2) = 0.250 × 3 = 0.750 mol ، m = 0.750 × 44.0 = 33.0 g.', '["إهمال النسبة المولية C3H8 : CO2 = 1 : 3.","","استخدام معامل الأكسجين (5) بدل معامل CO2 (3)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-11T13:13:23.574Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2578, null, null, null, 'MM(CaCO3) = 40.0 + 12.0 + 3(16.0) = 100.0 g/mol. n(CaCO3) = 500. ÷ 100.0 = 5.00 mol. النسبة المولية CaCO3 : CO2 = 1 : 1، إذن n(CO2) = 5.00 mol. V(CO2) = 5.00 × 22.4 = 112 L.', '["حساب الكتلة المولية 100.0 g/mol","حساب مولات CaCO3 = 5.00 mol","استخدام النسبة المولية 1 : 1","الحجم 112 L"]'::jsonb, '["MM(CaCO3) = 40.0 + 12.0 + 48.0 = 100.0 g/mol","n = 500. ÷ 100.0 = 5.00 mol","n(CO2) = 5.00 mol (1 : 1)","V = 5.00 × 22.4 = 112 L"]'::jsonb, '[{"element":"الكتلة المولية","marks":1},{"element":"عدد المولات","marks":1},{"element":"النسبة المولية","marks":1},{"element":"الحجم والوحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الخطوات صحيحة والناتج 112 L"},{"level":"3 درجات","description":"خطأ حسابي بسيط مع صحة الطريقة"},{"level":"2 درجتان","description":"حساب المولات صحيح دون إكمال"},{"level":"1 درجة","description":"الكتلة المولية فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["ضرب الكتلة في 22.4 مباشرة","حساب الكتلة المولية خطأً (مثل 68.0 g/mol بإهمال معامل الأكسجين)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-11T13:13:23.575Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.'),
(2579, null, null, null, 'بما أن الظروف ليست STP نستخدم PV = nRT: n(N2) = PV ÷ RT = (2.00 × 10.0) ÷ (0.0821 × 300) = 0.812 mol. النسبة N2 : NH3 = 1 : 2، إذن n(NH3) = 1.62 mol. MM(NH3) = 14.0 + 3(1.0) = 17.0 g/mol ، m = 1.624 × 17.0 = 27.6 g.', '["إدراك أن الظروف ليست STP واستخدام PV = nRT","حساب مولات N2 = 0.812 mol","استخدام النسبة المولية 1 : 2","حساب الكتلة المولية لـ NH3 والكتلة 27.6 g"]'::jsonb, '["n(N2) = (2.00 × 10.0) ÷ (0.0821 × 300) = 0.812 mol","n(NH3) = 0.812 × 2 = 1.62 mol","MM(NH3) = 17.0 g/mol","m = 1.624 × 17.0 = 27.6 g"]'::jsonb, '[{"element":"استخدام قانون الغاز المثالي","marks":1},{"element":"مولات N2","marks":1},{"element":"النسبة المولية","marks":1},{"element":"الكتلة النهائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الخطوات صحيحة والناتج 27.6 g"},{"level":"3 درجات","description":"طريقة صحيحة مع خطأ حسابي بسيط"},{"level":"2 درجتان","description":"حساب مولات N2 صحيح مع إهمال النسبة المولية (13.8 g)"},{"level":"1 درجة","description":"كتابة PV = nRT فقط"},{"level":"صفر","description":"لا إجابة"}]'::jsonb, '["استخدام 22.4 L/mol رغم أن الظروف ليست STP","إهمال النسبة المولية 1 : 2","التقريب المبكر للمولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-11T13:13:23.575Z"}'::jsonb, 'اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.')
