-- بيانات منصة كيمياء 2-1 — الجزء 7 من 7. نفّذ الأجزاء بالترتيب بعد schema.sql.
-- مولّد آليًا بواسطة scripts/build-supabase-seed.js — لا تعدّله يدويًا.
begin;
on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

select 'question', q.id, 'status', '{"status":"generated"}'::jsonb, '{"status":"approved"}'::jsonb, 'مالك المشروع: اعتماد نهائي بقرار مالك المشروع دون مراجعة تفصيلية لكل سؤال (اجتازت الأسئلة التحقق الآلي فقط). أي تعديل لاحق على ملف أسئلة يُلغي اعتماده تلقائيًا.', 'مالك المشروع', '2026-10-10'::timestamptz
from public.questions q
where q.status = 'approved' and q.origin = 'ai_generated'
  and not exists (select 1 from public.revisions r where r.entity = 'question' and r.entity_id = q.id and r.action = 'status');
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد نهائي لجميع الأهداف بقرار مالك المشروع دون مراجعة تفصيلية لكل هدف. الصياغة المعتمدة هي الصياغة المقترحة، وللأهداف المقترح فصلها تُضم الصياغتان في نص واحد بفاصلة منقوطة.', 'مالك المشروع', '2026-10-11'::timestamptz
from public.objectives o
where o.review_status = 'approved'
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');
select setval(pg_get_serial_sequence('public.questions', 'id'), (select max(id) from public.questions));

commit;
